window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0165", [{"word":"prefer","ipa_uk":"/prɪˈfɜː/","ipa_us":"/prɪˈfɜːr/","definition_zh":"更喜欢；宁愿；优先考虑；提出（控告、索赔）；提拔（旧义）；按自己的判断决定","definition_en":"to like one thing more than another, or to choose it rather than the alternative","core_image":"两扇门并排摆在面前，一只手已经按在右边那扇的把手上，左边的门连碰都没碰","scene":"清早的月台上，通勤者在慢车与快车之间反复比较，Many commuters prefer the slower train because it is quieter.","sceneCN":"这里 prefer 指「在两样东西中更喜欢其中一样，因而选它」（第 1 个义项：在两选项中更喜爱其一）；句意为许多通勤者更喜欢慢车，因为它更安静。图中可辨识物件：并排的两列车门、月台长椅、通勤者的手提包、站牌。","pos":[{"tag":"vt.","zh":"更喜欢；宁愿选择；优先考虑；提出（控告、索赔）；提拔（旧义）"}],"collocations":[{"phrase":"prefer to do sth","zh":"更愿意做某事"},{"phrase":"would prefer","zh":"宁愿；更希望"},{"phrase":"prefer A to B","zh":"喜欢 A 胜过 B"},{"phrase":"strongly prefer","zh":"强烈偏好"},{"phrase":"prefer charges","zh":"提出控告（法律用语）"},{"phrase":"prefer a claim","zh":"提出索赔（法律用语）"}],"forms":[{"label":"三单（he/she/it）","form":"prefers"},{"label":"过去式","form":"preferred"},{"label":"过去分词","form":"preferred"},{"label":"现在分词","form":"preferring"},{"label":"名词（偏好）","form":"preference"},{"label":"形容词（更可取的）","form":"preferable"},{"label":"副词（最好、更可取地）","form":"preferably"}],"derivatives":[{"word":"preference","pos":"n.","zh":"偏好；偏爱；优先权"},{"word":"preferable","pos":"adj.","zh":"更可取的；更好的"},{"word":"preferably","pos":"adv.","zh":"最好；更可取地"},{"word":"preferential","pos":"adj.","zh":"优先的；优待的"},{"word":"preferment","pos":"n.","zh":"提拔；晋升"}],"senses":[{"no":"01","title":"Like one thing more than another","titleCN":"更喜欢某一样东西","definition":"to like or want one thing more than another","definitionCN":"比另一件东西更喜欢或更想要某一件","example":"She prefers tea to coffee.","exampleCN":"比起咖啡，她更喜欢茶。","why":"Prae- means before and ferre means to carry, so the liked thing is carried in front of the other in one's esteem.","whyCN":"prae- 意为「在前」，ferre 意为「搬运」，被喜欢的那样东西于是被搬到另一样东西前面，排在心上更靠前的位置。"},{"no":"02","title":"Choose one option rather than the other","titleCN":"在两者中选其一","definition":"to choose one course or option rather than another because it suits one better","definitionCN":"因为更合心意而选择一种做法或选项，而不是另一种","example":"We preferred to walk rather than wait for the bus.","exampleCN":"我们宁愿走路，也不想等公交。","why":"Once one thing is placed in front, the hand follows it, so preference turns into a choice between courses of action.","whyCN":"一样东西一旦被放到前面，手就会跟着它走，于是「更喜欢」变成了在几种做法之间的选择。"},{"no":"03","title":"Give precedence to a claim or method","titleCN":"给予某项主张或方法优先地位","definition":"to treat one claim, method or person as more important than the others","definitionCN":"把某项主张、方法或某个人看得比其他更重","example":"The committee preferred the cheaper design.","exampleCN":"委员会更倾向于那个造价更低的方案。","why":"Ranking is placing in a row, and what is carried to the front of the row is what counts first.","whyCN":"排序就是把东西排成一列，被搬到最前面的那一个，就是最先被考虑的那一个。"},{"no":"04","title":"Bring a charge or claim before a court","titleCN":"向法庭提出控告或主张","definition":"to bring a charge, claim or request formally before a court or an authority","definitionCN":"正式向法庭或主管机关提出控告、索赔或请求","example":"The prosecutor preferred charges of fraud against the firm.","exampleCN":"检察官对这家公司提出了欺诈指控。","why":"Legal Latin kept the literal sense of bringing something forward, so a charge is carried before the bench.","whyCN":"法律拉丁语保留了「把东西搬到前面」的字面意思，因此控告就是被搬到法官席前的东西。"},{"no":"05","title":"Advance someone to a higher office","titleCN":"把某人提拔到更高的职位","definition":"to promote someone to a higher position or a more valuable office","definitionCN":"把某人提升到更高或更优厚的职位","example":"The bishop was preferred to a wealthier see.","exampleCN":"这位主教被提拔到一个更富裕的教区。","why":"A person raised above his peers is literally carried in front of them in rank.","whyCN":"一个人被抬到同辈之上，在位次上就是被搬到了他们前面。"},{"no":"06","title":"Regard one explanation as more likely","titleCN":"认为某一种解释更可能成立","definition":"to judge one explanation, reading or hypothesis as more likely than another","definitionCN":"判断某一种解释、读法或假说比另一种更可能","example":"Historians prefer the simpler reading of the letter.","exampleCN":"历史学家更认可对这封信较为简单的解读。","why":"The mind also carries things forward: among competing readings, one is placed ahead of the rest.","whyCN":"心思也会搬东西：在几种相互竞争的解释里，总有一种被放到其余之前。"},{"no":"07","title":"Express a softer wish about another person's action","titleCN":"委婉表达希望对方如何做","definition":"to say politely that one would rather have something done in a particular way","definitionCN":"礼貌地表示自己更希望某事以某种方式进行","example":"I would prefer it if you called before coming.","exampleCN":"我希望你来之前先打个电话。","why":"The comparative force softens a request: the speaker names a preferred arrangement instead of giving an order.","whyCN":"比较的意味让请求变软：说话人只是说出更合意的安排，而不是下命令。"},{"no":"08","title":"Decide at one's own discretion","titleCN":"按自己的判断自行决定","definition":"to decide according to one's own judgment, especially in formal rules that leave the choice open","definitionCN":"按自己的判断作出决定，尤用于把选择权留给当事人的正式规则","example":"The trustee may, as he prefers, sell the land at auction.","exampleCN":"受托人可以按自己的判断，以拍卖方式出售这块土地。","why":"The oldest sense of placing one thing before another survives as the freedom to put whichever course one likes first.","whyCN":"「把某样东西放到前面」这个最古老的意思，在这里留存为「可以把中意的做法排在前面」的自由。"}],"etymology":{"intro":{"en":"Prefer comes through Old French from Latin praeferre, built on prae- meaning before and ferre meaning to carry or bear. Dates are approximate.","cn":"prefer 经古法语来自拉丁语 praeferre，由 prae-「在前」与 ferre「搬运、承载」构成。年代均为约数。"},"items":[{"era":"LATIN FERRE","en":"Ferre meant to carry or bear, and its past participle latus stands behind English words such as relate and translate. Its older source is generally reconstructed as a root meaning to carry.","cn":"ferre 意为「搬运、承载」，其过去分词 latus 支撑着 relate、translate 等英语词。它更早的来源通常被重构为一个表示「搬运」的词根。"},{"era":"LATIN PRAEFERRE","en":"Prae- meaning before plus ferre produced praeferre, to place or carry in front, and by extension to value one thing above another.","cn":"表示「在前」的 prae- 加 ferre 构成 praeferre，意为「放到前面、搬在前面」，并引申为把某物看得比另一物更重。"},{"era":"OLD FRENCH PREFERER","en":"Old French preferer brought the verb into English in the late fourteenth century, at first in the sense of putting a person or thing before others.","cn":"古法语 preferer 在十四世纪后期把这个动词带入英语，最初指把人或物放到其他之前。"},{"era":"ENGLISH RANKING","en":"By the sixteenth century the verb named esteeming one thing above another, and legal usage used it for bringing a charge or request forward.","cn":"到十六世纪，这个动词已指看重某物胜过另一物，法律用语则用它表示把控告或请求呈到前面。"},{"era":"MODERN TASTE","en":"The everyday sense of liking one thing better than another settled in ordinary speech, while the legal and church senses stayed in specialized use.","cn":"「更喜欢某物」这一日常义在普通口语中固定下来，而法律与教会用语里的意思则留在专门场合。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation is not fixed, and the deeper Indo-European root of ferre is a reconstructed form rather than a recorded word.","cn":"来源不确定：英语中最早的书证年代没有定论；ferre 更深的印欧语词根属重构形式，并非有记录的真实词形。"}]},"similar":{"note":{"en":"The first group shares the Latin verb ferre but differs in prefix; the second holds words for liking and picking that are close in use. One look-alike has a different origin.","cn":"第一组共享拉丁动词 ferre，只是前缀不同；第二组是用法相近的「喜爱、挑选」类词。其中有一个形似词来源不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"refer","ipa":"/rɪˈfɜː/","tag":"carry back","definition":"Re- meaning back plus ferre: to carry a matter back to a source, hence to direct attention or consult.","definitionCN":"re-「向后」加 ferre：把某事带回源头，因而指指向某处或查阅。"},{"word":"confer","ipa":"/kənˈfɜː/","tag":"carry together","definition":"Con- meaning together plus ferre: to bring matters together, hence to consult or to bestow.","definitionCN":"con-「共同」加 ferre：把事情带到一处，因而指商议或授予。"},{"word":"differ","ipa":"/ˈdɪfə/","tag":"carry apart","definition":"Dis- meaning apart plus ferre: to carry things in different directions, hence to be unlike.","definitionCN":"dis-「分开」加 ferre：把东西带向不同方向，因而指彼此不同。"},{"word":"proffer","ipa":"/ˈprɒfə/","tag":"different origin","definition":"From Old French poroffrir, built on offrir and Latin offerre meaning to bring before; it looks like prefer but the prefix and source differ.","definitionCN":"来自古法语 poroffrir，由 offrir 与拉丁语 offerre「呈到面前」构成；它与 prefer 形似，但前缀与来源都不同。"}]},{"heading":"NEAR MEANING","entries":[{"word":"favour","ipa":"/ˈfeɪvə/","tag":"lean toward","definition":"To treat one person or option with special approval; it stresses approval rather than a comparison between two things.","definitionCN":"带着特别的认可对待某个人或某种选项；它强调认可，而不是两物之间的比较。"},{"word":"choose","ipa":"/tʃuːz/","tag":"act on the preference","definition":"To pick one option; prefer names the leaning, choose names the act.","definitionCN":"挑出一个选项；prefer 命名的是倾向，choose 命名的是动作。"},{"word":"opt","ipa":"/ɒpt/","tag":"formal choice","definition":"To make a choice, often in a formal or deliberate context; it does not carry the comparative force of liking one more than another.","definitionCN":"作出选择，常用于正式或慎重的场合；它不带有「比另一物更喜欢」的比较意味。"},{"word":"like","ipa":"/laɪk/","tag":"plain feeling","definition":"The everyday verb for finding something pleasant; prefer adds a comparison with something else.","definitionCN":"表示觉得某物令人愉快的日常动词；prefer 则加上了与另一物的比较。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the real root, the real family and the phrases the verb keeps.","cn":"正常联想：真实的前缀、真实的词根、真实的同族词，以及这个动词实际常用的搭配。"},"normal":[{"en":"prae- meaning before plus ferre meaning carry: to carry one thing in front of another.","cn":"prae-「在前」加 ferre「搬运」：把一样东西搬到另一样前面。"},{"en":"The family runs prefer, preference, preferable, preferably, preferential and preferment.","cn":"同族词包括 prefer（更喜欢）、preference（偏好）、preferable（更可取的）、preferably（更可取地）、preferential（优先的）、preferment（提拔）。"},{"en":"Fixed phrases mark the comparison: prefer tea to coffee, prefer to wait, strongly prefer.","cn":"固定搭配标出比较关系：喜欢茶胜过咖啡、宁愿等待、强烈偏好。"},{"en":"The same root runs through refer, confer, differ, infer and transfer, each with its own prefix.","cn":"同一词根贯穿 refer、confer、differ、infer、transfer，各自配上不同的前缀。"},{"en":"Legal usage keeps the old forward motion: to prefer charges is to bring them before a court.","cn":"法律用法保住旧的「向前搬」动作：提出控告就是把控告呈到法庭前。"}],"abstract":[{"en":"Picture two doors and a hand already resting on the right handle.","cn":"想象两扇门，一只手已经按在右边那扇的把手上。"},{"en":"Picture a clerk placing one file on top of a stack.","cn":"想象一名职员把一份卷宗放到整叠文件的最上面。"},{"en":"Picture a compass needle that always settles a little east of north.","cn":"想象一枚罗盘针，每次都停在正北略偏东的位置。"}]},"examples":[{"en":"Most readers prefer the shorter edition.","cn":"多数读者更喜欢篇幅较短的版本。"},{"en":"She preferred to say nothing until the facts were clear.","cn":"在事实清楚之前，她宁愿什么都不说。"},{"en":"The court preferred charges against two officers.","cn":"法庭对两名警官提出了指控。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「普瑞佛」——先把喜欢的那件捧到前面 → prefer 更喜欢、宁愿","word":"prefer"},"root":"拉丁 praeferre「放到前面、看重」= prae-「在前」+ ferre「搬运、承载」；ferre 的印欧语来源通常被重构为表示「搬运」的词根。英语 prefer 经古法语进入。","sensesIntro":{"en":"Eight senses follow one gesture: one thing is carried in front of another, and that placement is applied to taste, action, ranking, legal charges, offices, explanations, polite wishes and finally to open discretion.","cn":"八个义项沿同一个动作展开：把一样东西搬到另一样前面，这个摆放再依次用于口味、行动、排序、法律控告、职位、解释、礼貌愿望，最后用于留有余地的自行裁量。"},"semanticMap":{"core":{"en":"CORE IMAGE: two things offered side by side, and one is carried to the front of the hand.","cn":"核心意象：两样东西并排摆在面前，其中一样被搬到手上更靠前的位置。"},"chain":["PLACE SIDE BY SIDE","CARRY TO THE FRONT","LIKE THE FRONT ONE","RANK IT FIRST","BRING IT FORWARD","LEAN TOWARD IT"],"branches":[{"senses":"01 · 02","en":"TASTE AND ACTION: the thing carried to the front is first liked, then taken.","cn":"口味与行动：被搬到前面的东西先被喜欢，再被拿走。"},{"senses":"03","en":"RANKING: precedence is the same placement seen as order rather than desire.","cn":"排序：优先地位是同一种摆放，只是被看成次序而非喜好。"},{"senses":"04 · 05","en":"FORMAL FORWARDING: a charge or a candidate is brought before the bench or above one's peers.","cn":"正式呈交：控告或人选被带到法官席前，或被抬到同辈之上。"},{"senses":"06","en":"READING: among explanations the mind puts one ahead of the rest.","cn":"解读：在几种解释中，心思把其中一种放到其余之前。"},{"senses":"07 · 08","en":"SOFTENED WILL: a polite wish and a formal discretion both leave the preferred course to the speaker.","cn":"柔化的意愿：礼貌的愿望与正式的裁量，都把中意的做法留给说话人自己。"}]},"affixes":{"intro":{"en":"Prefer can be read from a Latin prefix and a Latin verb that also build a large English family.","cn":"prefer 可以按一个拉丁前缀与一个拉丁动词逐段读出，这两部分还构成一大族英语词。"},"latinIntro":{"en":"Latin ferre gives refer, confer, differ, infer, transfer and prefer; prae- adds the sense of being in front.","cn":"拉丁语 ferre 衍生 refer、confer、differ、infer、transfer 与 prefer；prae- 加上「在前面」的意思。"},"items":[{"word":"prae-","structure":"prae- (Latin prefix, before, in front)","meaning":"before; in front","meaningCN":"在前；在前面","example":"The prefix also appears in predict and precede.","exampleCN":"这个前缀也出现在 predict（预测）与 precede（在……之前）里。"},{"word":"ferre","structure":"ferre (Latin verb, to carry, bear)","meaning":"to carry; to bear","meaningCN":"搬运；承载","example":"Its participle latus underlies translate and relate.","exampleCN":"它的过去分词 latus 是 translate 与 relate 的词源基础。"},{"word":"prefer","structure":"prae- + ferre","meaning":"to carry in front, hence to value more","meaningCN":"搬到前面，因而更看重","example":"She prefers the earlier train.","exampleCN":"她更喜欢早一班的那趟车。"},{"word":"preference","structure":"prefer + -ence (noun of state or quality)","meaning":"the state of liking one thing more","meaningCN":"偏好；更喜爱某物的状态","example":"Her preference for quiet rooms is well known.","exampleCN":"她偏爱安静的房间，这是众所皆知的。"},{"word":"preferable","structure":"prefer + -able (worthy of being chosen)","meaning":"more worth choosing","meaningCN":"更可取的；更值得选的","example":"The earlier flight is preferable in winter.","exampleCN":"冬天早一班的航班更可取。"},{"word":"preferably","structure":"preferable + -ly (adverb ending)","meaning":"if the choice were open, in the better way","meaningCN":"最好；更可取地","example":"Bring cash, preferably in small notes.","exampleCN":"带上现金，最好是小面额的。"},{"word":"preferential","structure":"prefer + -ential (relational adjective)","meaning":"giving one party an advantage","meaningCN":"优先的；给予一方优待的","example":"Members get preferential rates.","exampleCN":"会员享有优惠费率。"},{"word":"preferment","structure":"prefer + -ment (result or act)","meaning":"an advance to a higher post","meaningCN":"提拔；晋升","example":"His preferment came after years of service.","exampleCN":"他在多年任职之后获得提拔。"},{"word":"proffer","structure":"pro- + offerre (to bring before), a different formation","meaning":"to hold out something for acceptance","meaningCN":"递上；提供","example":"She proffered a handwritten note.","exampleCN":"她递上一张手写的便条。"}],"latinEntries":[{"word":"ferre","structure":"ferre, tuli, latum (verb, irregular)","meaning":"to carry, bear","meaningCN":"搬运；承载"},{"word":"praeferre","structure":"praeferre, praetuli, praelatum (verb, irregular)","meaning":"to place before, value above","meaningCN":"放到前面；更看重"},{"word":"latus","structure":"latus, -a, -um (past participle of ferre)","meaning":"carried, borne","meaningCN":"被搬运的；被承载的"},{"word":"relatio","structure":"relatio, relationis (f., third declension)","meaning":"a bringing back, a report","meaningCN":"带回；汇报"}],"derivatives":[{"word":"preference","structure":"prefer + -ence (state) → the state of holding one thing above another","meaning":"a greater liking for one thing","meaningCN":"偏好；偏爱"},{"word":"preferable","structure":"prefer + -able (fit to be chosen) → fit to be chosen rather than the other","meaning":"more worth choosing","meaningCN":"更可取的"},{"word":"preferably","structure":"preferable + -ly (adverb) → in the more desirable way","meaning":"if possible; by preference","meaningCN":"最好；更可取地"},{"word":"preferential","structure":"prefer + -ential (relational adjective) → marked by giving advantage to one side","meaning":"giving one side an advantage","meaningCN":"优先的；优待的"},{"word":"preferment","structure":"prefer + -ment (result) → the result of being raised above others","meaning":"promotion to a higher post","meaningCN":"提拔；晋升"}]}},{"word":"choice","ipa_uk":"/tʃɔɪs/","ipa_us":"/tʃɔɪs/","definition_zh":"选择；选项；可供挑选的范围；被选中的人或物；选择权；精选的；上等的","definition_en":"the act of choosing, or the range of things from which one can choose","core_image":"早餐桌上摆着三只碗，一只手悬在中间那只上方，另外两只被轻轻推远","scene":"清晨的厨房里，母亲把三只碗推到孩子面前，The child's choice was the bowl with the red lid.","sceneCN":"这里 choice 指「从若干选项中挑出的那一个」（第 4 个义项：被选中的事物）；句意为孩子挑中的是带红盖的那只碗。图中可辨识物件：三只碗、红盖子、木桌、孩子的手。","pos":[{"tag":"n.","zh":"选择；选项；选择范围；选择权；被选中的人或物"},{"tag":"adj.","zh":"精选的；上等的"}],"collocations":[{"phrase":"make a choice","zh":"作出选择"},{"phrase":"have no choice","zh":"别无选择"},{"phrase":"a wide choice of","zh":"种类繁多的选择"},{"phrase":"freedom of choice","zh":"选择自由"},{"phrase":"by choice","zh":"出于自愿"},{"phrase":"choice of words","zh":"措辞的选择"}],"forms":[{"label":"复数","form":"choices"},{"label":"比较级（作形容词，较少用）","form":"choicer"},{"label":"最高级（作形容词，较少用）","form":"choicest"},{"label":"动词（选择）","form":"choose"},{"label":"名词（挑选者）","form":"chooser"}],"derivatives":[{"word":"choose","pos":"v.","zh":"选择；挑选"},{"word":"chooser","pos":"n.","zh":"挑选者"},{"word":"choosy","pos":"adj.","zh":"挑剔的"},{"word":"choosiness","pos":"n.","zh":"挑剔"}],"senses":[{"no":"01","title":"The act of picking one thing","titleCN":"挑选这一动作","definition":"the act of selecting one thing or person from two or more possibilities","definitionCN":"从两个或更多可能中挑出一个事物或一个人的动作","example":"The choice took less than a minute.","exampleCN":"挑选的过程不到一分钟。","why":"The noun first names the act, and only afterwards the thing that the act produces.","whyCN":"这个名词先命名动作本身，之后才命名动作产生的结果。"},{"no":"02","title":"An option that is open to you","titleCN":"摆在面前可供选择的一项","definition":"one of the things that a person is able to pick","definitionCN":"一个人能够挑选的若干事物之一","example":"You have three choices: stay, leave, or wait.","exampleCN":"你有三种选择：留下、离开，或者等待。","why":"Once the act is named, the items the act ranges over take the same name.","whyCN":"动作有了名称之后，动作所覆盖的那些项目也用同一个词来称呼。"},{"no":"03","title":"The range of things offered","titleCN":"可供挑选的范围或品种","definition":"the variety or selection of things that is offered to someone","definitionCN":"提供给某人的可供挑选的品种或范围","example":"The shop offers a wide choice of teas.","exampleCN":"这家店有种类繁多的茶可供挑选。","why":"A wide range is simply the set of options seen as one offering.","whyCN":"宽广的范围不过是把全部选项看成一份完整的供应。"},{"no":"04","title":"The thing or person that was picked","titleCN":"被挑中的事物或人","definition":"the person or thing that has been selected","definitionCN":"已经被选中的那个人或那件事物","example":"Her choice was the smallest room.","exampleCN":"她挑中的是最小的那间房。","why":"The result of the act carries the name of the act, as the picked thing is the choice made visible.","whyCN":"动作的结果沿用了动作的名称，因为被挑中之物就是「选择」看得见的样子。"},{"no":"05","title":"The freedom or power to decide","titleCN":"决定的选择权","definition":"the right or ability to decide for oneself","definitionCN":"为自己作决定的权利或能力","example":"Workers had little choice about the shift.","exampleCN":"工人在排班这件事上几乎没有选择权。","why":"A capacity is the act considered as something a person possesses.","whyCN":"能力就是把动作看成一个人所拥有的东西。"},{"no":"06","title":"Of noticeably good quality","titleCN":"品质明显优良的","definition":"of a quality clearly above the ordinary, especially of food","definitionCN":"品质明显高于寻常的，尤指食物","example":"The market sells choice vegetables.","exampleCN":"这个市场出售上等的蔬菜。","why":"A thing picked out from the rest is a thing above the rest, so the noun of selection became an adjective of quality.","whyCN":"从其余之中被挑出来的东西，就是高于其余的东西，于是表示挑选的名词变成了表示品质的形容词。"},{"no":"07","title":"Selected with care for a purpose","titleCN":"为某种用途精心挑选的","definition":"chosen with care, often for a particular purpose or effect","definitionCN":"经过仔细挑选，常为某种用途或效果","example":"He kept choice quotations in a notebook.","exampleCN":"他把精挑细选的引文记在笔记本里。","why":"The past-participle force of the source survives in the adjective: the thing has been picked and is therefore select.","whyCN":"来源中过去分词的力量留在形容词里：这东西已经被挑过，因此是精选的。"},{"no":"08","title":"Choice treated as a principle","titleCN":"被当作原则的选择自由","definition":"the principle that a person should be free to decide, especially in public debate","definitionCN":"认为个人应当自由作决定的原则，尤见于公共讨论","example":"The debate turned on choice in schooling.","exampleCN":"这场辩论的焦点是上学方面的选择自由。","why":"An ordinary capacity becomes a value when arguments treat it as something a good society must protect.","whyCN":"当论证把一种普通能力看成良好社会必须保护的东西时，这种能力就变成了价值。"}],"etymology":{"intro":{"en":"Choice and choose come from the same Germanic stock, carried into English through Old French and Old English respectively. Dates are approximate.","cn":"choice 与 choose 同出日耳曼语词干，分别经古法语与古英语进入英语。年代均为约数。"},"items":[{"era":"OLD FRENCH CHOIS","en":"The noun chois, meaning a choice, entered English around 1300 from Old French, where it already stood apart from the verb choisir.","cn":"意为「选择」的名词 chois 约在十三世纪末从古法语进入英语，在法语里它已与动词 choisir 分开。"},{"era":"FRANKISH SOURCE","en":"Old French choisir is generally thought to come from Frankish kausjan or a similar Germanic verb; that form is a reconstruction and is not recorded in writing.","cn":"古法语 choisir 一般被认为是来自法兰克语 kausjan 或相近的日耳曼语动词；这一词形属重构形式，没有书面记录。"},{"era":"GERMANIC FAMILY","en":"The same stock appears in Old English ceosan, Old High German kiosan and Old Norse kjosa, all meaning to test or to choose.","cn":"同一词干出现在古英语 ceosan、古高地德语 kiosan 与古诺斯语 kjosa 中，都表示「检验」或「选择」。"},{"era":"ADJECTIVE SENSE","en":"The adjective use, first meaning carefully selected and later meaning of superior quality, grew out of the noun in the late medieval period.","cn":"形容词用法先表示「仔细挑选过的」，后来表示「品质优良的」，是中世纪后期从名词义生长出来的。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact Germanic form behind Old French choisir is unsettled, and reference works give different first dates for the adjective.","cn":"来源不确定：古法语 choisir 背后的确切日耳曼语词形尚无定论，各家参考资料对形容词首见年代的说法也不一致。"}]},"similar":{"note":{"en":"The first group shares the Germanic stock of choice but differs in word class; the second holds words that also name a selection or an alternative. One look-alike belongs to a different root.","cn":"第一组共享 choice 的日耳曼语词干，只是词性不同；第二组也指选择或替代项。其中有一个形似词属于别的词根。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"choose","ipa":"/tʃuːz/","tag":"same root, verb","definition":"The verb of the same stock: choice names the act or the thing, choose performs it.","definitionCN":"同一词干的动词：choice 命名动作或事物，choose 则是去执行这个动作。"},{"word":"choosy","ipa":"/ˈtʃuːzi/","tag":"same root, adjective","definition":"Fussy about what one accepts, formed from choose with an ending meaning inclined to.","definitionCN":"对接受什么很挑剔，由 choose 加一个表示「倾向于」的词尾构成。"},{"word":"chooser","ipa":"/ˈtʃuːzə/","tag":"same root, person","definition":"One who chooses; it names the person, while choice names the act or the option.","definitionCN":"作出挑选的人；它命名人，而 choice 命名动作或选项。"},{"word":"chorus","ipa":"/ˈkɔːrəs/","tag":"different origin","definition":"From Greek choros, a dance or band of singers; the spelling looks close to choice but the root is unrelated.","definitionCN":"来自希腊语 choros「歌舞队」；拼写与 choice 相近，但词根无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"option","ipa":"/ˈɒpʃn/","tag":"one item on the list","definition":"A single thing that may be chosen; choice can also name the whole range.","definitionCN":"可以被挑选的单独一项；choice 还能指整个范围。"},{"word":"alternative","ipa":"/ɔːlˈtɜːnətɪv/","tag":"the other one","definition":"One of two things that stand in place of each other; choice is the wider word for the act or the set.","definitionCN":"两个可以彼此替代的事物之一；choice 是更宽的词，可指动作或整套选项。"},{"word":"selection","ipa":"/sɪˈlekʃn/","tag":"the set or the act","definition":"A collection of things picked out, or the act of picking; choice stresses the decision, selection stresses the gathering.","definitionCN":"被挑出的一组东西，或挑选的动作；choice 强调决定，selection 强调汇拢。"},{"word":"preference","ipa":"/ˈprefrəns/","tag":"the leaning","definition":"A greater liking for one thing; a choice is the decision that may follow from it.","definitionCN":"对某物更强的喜爱；choice 则是由此可能作出的决定。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real word family, the real phrases and the adjective sense that still lives in ordinary usage.","cn":"正常联想：真实的同族词、真实的固定搭配，以及至今仍活在日常用法里的形容词义。"},"normal":[{"en":"The verb choose and the noun choice are one family: choose the act, choice the act or the thing.","cn":"动词 choose 与名词 choice 是一家：choose 是动作，choice 是动作或事物。"},{"en":"The family runs choose, chooser, choosy and choosiness.","cn":"同族词包括 choose（选择）、chooser（挑选者）、choosy（挑剔的）、choosiness（挑剔）。"},{"en":"Fixed phrases mark the field: make a choice, have no choice, a wide choice of, freedom of choice.","cn":"固定搭配标出使用范围：作出选择、别无选择、种类繁多的选择、选择自由。"},{"en":"The adjective choice means picked out, hence better than the rest, a sense still alive in choice vegetables.","cn":"形容词 choice 意为「被挑出来的」，因而「优于其余」，这个意思仍活在「上等蔬菜」的说法里。"},{"en":"By choice means because one decided so, not because one was forced.","cn":"by choice 意为出于自己的决定，而不是被迫。"}],"abstract":[{"en":"Picture three bowls and one hand hovering above the middle one.","cn":"想象三只碗，一只手悬在中间那只上方。"},{"en":"Picture a menu with one line circled in pencil.","cn":"想象一份菜单，其中一行被铅笔圈了起来。"},{"en":"Picture a road fork where one branch has been marked on the map.","cn":"想象一条岔路，地图上其中一支已被标出。"}]},"examples":[{"en":"The menu offered a choice of three soups.","cn":"菜单上有三种汤可供选择。"},{"en":"He made his choice without looking at the price.","cn":"他没看价格就作了选择。"},{"en":"The shop is known for choice fruit.","cn":"这家店以上等水果著称。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「挑伊斯」——在一排东西里挑出中意的那一个 → choice 选择","word":"choice"},"root":"与 choose 同出日耳曼语词干，经古法语 chois 进入英语；其更早的法兰克语词形属重构形式。","sensesIntro":{"en":"Eight senses follow one act of picking: the act itself, the options before it, the range they form, the thing taken, the power to take it, the quality of what is picked, careful selection and finally choice treated as a public value.","cn":"八个义项沿同一次挑选展开：挑选这个动作、眼前的名目、名目构成的整体范围、被拿走的那一件、拿走它的权力、被挑中之物的品质、精心的挑选，最后是作为公共价值的选择。"},"semanticMap":{"core":{"en":"CORE IMAGE: three bowls on a table, one hand hovering above the middle one while the other two are pushed aside.","cn":"核心意象：桌上摆着三只碗，一只手悬在中间那只上方，另外两只被推到一旁。"},"chain":["ACT OF PICKING","OPTION ON OFFER","RANGE OF OFFERS","THING PICKED","POWER TO DECIDE","QUALITY OF THE PICKED"],"branches":[{"senses":"01","en":"THE ACT: naming the moment of selection before naming anything selected.","cn":"动作：先命名挑选发生的那一刻，再命名被挑选出来的东西。"},{"senses":"02 · 03","en":"THE FIELD: one option and the whole range are the same set seen close up and from above.","cn":"场域：单个选项与整个范围是同一套事物的近看与俯看。"},{"senses":"04","en":"THE RESULT: what was picked carries the name of the picking.","cn":"结果：被挑中之物沿用了挑选的名称。"},{"senses":"05 · 08","en":"THE RIGHT: a capacity becomes a value when a society argues about it.","cn":"权利：当社会为此争论时，一种能力就变成了价值。"},{"senses":"06 · 07","en":"THE QUALITY: to be picked out is to be above the rest, so selection turns into praise.","cn":"品质：被挑出来就意味着高于其余，于是挑选变成了称赞。"}]},"affixes":{"intro":{"en":"Choice belongs to a Germanic family whose verb survives as choose, and the noun also feeds a small adjective group.","cn":"choice 属于一个日耳曼语词族，其动词形态留存为 choose，这个名词还衍生出一小类形容词。"},"latinIntro":{"en":"Choice has no Latin ancestor and no Latin cognate; Latin verbs for choosing, such as eligere and seligere, supply elect and select but belong to other families.","cn":"choice 没有拉丁语祖词，也没有拉丁同族词；拉丁语中表示选择的 eligere 与 seligere 分别产生 elect 与 select，但属于别的词族。因此拉丁词族条目留空。"},"items":[{"word":"ceosan","structure":"Old English ceosan (strong verb)","meaning":"to choose, test, taste","meaningCN":"选择；检验；品尝","example":"The Old English verb already joined choosing with testing.","exampleCN":"这个古英语动词已经把「挑选」与「检验」连在一起。"},{"word":"chose","structure":"choose + old strong past inflection","meaning":"picked in the past","meaningCN":"过去挑中了","example":"She chose the quieter road.","exampleCN":"她挑了那条更安静的路。"},{"word":"chosen","structure":"choose + old strong participle ending","meaning":"having been picked","meaningCN":"已被挑中的","example":"The chosen candidate starts on Monday.","exampleCN":"被选中的人星期一入职。"},{"word":"choice","structure":"Old French chois (noun of choosing)","meaning":"the act or the thing chosen","meaningCN":"选择；被选中之物","example":"The choice was made in silence.","exampleCN":"选择是在沉默中作出的。"},{"word":"chooser","structure":"choose + -er (one who acts)","meaning":"a person who picks","meaningCN":"作挑选的人","example":"The chooser must live with the result.","exampleCN":"作挑选的人必须承担结果。"},{"word":"choosy","structure":"choose + -y (inclined to)","meaning":"hard to please about what one accepts","meaningCN":"对接受的东西很挑剔","example":"She is choosy about her coffee.","exampleCN":"她对咖啡很挑剔。"},{"word":"choosiness","structure":"choosy + -ness (quality)","meaning":"the quality of being hard to please","meaningCN":"挑剔的品质","example":"His choosiness slowed the search.","exampleCN":"他的挑剔让寻找变慢了。"},{"word":"choosing","structure":"choose + -ing (action noun)","meaning":"the process of picking","meaningCN":"挑选的过程","example":"Choosing takes longer than buying.","exampleCN":"挑比买花的时间更长。"}],"latinEntries":[],"derivatives":[{"word":"chooser","structure":"choose + -er (agent) → the person who performs the pick","meaning":"one who chooses","meaningCN":"挑选者"},{"word":"choosy","structure":"choose + -y (inclined) → inclined to be hard to please","meaning":"fussy in choosing","meaningCN":"挑剔的"},{"word":"choosiness","structure":"choosy + -ness (quality) → the state of being fussy","meaning":"fussiness in choosing","meaningCN":"挑剔"},{"word":"chosen","structure":"choose + strong participle → the state of having been picked","meaning":"selected","meaningCN":"被选中的"}]}},{"word":"choose","ipa_uk":"/tʃuːz/","ipa_us":"/tʃuːz/","definition_zh":"选择；挑选；决定；宁愿；选举；选定（路线、专业等）","definition_en":"to pick one person or thing from two or more possibilities","core_image":"一串钥匙在手里摊开，最后只有一把被从环上解下带走","scene":"旅店前台把一串房间钥匙推过来，The guest chooses the key with the blue tag.","sceneCN":"这里 choose 指「从若干可能中挑出一个」（第 1 个义项：从多个选项中作出挑选）；句意为客人挑了挂蓝牌的那把钥匙。图中可辨识物件：钥匙串、蓝牌、木质前台、登记簿。","pos":[{"tag":"vt.","zh":"选择；挑选；决定；宁愿；选举"},{"tag":"vi.","zh":"作出选择；决定"}],"collocations":[{"phrase":"choose between","zh":"在……之间作选择"},{"phrase":"choose from","zh":"从……中挑选"},{"phrase":"choose to do sth","zh":"决定做某事"},{"phrase":"choose wisely","zh":"明智地选择"},{"phrase":"choose a career","zh":"选择职业"},{"phrase":"pick and choose","zh":"挑三拣四；任意挑选"}],"forms":[{"label":"三单（he/she/it）","form":"chooses"},{"label":"过去式","form":"chose"},{"label":"过去分词","form":"chosen"},{"label":"现在分词","form":"choosing"},{"label":"名词（选择）","form":"choice"},{"label":"名词（挑选者）","form":"chooser"},{"label":"形容词（挑剔的）","form":"choosy"}],"derivatives":[{"word":"choice","pos":"n.","zh":"选择；选项"},{"word":"chooser","pos":"n.","zh":"挑选者"},{"word":"choosy","pos":"adj.","zh":"挑剔的"},{"word":"choosiness","pos":"n.","zh":"挑剔"},{"word":"chosen","pos":"adj.","zh":"被选中的"}],"senses":[{"no":"01","title":"Select one from several","titleCN":"从若干中挑出一个","definition":"to pick one person or thing from two or more possibilities","definitionCN":"从两个或更多可能中挑出一个人或一样东西","example":"She chose the smaller of the two rooms.","exampleCN":"她挑了那两间房当中较小的那间。","why":"The old verb meant to test and then take, so choosing begins with examining what lies before the hand.","whyCN":"这个古老动词的意思是先检验再拿走，因此挑选始于端详摆在手前的东西。"},{"no":"02","title":"Decide to act in a certain way","titleCN":"决定采取某种做法","definition":"to decide to do something, especially when other courses are open","definitionCN":"决定去做某事，尤在其他做法也可行时","example":"She chose to say nothing until the facts were clear.","exampleCN":"她决定在事实清楚之前什么都不说。","why":"Choosing a course of action is picking among ways of acting, not among objects.","whyCN":"选择一种做法，是在几种行动方式里挑选，而不是在物件里挑选。"},{"no":"03","title":"Prefer one thing over another","titleCN":"更喜爱其中之一","definition":"to take one thing rather than another because one likes it better","definitionCN":"因为更喜欢某物而取它而非另一物","example":"He chose the older method over the new one.","exampleCN":"他选了旧方法，而不是新方法。","why":"A preference becomes a choice the moment the hand moves.","whyCN":"偏好一旦让手动起来，就变成了选择。"},{"no":"04","title":"Elect someone by vote","titleCN":"以投票选出某人","definition":"to select a person for an office or position by voting","definitionCN":"通过投票把人选担任某个职位或岗位","example":"The members chose a new treasurer.","exampleCN":"成员们选出了新的司库。","why":"A group performs the same pick, only the hands are counted instead of one hand moving.","whyCN":"一群人做同一件事，只是数的不是一只手而是许多票。"},{"no":"05","title":"Settle on a career or a path","titleCN":"选定一条职业或人生道路","definition":"to decide on a course of study, career or way of life","definitionCN":"决定要走的学业方向、职业或生活方式","example":"At eighteen she chose medicine.","exampleCN":"十八岁时她选择了学医。","why":"One large choice replaces a series of small ones, and its result lasts for years.","whyCN":"一个大选择取代了许多小选择，它的结果会持续多年。"},{"no":"06","title":"See fit, in formal usage","titleCN":"正式用语中表示「认为合适」","definition":"to decide as one thinks right, in formal or older usage","definitionCN":"按自己认为合适的方式作决定，见于正式或较早的用法","example":"The court may choose to adjourn until Monday.","exampleCN":"法庭可以自行决定休庭到下周一。","why":"When a rule leaves the decision open, choosing means judging what fits the case.","whyCN":"当规则把决定权留空时，选择就意味着判断什么才合宜。"},{"no":"07","title":"Pick out goods and take them","titleCN":"挑出货物并拿走","definition":"to select goods from what is offered and take them as one's own","definitionCN":"从提供的货物中挑出并据为己有","example":"Buyers choose the beans by hand.","exampleCN":"买家用手挑出豆子。","why":"This is the oldest bodily sense: the hand tests, then removes the wanted item from the pile.","whyCN":"这是最古老的身体动作：手先试，再把想要的那一件从堆里拿走。"},{"no":"08","title":"Select members of a set in mathematics","titleCN":"数学中从集合里选取若干元素","definition":"in mathematics, to select a number of items from a larger set without regard to order","definitionCN":"数学中从较大的集合里选出若干元素，不计次序","example":"We choose three points on the circle.","exampleCN":"我们在这个圆上选取三个点。","why":"Mathematics keeps only the picking and drops the hand: a subset is chosen from a set.","whyCN":"数学只保留「挑选」而丢掉手：从一个集合里选出一个子集。"}],"etymology":{"intro":{"en":"Choose is an Old English strong verb whose past forms chose and chosen survive, and whose noun came separately through Old French. Dates are approximate.","cn":"choose 是一个古英语强变化动词，过去式 chose 与过去分词 chosen 留存至今，其名词形态则另经古法语进入英语。年代均为约数。"},"items":[{"era":"OLD ENGLISH CEOSAN","en":"Old English ceosan meant to choose, test or taste, and it already carried the sense of examining something before taking it.","cn":"古英语 ceosan 意为「选择、检验、品尝」，已经带有「先察看再取用」的意思。"},{"era":"GERMANIC STOCK","en":"The same verb appears in Old Norse kjosa, Old High German kiosan and Gothic kiusan, all generally traced to a Germanic verb meaning to test.","cn":"同一动词出现在古诺斯语 kjosa、古高地德语 kiosan 与哥特语 kiusan 中，一般都被追溯到表示「检验」的日耳曼语动词。"},{"era":"INDO-EUROPEAN ROOT","en":"The deeper source is usually reconstructed as a root meaning to taste, which also stands behind Latin gustare; the form is a reconstruction, not a recorded word.","cn":"更深的来源通常被重构为一个表示「品尝」的词根，这一词根也是拉丁语 gustare 的来源；该词形属重构形式，并非有记录的真实词。"},{"era":"PAST FORMS","en":"The English past chose and the participle chosen descend from the old strong verb, while the noun choice came in separately through Old French.","cn":"英语过去式 chose 与过去分词 chosen 来自这个古老的强变化动词，而名词 choice 则另经古法语进入。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the exact shape of the Germanic verb and its date of first record are not settled, and the link to a root meaning to taste remains a reconstruction.","cn":"来源不确定：这个日耳曼语动词的确切词形与最早记录年代都无定论，它与表示「品尝」的词根之间的联系仍属重构。"}]},"similar":{"note":{"en":"The first group shares the Germanic stock of choose but differs in function; the second holds verbs that also pick something out. One look-alike belongs to a different root.","cn":"第一组共享 choose 的日耳曼语词干，只是功能不同；第二组也是「挑出某物」的动词。其中有一个形似词属于别的词根。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"choice","ipa":"/tʃɔɪs/","tag":"same root, noun","definition":"The noun of the same stock: it names the act or the option, while choose performs the act.","definitionCN":"同一词干的名词：它命名动作或选项，而 choose 去执行这个动作。"},{"word":"choosy","ipa":"/ˈtʃuːzi/","tag":"same root, adjective","definition":"Hard to please about what one accepts; it describes the person, not the act.","definitionCN":"对接受的东西很挑剔；它描述人，而不是动作。"},{"word":"chosen","ipa":"/ˈtʃəʊzn/","tag":"same root, participle","definition":"The past participle used as an adjective for something already picked.","definitionCN":"过去分词作形容词，指已经被挑中的东西。"},{"word":"cheese","ipa":"/tʃiːz/","tag":"different origin","definition":"From Latin caseus, a dairy product; the spelling looks close to choose but the root is unrelated.","definitionCN":"来自拉丁语 caseus，指乳制品；拼写与 choose 相近，但词根无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"pick","ipa":"/pɪk/","tag":"plain everyday verb","definition":"To take one thing from several, often quickly; choose is the more neutral and formal word.","definitionCN":"常指较快地从几样中取一样；choose 更中性、更正式。"},{"word":"select","ipa":"/sɪˈlekt/","tag":"careful choice","definition":"To pick with care and often by a standard; it stresses the test applied before taking.","definitionCN":"仔细挑选，且常按某种标准；它强调取用之前所做的检验。"},{"word":"elect","ipa":"/ɪˈlekt/","tag":"choose by vote","definition":"To choose a person for office by voting; choose is the wider verb that also covers objects.","definitionCN":"通过投票选出任职者；choose 更宽，也涵盖物件。"},{"word":"opt","ipa":"/ɒpt/","tag":"formal decision","definition":"To make a choice between alternatives, often in a formal context; it does not name the object taken.","definitionCN":"在若干替代项中作出选择，常用于正式语境；它不点明被取走的东西。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real strong verb, the real family and the phrases that keep the act visible.","cn":"正常联想：真实的强变化动词、真实的同族词，以及让这个动作保持可见的固定搭配。"},"normal":[{"en":"The old verb meant test as well as take, so choosing still feels like examining first.","cn":"这个古老动词既表示「检验」也表示「取走」，因此挑选至今仍像先察看再动手。"},{"en":"The family runs choose, chose, chosen, choice, chooser, choosy and choosiness.","cn":"同族词包括 choose（选择）、chose（过去式）、chosen（过去分词）、choice（选择）、chooser（挑选者）、choosy（挑剔的）、choosiness（挑剔）。"},{"en":"Fixed phrases keep the act visible: choose between, choose from, choose to wait.","cn":"固定搭配让动作保持可见：在两者之间选、从若干中选、决定等待。"},{"en":"Pick and choose is the same act doubled, and it usually carries a tone of fussiness.","cn":"pick and choose 是同一个动作说了两遍，通常带有挑剔的语气。"},{"en":"The noun choice came from Old French, so the verb and the noun look different although they are one family.","cn":"名词 choice 来自古法语，因此动词与名词看起来不同，其实是同一家。"}],"abstract":[{"en":"Picture a ring of keys and one key lifted away from the rest.","cn":"想象一串钥匙，其中一把被从其余之中摘下来。"},{"en":"Picture a hand passing over a row of jars and stopping at one.","cn":"想象一只手扫过一排罐子，最后停在其中一个上。"},{"en":"Picture a map with one road inked over the others.","cn":"想象一张地图，其中一条路被描得比其余更黑。"}]},"examples":[{"en":"You may choose any seat in the hall.","cn":"你可以选大厅里的任何一个座位。"},{"en":"They chose to move the meeting to Friday.","cn":"他们决定把会议改到周五。"},{"en":"Voters will choose a new mayor next month.","cn":"选民下个月将选出新市长。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「秋斯」——秋天在满地落叶里挑出最漂亮的那一片 → choose 挑选","word":"choose"},"root":"古英语 ceosan「选择、检验、品尝」，源自日耳曼语表示「检验」的动词；其更深的印欧语词根通常被重构为表示「品尝」的词根。","sensesIntro":{"en":"Eight senses follow one hand: it examines what is offered, takes one item, decides a course, joins a vote, settles a life path, judges what fits, lifts goods from a pile and finally selects a subset in mathematics.","cn":"八个义项沿同一只手展开：它察看摆出来的东西、取走一件、决定一种做法、参与一次投票、选定一条人生道路、判断什么合宜、从堆里拿起货物，最后在数学里选出一个子集。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ring of keys spread in the hand, and only one is freed from the ring and carried away.","cn":"核心意象：一串钥匙摊在手里，最后只有一把被从环上解下带走。"},"chain":["SIZE UP","COMPARE","PICK OUT","TAKE AS ONE'S OWN","DECIDE TO ACT","SETTLE ON A PATH"],"branches":[{"senses":"01 · 07","en":"PICKING OBJECTS: goods and ordinary things are taken one by one from what is offered.","cn":"挑物件：货物与寻常东西被一件件地从摆出来的东西里取走。"},{"senses":"02 · 06","en":"DECIDING TO ACT: choosing to do something and choosing to exercise a formal discretion both end deliberation.","cn":"决定行动：决定去做某事，与在正式规则下自行裁量，都终结了斟酌。"},{"senses":"03","en":"PREFERENCE: choosing one over another is liking turned into a movement of the hand.","cn":"偏好：择此弃彼，就是把喜爱变成手的动作。"},{"senses":"04","en":"ELECTION: a group performs the same pick, with votes counted instead of one hand moving.","cn":"选举：一群人做同样的挑选，只是数票而不是看一只手。"},{"senses":"05 · 08","en":"SETTLING A SET OR A PATH: a career and a mathematical subset are both a lasting selection.","cn":"定下一套或一路：职业与数学子集都是一次会持续的选择。"}]},"affixes":{"intro":{"en":"Choose is an Old English strong verb; its parts are native, and its Latin-looking relatives belong to other families.","cn":"choose 是古英语强变化动词，构词成分是本族语成分；那些看起来像拉丁语的亲属词属于别的词族。"},"latinIntro":{"en":"Choose has no Latin ancestor and no Latin cognate; the Latin verbs eligere and seligere supply elect and select but are not related to this word, so the Latin entries are left empty.","cn":"choose 没有拉丁语祖词，也没有拉丁同族词；拉丁语动词 eligere 与 seligere 产生 elect 与 select，但与这个词无关，因此拉丁词族条目留空。"},"items":[{"word":"ceosan","structure":"Old English ceosan (strong verb)","meaning":"to choose, test, taste","meaningCN":"选择；检验；品尝","example":"The old verb joined testing with taking.","exampleCN":"这个古老动词把检验与取走连在一起。"},{"word":"chose","structure":"choose + old strong past form","meaning":"picked in the past","meaningCN":"过去挑中了","example":"She chose the quieter road.","exampleCN":"她挑了那条更安静的路。"},{"word":"chosen","structure":"choose + strong participle ending","meaning":"having been picked","meaningCN":"已被挑中的","example":"The chosen candidate starts on Monday.","exampleCN":"被选中的人星期一入职。"},{"word":"choice","structure":"Old French chois (noun of choosing)","meaning":"the act or the thing chosen","meaningCN":"选择；被选中之物","example":"The choice was made in silence.","exampleCN":"选择是在沉默中作出的。"},{"word":"chooser","structure":"choose + -er (one who acts)","meaning":"a person who picks","meaningCN":"作挑选的人","example":"The chooser must live with the result.","exampleCN":"作挑选的人必须承担结果。"},{"word":"choosy","structure":"choose + -y (inclined to)","meaning":"hard to please about what one accepts","meaningCN":"对接受的东西很挑剔","example":"She is choosy about her coffee.","exampleCN":"她对咖啡很挑剔。"},{"word":"choosiness","structure":"choosy + -ness (quality)","meaning":"the quality of being hard to please","meaningCN":"挑剔的品质","example":"His choosiness slowed the search.","exampleCN":"他的挑剔让寻找变慢了。"},{"word":"choosing","structure":"choose + -ing (action noun)","meaning":"the process of picking","meaningCN":"挑选的过程","example":"Choosing takes longer than buying.","exampleCN":"挑比买花的时间更长。"}],"latinEntries":[],"derivatives":[{"word":"choice","structure":"choose + Old French noun ending → the act or the thing selected","meaning":"a selection or an option","meaningCN":"选择；选项"},{"word":"chooser","structure":"choose + -er (agent) → the person who performs the pick","meaning":"one who chooses","meaningCN":"挑选者"},{"word":"choosy","structure":"choose + -y (inclined) → inclined to be hard to please","meaning":"fussy in choosing","meaningCN":"挑剔的"},{"word":"choosiness","structure":"choosy + -ness (quality) → the state of being fussy","meaning":"fussiness in choosing","meaningCN":"挑剔"}]}},{"word":"decide","ipa_uk":"/dɪˈsaɪd/","ipa_us":"/dɪˈsaɪd/","definition_zh":"决定；下决心；判定；裁决；成为决定性因素；决定某物的最终形式","definition_en":"to make a choice after thinking, or to settle a matter","core_image":"桌上摊着两条路线，一支笔在分叉处划下一道短线，把其中一条从纸上截断","scene":"会议室的白板上画着两条方案，The board decided to cut the western route from the plan.","sceneCN":"这里 decide 指「在几个可能中作出取舍」（第 1 个义项：经过思考后作出决定）；句意为董事会决定把西线从方案中删去。图中可辨识物件：白板、两条路线、马克笔、会议桌。","pos":[{"tag":"vt.","zh":"决定；判定；裁决；决定某物的最终形式"},{"tag":"vi.","zh":"作出决定；下决心"}],"collocations":[{"phrase":"decide on","zh":"就……作出决定"},{"phrase":"decide to do sth","zh":"决定做某事"},{"phrase":"decide against","zh":"决定不采用；决定反对"},{"phrase":"decide between","zh":"在……之间作抉择"},{"phrase":"decide the matter","zh":"对这件事作出裁定"},{"phrase":"hard to decide","zh":"难以决定"}],"forms":[{"label":"三单（he/she/it）","form":"decides"},{"label":"过去式","form":"decided"},{"label":"过去分词","form":"decided"},{"label":"现在分词","form":"deciding"},{"label":"名词（决定）","form":"decision"},{"label":"形容词（果断的；决定性的）","form":"decisive"},{"label":"副词（果断地）","form":"decisively"},{"label":"名词（果断）","form":"decisiveness"}],"derivatives":[{"word":"decision","pos":"n.","zh":"决定；决议；果断"},{"word":"decisive","pos":"adj.","zh":"果断的；决定性的"},{"word":"decisively","pos":"adv.","zh":"果断地；决定性地"},{"word":"decisiveness","pos":"n.","zh":"果断；决断力"},{"word":"decidable","pos":"adj.","zh":"可判定的（逻辑用语）"},{"word":"undecided","pos":"adj.","zh":"尚未决定的；犹豫的"}],"senses":[{"no":"01","title":"Make a choice after thinking","titleCN":"经过思考后作出决定","definition":"to make a choice between possibilities after considering them","definitionCN":"在考虑过几种可能之后作出抉择","example":"We decided after a long discussion.","exampleCN":"我们经过长时间讨论后作出了决定。","why":"The Latin verb meant to cut off, so a decision is a line drawn through the options one will not take.","whyCN":"这个拉丁动词意为「切掉」，因此决定就是在不再要的选项上划一道线。"},{"no":"02","title":"Bring a matter to an end","titleCN":"把一件事了结","definition":"to settle a question or dispute so that it no longer needs discussion","definitionCN":"把问题或争端了结，使它不再需要讨论","example":"One sentence decided the argument.","exampleCN":"一句话就把争论了结了。","why":"Cutting off is also ending, so deciding closes a matter the way a knife closes a thread.","whyCN":"切断也就是终结，因此决定像刀切断线一样把一件事收尾。"},{"no":"03","title":"Be the factor that determines the outcome","titleCN":"成为决定结果的因素","definition":"to determine the result of a contest or process","definitionCN":"决定一场较量或一个过程的结果","example":"One late goal decided the match.","exampleCN":"终场前的一个进球决定了这场比赛。","why":"The same verb shifts from the person who chooses to the event that makes the choice inevitable.","whyCN":"同一个动词从「作选择的人」转到「使选择不可避免的那件事」。"},{"no":"04","title":"Make up one's mind to act","titleCN":"下定决心去做","definition":"to resolve firmly to do something","definitionCN":"坚定地决定要做某事","example":"She decided to resign.","exampleCN":"她决定辞职。","why":"A resolution is a choice about one's own future action, and it ends the wavering.","whyCN":"决心是对自己未来行动的抉择，它终结了摇摆。"},{"no":"05","title":"Give an authoritative judgment","titleCN":"作出权威裁决","definition":"to settle a case or question by authority","definitionCN":"以权威身份裁断案件或问题","example":"The panel decided in favour of the tenant.","exampleCN":"裁决小组判房客一方胜诉。","why":"A court cuts the knot that the parties could not untie themselves.","whyCN":"当事人自己解不开的结，由法庭一刀切断。"},{"no":"06","title":"Choose in favour of or against","titleCN":"决定支持或反对","definition":"to reach a conclusion for or against a person or proposal","definitionCN":"对某个人或某项提议得出支持或反对的结论","example":"The committee decided against the plan.","exampleCN":"委员会决定否决这个方案。","why":"The choice now runs in one direction, and the verb names which side of the cut one stands on.","whyCN":"选择此时只朝一个方向走，动词点明人站在切口哪一边。"},{"no":"07","title":"Establish a result by a formal procedure","titleCN":"用形式化程序判定结果","definition":"in logic and computing, to settle a question by a procedure that always gives an answer","definitionCN":"在逻辑与计算中，用总能给出答案的程序判定一个问题","example":"The procedure decides whether the formula is valid.","exampleCN":"这个程序判定该公式是否有效。","why":"A mechanical procedure cuts the space of possibilities down to yes or no.","whyCN":"机械化的程序把可能性空间切到只剩「是」或「否」。"},{"no":"08","title":"Determine the final form of something","titleCN":"决定某物的最终形态","definition":"to determine the final shape or arrangement of something","definitionCN":"决定某物的最终形状或安排","example":"The editor decided the order of the chapters.","exampleCN":"编辑决定了各章的顺序。","why":"Here the cut is made in a material or a plan, not in a list of choices.","whyCN":"这里的切口落在材料或方案上，而不是落在选项清单上。"}],"etymology":{"intro":{"en":"Decide comes from Latin decidere, literally to cut off, built on de- meaning off and caedere meaning to cut. Dates are approximate.","cn":"decide 来自拉丁语 decidere，字面意为「切掉」，由 de-「离开」与 caedere「切」构成。年代均为约数。"},"items":[{"era":"LATIN CAEDERE","en":"Caedere meant to cut, fell or strike. Its deeper Indo-European source is reconstructed as a root meaning to strike, and that form is not recorded.","cn":"caedere 意为「切、砍倒、击打」。它更深的印欧语来源被重构为一个表示「击打」的词根，该词形没有记录。"},{"era":"LATIN DECIDERE","en":"De- meaning off plus caedere produced decidere, to cut off or cut down, and already in Latin to settle or determine a matter.","cn":"de-「离开」加 caedere 构成 decidere，意为「切掉、砍下」，在拉丁语里已经引申为「了结、判定」一件事。"},{"era":"OLD FRENCH DECIDER","en":"Old French decider brought the verb into English around 1400, first in the sense of coming to a resolution.","cn":"古法语 decider 约在十五世纪初把这个动词带入英语，最初指得出一个决断。"},{"era":"LEGAL AND LOGICAL USE","en":"The legal sense of settling a case appeared in the fifteenth century, and the formal procedure sense came much later with logic and computing.","cn":"裁断案件的法学义在十五世纪出现；形式化程序的义项则晚得多，随逻辑学与计算技术而来。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation is not fixed, and how the image of cutting became the everyday sense of choosing is a matter of interpretation rather than record.","cn":"来源不确定：英语最早书证年代无定论；「切」这个形象如何变成日常的「选择」，属解释而非有记录的实证。"}]},"similar":{"note":{"en":"The first group looks close to decide in spelling and shares Latin ancestry in some cases; the second holds verbs of resolving. One look-alike has a different root.","cn":"第一组在拼写上与 decide 相近，其中有的共享拉丁语来源；第二组是表示「决断」的动词。有一个形似词词根不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"decision","ipa":"/dɪˈsɪʒn/","tag":"same root, noun","definition":"The noun of the same verb: it names the result or the act, while decide performs it.","definitionCN":"同一动词的名词：它命名结果或动作，而 decide 去执行这个动作。"},{"word":"decisive","ipa":"/dɪˈsaɪsɪv/","tag":"same root, adjective","definition":"Marked by the ability to decide quickly, or able to settle an outcome.","definitionCN":"表现为能迅速决断，或能够决定结果。"},{"word":"decidable","ipa":"/dɪˈsaɪdəbl/","tag":"same root, technical","definition":"In logic, able to be settled by a procedure; it is a technical adjective, not a description of a person.","definitionCN":"在逻辑学中指能由程序判定；这是技术性形容词，不用于描述人的性格。"},{"word":"deciduous","ipa":"/dɪˈsɪdjuəs/","tag":"different root","definition":"Falling off seasonally, from Latin cadere meaning to fall, not caedere meaning to cut; the resemblance is misleading.","definitionCN":"指季节性脱落的，来自拉丁语 cadere「落下」，而非 caedere「切」；形似容易误导。"}]},{"heading":"NEAR MEANING","entries":[{"word":"determine","ipa":"/dɪˈtɜːmɪn/","tag":"fix the limits","definition":"To fix or settle something, often by investigation; decide stresses the moment of choice.","definitionCN":"常经调查而确定或限定某事；decide 强调作出选择的那一刻。"},{"word":"resolve","ipa":"/rɪˈzɒlv/","tag":"settle firmly","definition":"To settle a difficulty or make a firm decision; it adds the note of loosening a knot.","definitionCN":"解决困难或作出坚定决定；它带有「解开结」的意味。"},{"word":"conclude","ipa":"/kənˈkluːd/","tag":"end with a judgment","definition":"To reach a judgment at the end of reasoning; decide can also mean to end a matter outright.","definitionCN":"在推理结束时得出判断；decide 还可以直接表示把事了结。"},{"word":"choose","ipa":"/tʃuːz/","tag":"pick among options","definition":"To pick one option from several; decide adds the settling of the question, not only the picking.","definitionCN":"从几个选项中挑一个；decide 多加了一层「把问题定下来」，不只是挑。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the real root of cutting, the real family and the phrases the verb keeps.","cn":"正常联想：真实的前缀、真实的「切」词根、真实的同族词，以及这个动词实际常用的搭配。"},"normal":[{"en":"de- meaning off plus caedere meaning cut: to cut off the options one will not take.","cn":"de-「离开」加 caedere「切」：把不打算要的选项切掉。"},{"en":"The family runs decide, decision, decisive, decisively, decisiveness and decidable.","cn":"同族词包括 decide（决定）、decision（决定）、decisive（果断的）、decisively（果断地）、decisiveness（果断）、decidable（可判定的）。"},{"en":"Fixed phrases mark the direction: decide on, decide against, decide between.","cn":"固定搭配标出方向：就……作决定、决定反对、在两者间抉择。"},{"en":"A court decides a case, and the losing side is cut off from further argument.","cn":"法庭裁断案件，败诉一方就此被切断了继续争辩的余地。"},{"en":"Deciduous looks like decide but comes from falling, not cutting, so the two should not be linked.","cn":"deciduous 看起来像 decide，但它来自「落下」而不是「切」，两者不应混为一谈。"}],"abstract":[{"en":"Picture a pen drawing a line through one of two routes on a map.","cn":"想象一支笔在地图上的两条路线中，把其中一条划掉。"},{"en":"Picture a knot cut once and falling open on both sides.","cn":"想象一个结被切了一刀，向两边散开。"},{"en":"Picture a balance that stops swinging and holds one pan down.","cn":"想象一架天平停止摆动，一端沉了下去。"}]},"examples":[{"en":"They decided to postpone the trip until spring.","cn":"他们决定把旅行推迟到春天。"},{"en":"The referee decided the disputed point in seconds.","cn":"裁判几秒钟内就裁定了那个争议点。"},{"en":"Her answer decided the whole interview.","cn":"她的回答决定了整场面试的结果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「得赛」——在岔路口拿定主意，把别的路一刀划掉 → decide 决定","word":"decide"},"root":"拉丁 decidere「切掉、了结」= de-「离开」+ caedere「切、砍」；caedere 更深的印欧语词根被重构为表示「击打」的形式。英语 decide 经古法语进入。","sensesIntro":{"en":"Eight senses follow one cut: options are cut off, a dispute is ended, an outcome is settled, a person resolves, a court judges, a side is chosen, a procedure answers yes or no, and a final form is fixed.","cn":"八个义项沿同一刀展开：切掉选项、了结争端、定下结果、人下决心、法庭裁断、选定一边、程序给出是或否，最后把最终形态固定下来。"},"semanticMap":{"core":{"en":"CORE IMAGE: two routes on a sheet of paper, and one is cut away with a single stroke.","cn":"核心意象：纸上是两条路线，其中一条被一笔切掉。"},"chain":["WEIGH THE OPTIONS","CUT ONE OFF","END THE MATTER","SETTLE THE RESULT","STAND ON ONE SIDE","FIX THE FORM"],"branches":[{"senses":"01 · 04","en":"WEIGH AND RESOLVE: a person compares courses and then makes one of them his own.","cn":"权衡与决心：人先比较几种做法，再把其中一种变成自己的。"},{"senses":"02 · 05","en":"END AND JUDGE: a dispute is closed either by agreement or by authority.","cn":"了结与裁断：争端或经协商关闭，或由权威关闭。"},{"senses":"03 · 08","en":"DETERMINE: an event fixes an outcome, and an editor fixes a form.","cn":"决定：一件事定下结果，一位编辑定下形态。"},{"senses":"06","en":"TAKE A SIDE: the cut leaves the chooser standing on one side of it.","cn":"择边：切口让作决定的人站在其中一边。"},{"senses":"07","en":"PROCEDURE: a mechanical rule cuts the possibilities down to yes or no.","cn":"程序：机械规则把可能性切到只剩是或否。"}]},"affixes":{"intro":{"en":"Decide can be read from a Latin prefix and a Latin verb of cutting, both of which build a compact English family.","cn":"decide 可以按一个拉丁前缀与一个表示「切」的拉丁动词逐段读出，这两部分构成一小族英语词。"},"latinIntro":{"en":"Latin caedere gives decide, incision and precise through related forms; de- adds the sense of separation.","cn":"拉丁语 caedere 通过相关形态衍生 decide、incision 与 precise；de- 加上「分离」的意思。"},"items":[{"word":"de-","structure":"de- (Latin prefix, off, away)","meaning":"off; away","meaningCN":"离开；去掉","example":"The prefix also appears in depart and deduct.","exampleCN":"这个前缀也出现在 depart（离开）与 deduct（扣除）里。"},{"word":"caedere","structure":"caedere (Latin verb, to cut, strike)","meaning":"to cut; to strike","meaningCN":"切；砍；击","example":"Its stem survives in incision and precise.","exampleCN":"它的词干留在 incision（切口）与 precise（精确的）里。"},{"word":"decide","structure":"de- + caedere","meaning":"to cut off, hence to settle","meaningCN":"切掉，因而了结","example":"They decided to stay.","exampleCN":"他们决定留下。"},{"word":"decision","structure":"decide + -ion (noun of action)","meaning":"the act or result of settling","meaningCN":"决定（动作或结果）","example":"The decision was unanimous.","exampleCN":"这个决定是一致通过的。"},{"word":"decisive","structure":"decide + -ive (tending to)","meaning":"able to settle an outcome","meaningCN":"能决定结果的；果断的","example":"She gave a decisive answer.","exampleCN":"她给出了果断的回答。"},{"word":"decisively","structure":"decisive + -ly (adverb ending)","meaning":"in a manner that settles the matter","meaningCN":"以果断、决定性的方式","example":"He acted decisively.","exampleCN":"他果断地行动。"},{"word":"decisiveness","structure":"decisive + -ness (quality)","meaning":"the quality of settling quickly","meaningCN":"果断的品质","example":"Her decisiveness ended the debate.","exampleCN":"她的果断结束了争论。"},{"word":"decidable","structure":"decide + -able (can be)","meaning":"able to be settled by a procedure","meaningCN":"可由程序判定的","example":"The problem is decidable in principle.","exampleCN":"这个问题在原则上可判定。"},{"word":"undecided","structure":"un- (not) + decided","meaning":"not yet settled","meaningCN":"尚未决定的","example":"Two voters remain undecided.","exampleCN":"还有两名选民未作决定。"}],"latinEntries":[{"word":"caedere","structure":"caedere, cecidi, caesum (verb, third conjugation)","meaning":"to cut, fell, strike","meaningCN":"切；砍倒；击"},{"word":"decidere","structure":"decidere, decidi, decisum (verb, third conjugation)","meaning":"to cut off, settle","meaningCN":"切掉；了结"},{"word":"decisio","structure":"decisio, decisionis (f., third declension)","meaning":"a settlement, a decision","meaningCN":"了结；裁断"},{"word":"caesum","structure":"caesum, -i (n., supine used as a noun)","meaning":"a cutting","meaningCN":"切割"}],"derivatives":[{"word":"decision","structure":"decide + -ion (action noun) → the result of cutting off the alternatives","meaning":"a settled choice","meaningCN":"决定；决议"},{"word":"decisive","structure":"decide + -ive (tending adjective) → tending to settle the matter","meaning":"settling an outcome","meaningCN":"决定性的；果断的"},{"word":"decisively","structure":"decisive + -ly (adverb) → in a way that settles the matter","meaning":"in a decisive manner","meaningCN":"果断地；决定性地"},{"word":"decidable","structure":"decide + -able (possibility) → able to be settled by a rule","meaning":"settleable by procedure","meaningCN":"可判定的"},{"word":"undecided","structure":"un- (negation) + decided → not yet cut off from the options","meaning":"not settled","meaningCN":"未决定的"}]}},{"word":"intention","ipa_uk":"/ɪnˈtenʃn/","ipa_us":"/ɪnˈtenʃən/","definition_zh":"意图；打算；目的；[法律] 故意；[宗教] 意向；[医] 愈合方式；[哲学] 意识指向","definition_en":"the purpose or plan that a person means to carry out","core_image":"一支箭搭在弦上，箭头指向远处的靶心，手还没有松开","scene":"射箭场上，教练让学生先别放箭，The archer's intention was to hit the farthest target.","sceneCN":"这里 intention 指「打算要做的事」（第 2 个义项：心中计划要做的事）；句意为射手的打算是射中最远的那个靶。图中可辨识物件：弓、箭、靶心、教练的手势。","pos":[{"tag":"n.","zh":"意图；打算；目的；故意；宗教意向；愈合方式"}],"collocations":[{"phrase":"intention to do sth","zh":"做某事的意图"},{"phrase":"with the intention of","zh":"带着……的目的"},{"phrase":"have no intention of","zh":"无意做……"},{"phrase":"clear intention","zh":"明确的意图"},{"phrase":"good intentions","zh":"良好的用意"},{"phrase":"declare one's intention","zh":"表明意图"}],"forms":[{"label":"复数","form":"intentions"},{"label":"动词（打算）","form":"intend"},{"label":"名词（意图，法律常用）","form":"intent"},{"label":"形容词（故意的）","form":"intentional"},{"label":"副词（故意地）","form":"intentionally"},{"label":"名词（意向性，哲学用语）","form":"intentionality"}],"derivatives":[{"word":"intend","pos":"v.","zh":"打算；意图"},{"word":"intent","pos":"n./adj.","zh":"意图；专注的"},{"word":"intentional","pos":"adj.","zh":"故意的"},{"word":"intentionally","pos":"adv.","zh":"故意地"},{"word":"intentionality","pos":"n.","zh":"意向性（哲学用语）"}],"senses":[{"no":"01","title":"The purpose behind an action","titleCN":"行为背后的目的","definition":"the purpose that a person means to achieve by acting","definitionCN":"一个人通过行动想要达到的目的","example":"The intention behind the rule was safety.","exampleCN":"这条规则背后的用意是安全。","why":"The Latin verb means to stretch toward, so an intention is the mind aimed at an end before the hand moves.","whyCN":"这个拉丁动词意为「朝……伸展」，因此意图是手还没动、心已对准的那个终点。"},{"no":"02","title":"Something one plans to do","titleCN":"心中计划要做的事","definition":"a plan or aim that one has in mind to carry out","definitionCN":"心里打算要去实现的计划或目标","example":"Her intention was to study abroad.","exampleCN":"她的打算是出国留学。","why":"The stretched aim becomes a plan with steps, and the word then names the plan itself.","whyCN":"被拉长的瞄准变成有步骤的计划，于是这个词也直接指那份计划。"},{"no":"03","title":"The mind directed at an object","titleCN":"心指向某个对象","definition":"in philosophy, the direction of consciousness toward an object","definitionCN":"在哲学中，意识指向某个对象的状态","example":"In phenomenology, intention is what makes a thought about something.","exampleCN":"在现象学里，意识指向某物正是思想「关于某物」的原因。","why":"Consciousness is always stretched toward something, so the old image of aiming became a technical term for aboutness.","whyCN":"意识总是朝着某物伸展，于是古老的瞄准形象变成了指称性的术语。"},{"no":"04","title":"The purpose the law reads into an act","titleCN":"法律从行为中读出的故意","definition":"in law, the purpose that a person is treated as having when acting","definitionCN":"在法律上，一个人实施行为时被认定怀有的目的","example":"The court looked for an intention to deceive.","exampleCN":"法庭查找是否存在欺诈的故意。","why":"Law must judge an invisible aim from visible conduct, so intention becomes a fact the court reconstructs.","whyCN":"法律必须从看得见的行为判断看不见的目的，因此故意成了法庭重建出来的事实。"},{"no":"05","title":"The inward purpose of a rite","titleCN":"宗教仪式中的内在意向","definition":"the inward purpose with which a worshipper or priest performs a rite","definitionCN":"行仪式的人或司祭施行礼仪时所怀的内在目的","example":"The priest announced the intention of the Mass.","exampleCN":"司祭宣布了这场弥撒的意向。","why":"A rite has an outward form and an inward aim, and the word names the second.","whyCN":"礼仪有外在形式与内在目的，这个词命名的是后者。"},{"no":"06","title":"The way a wound closes","titleCN":"伤口的愈合方式","definition":"in medicine, the manner in which a wound heals, either directly or through new tissue","definitionCN":"在医学上，伤口直接愈合或经由新生组织愈合的方式","example":"The cut healed by first intention.","exampleCN":"这道切口以第一期愈合的方式长好。","why":"Surgery borrowed the word because healing also follows an aim set at the start.","whyCN":"外科借用这个词，因为愈合同样沿着起初设定的方向走。"},{"no":"07","title":"A fixed direction of attention","titleCN":"专注的注意力","definition":"an older sense of a straining of the mind toward something, close to attention","definitionCN":"较古的义项，指心力朝某物绷紧，接近「注意」","example":"The monk kept his intention fixed on the prayer.","exampleCN":"僧人把心力一直定在祈祷上。","why":"The oldest Latin noun meant a stretching or straining, and attention is the same stretch held steady.","whyCN":"最古老的拉丁名词意为「拉伸、绷紧」，而注意就是把同一根弦稳稳拉住。"},{"no":"08","title":"The meaning a work is meant to convey","titleCN":"作品想要传达的意思","definition":"the meaning that a maker or speaker meant a work or remark to carry","definitionCN":"创作者或说话人希望作品、话语承载的意思","example":"The intention of the painting is still debated.","exampleCN":"这幅画的用意仍有争论。","why":"Once an aim is placed in a made thing, it can be read back out of it, and that reading is called its intention.","whyCN":"目的被放进一件成品之后，又能从成品里读回来，读出的那层意思就叫它的用意。"}],"etymology":{"intro":{"en":"Intention comes through Old French from Latin intentio, a noun of action from intendere, which means to stretch toward. Dates are approximate.","cn":"intention 经古法语来自拉丁语 intentio，是动词 intendere 的动名词，后者意为「朝……伸展」。年代均为约数。"},"items":[{"era":"LATIN TENDERE","en":"Tendere meant to stretch or extend. Its deeper Indo-European source is reconstructed as a root meaning to stretch, and that form is not recorded.","cn":"tendere 意为「伸展、拉开」。它更深的印欧语来源被重构为一个表示「拉伸」的词根，该词形没有记录。"},{"era":"LATIN INTENDERE","en":"In- meaning toward plus tendere produced intendere, to stretch toward or aim at something.","cn":"in-「朝向」加 tendere 构成 intendere，意为「朝某物伸展、瞄准」。"},{"era":"LATIN INTENTIO","en":"Intentio named a stretching, an effort or a fixing of attention, and Latin writers also used it for the aim of the mind.","cn":"intentio 指拉伸、用力或注意的固定，拉丁作家也用它指心之所向。"},{"era":"OLD FRENCH ENCION","en":"Old French entencion brought the word into English in the fourteenth century as thought, purpose or aim.","cn":"古法语 entencion 在十四世纪把这个词带入英语，意为思想、目的或目标。"},{"era":"SPECIALIZED SENSES","en":"Law and theology sharpened the word into a judged purpose, while medicine used it for the mode of healing.","cn":"法学与神学把这个词收窄为可被判断的目的，医学则用它指愈合的方式。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation is not fixed, and the philosophical sense was shaped by later translators rather than by one original usage.","cn":"来源不确定：英语最早书证年代无定论；哲学义是由后世译者塑造的，并非出自某一次原始用法。"}]},"similar":{"note":{"en":"The first group shares the Latin verb tendere but differs in prefix; the second holds words for purpose and aim. One look-alike looks technical but comes from the same root.","cn":"第一组共享拉丁动词 tendere，只是前缀不同；第二组是表示目的与目标的词。其中有一个看似技术语的词其实同根。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"intent","ipa":"/ɪnˈtent/","tag":"same root, legal noun","definition":"The short noun used especially in law and in the phrase with intent; intention is the fuller everyday noun.","definitionCN":"较短的名称词，尤用于法律与「怀有故意」的短语；intention 是更完整的日常名词。"},{"word":"attention","ipa":"/əˈtenʃn/","tag":"same root, different prefix","definition":"Ad- meaning toward plus tendere: the mind stretched toward something, hence notice or care.","definitionCN":"ad-「朝向」加 tendere：心朝某物伸展，因而指注意或关照。"},{"word":"intense","ipa":"/ɪnˈtens/","tag":"same root, adjective","definition":"Stretched tight, hence strong or extreme; it describes force, not a plan.","definitionCN":"绷得很紧，因而指强烈或极端的；它描述力度，不描述计划。"},{"word":"intension","ipa":"/ɪnˈtenʃn/","tag":"same root, technical","definition":"A logic term for the internal content of a concept; it sounds like intention but belongs to semantics, not to plans.","definitionCN":"逻辑学术语，指概念的内涵；它与 intention 同音，但属于语义学，不指计划。"}]},{"heading":"NEAR MEANING","entries":[{"word":"purpose","ipa":"/ˈpɜːpəs/","tag":"the end in view","definition":"The reason for doing something or the result aimed at; intention stresses the mind that holds it.","definitionCN":"做某事的理由或瞄准的结果；intention 更强调怀有这个目的的心。"},{"word":"aim","ipa":"/eɪm/","tag":"the target","definition":"The goal one tries to hit; it keeps the image of pointing, which intention has made abstract.","definitionCN":"想要击中的目标；它保留了「瞄准」的形象，而 intention 已把这层形象抽象化。"},{"word":"plan","ipa":"/plæn/","tag":"steps laid out","definition":"A set of steps for doing something; an intention may exist without any steps worked out.","definitionCN":"为做某事安排的一组步骤；意图可以存在而完全没有排出步骤。"},{"word":"motive","ipa":"/ˈməʊtɪv/","tag":"the reason that moves","definition":"The reason that drives a person to act; intention is the aim, motive is the push behind it.","definitionCN":"促使人行动的原因；intention 是瞄准的目标，motive 是背后的推力。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the root of stretching, the real family and the phrases the noun keeps.","cn":"正常联想：真实的前缀、表示「拉伸」的词根、真实的同族词，以及这个名词实际常用的搭配。"},"normal":[{"en":"in- meaning toward plus tendere meaning stretch: the mind stretched toward an end.","cn":"in-「朝向」加 tendere「伸展」：心朝某个终点拉长。"},{"en":"The family runs intend, intent, intention, intentional, intentionally and intentionality.","cn":"同族词包括 intend（打算）、intent（意图）、intention（意图）、intentional（故意的）、intentionally（故意地）、intentionality（意向性）。"},{"en":"Fixed phrases mark the aim: intention to do, with the intention of, have no intention of.","cn":"固定搭配标出目标：做某事的意图、带着……的目的、无意做……。"},{"en":"Attention shares the same root with a different prefix: both are a stretching of the mind.","cn":"attention 共享同一词根而前缀不同：两者都是心力的伸展。"},{"en":"In law the short form intent is usual, as in with intent to deceive.","cn":"法律上常用较短的 intent，例如「怀有欺骗的故意」。"}],"abstract":[{"en":"Picture an arrow on a drawn bow, pointed at a target not yet reached.","cn":"想象一支箭搭在拉开的弓上，箭头对着尚未到达的靶。"},{"en":"Picture a finger tracing a line across a map before the walk begins.","cn":"想象一根手指在出发前沿着地图划出一条线。"},{"en":"Picture a lamp turned toward a corner that is still dark.","cn":"想象一盏灯转向一个仍然昏暗的角落。"}]},"examples":[{"en":"He had no intention of selling the house.","cn":"他无意出售这所房子。"},{"en":"The letter states the writer's intention plainly.","cn":"这封信把写信人的意图说得清清楚楚。"},{"en":"Good intentions do not always produce good results.","cn":"良好的用意并不总能带来好结果。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因疼神」——心里一直惦记着要去做的那件事 → intention 意图、打算","word":"intention"},"root":"拉丁 intentio「拉伸、注意、心之所向」来自 intendere = in-「朝向」+ tendere「伸展」；tendere 更深的印欧语词根被重构为表示「拉伸」的形式。英语 intention 经古法语进入。","sensesIntro":{"en":"Eight senses follow one stretch: the mind reaches toward an end, turns that reach into a plan, aims it at an object, and then law, rite, medicine and art each read the aim back out of the act.","cn":"八个义项沿同一次伸展展开：心朝一个终点伸出去，把这次伸展变成计划，再对准某个对象；随后法律、礼仪、医学与艺术各自从行为里把目的读回来。"},"semanticMap":{"core":{"en":"CORE IMAGE: an arrow on a drawn bow, aimed at a target before the string is released.","cn":"核心意象：一支箭搭在拉开的弓上，弦还没放就已经对准了靶。"},"chain":["BOW DRAWN","AIM TAKEN","PLAN FORMED","MIND DIRECTED","PURPOSE READ","MEANING MEANT"],"branches":[{"senses":"01 · 08","en":"PURPOSE AND MEANING: what the maker aims at is later read out of the made thing.","cn":"目的与含义：创作者瞄准的东西，后来又从成品里被读出来。"},{"senses":"02","en":"PLAN: the stretched aim hardens into steps one means to take.","cn":"计划：被拉长的瞄准凝固成打算要走的一步步。"},{"senses":"03 · 07","en":"DIRECTED MIND: aboutness and fixed attention are the same stretch, one toward an object and one held steady.","cn":"指向的心：指称性与固定的注意是同一次伸展，前者朝向对象，后者稳稳拉住。"},{"senses":"04 · 05","en":"JUDGED PURPOSE: law and rite both ask what inward aim accompanied the outward act.","cn":"被判断的目的：法律与礼仪都在问，外在行为伴随着什么样的内在目的。"},{"senses":"06","en":"HEALING MODE: surgery borrows the aim for the direction in which a wound closes.","cn":"愈合方式：外科借这个「方向」来指伤口闭合的走法。"}]},"affixes":{"intro":{"en":"Intention can be read from a Latin prefix and a verb of stretching that also build a wide English family.","cn":"intention 可以按一个拉丁前缀与一个表示「伸展」的动词逐段读出，两者还构成一大族英语词。"},"latinIntro":{"en":"Latin tendere gives intend, intention, attention, intense and tension through related forms; in- adds direction toward something.","cn":"拉丁语 tendere 通过相关形态衍生 intend、intention、attention、intense 与 tension；in- 加上「朝向某物」的方向。"},"items":[{"word":"in-","structure":"in- (Latin prefix, toward, into)","meaning":"toward; into","meaningCN":"朝向；进入","example":"The prefix also appears in incline and inject.","exampleCN":"这个前缀也出现在 incline（倾斜）与 inject（注入）里。"},{"word":"tendere","structure":"tendere (Latin verb, to stretch, extend)","meaning":"to stretch; to extend","meaningCN":"伸展；拉长","example":"Its stem survives in tension and tendon.","exampleCN":"它的词干留在 tension（张力）与 tendon（腱）里。"},{"word":"intend","structure":"in- + tendere","meaning":"to stretch the mind toward something","meaningCN":"把心朝某物伸过去；打算","example":"We intend to leave at dawn.","exampleCN":"我们打算天亮时离开。"},{"word":"intention","structure":"intend + -ion (noun of action)","meaning":"the aim held in mind","meaningCN":"心里怀着的意图","example":"Her intention was clear.","exampleCN":"她的意图很清楚。"},{"word":"intent","structure":"intend + Latin participle ending (short noun)","meaning":"a fixed purpose, especially in law","meaningCN":"固定的目的，尤用于法律","example":"He acted with intent to deceive.","exampleCN":"他怀着欺骗的故意行事。"},{"word":"intentional","structure":"intention + -al (relational adjective)","meaning":"done with a purpose","meaningCN":"有目的而做的；故意的","example":"The pause was intentional.","exampleCN":"那次停顿是故意的。"},{"word":"intentionally","structure":"intentional + -ly (adverb ending)","meaning":"in a purposeful manner","meaningCN":"以有目的的方式；故意地","example":"He left the door open intentionally.","exampleCN":"他故意让门开着。"},{"word":"attention","structure":"ad- (toward) + tendere, a parallel formation","meaning":"the mind stretched toward something","meaningCN":"心朝某物伸展；注意","example":"The lecture held my attention.","exampleCN":"这场讲座吸引了我的注意。"},{"word":"tension","structure":"tendere + -ion (state noun)","meaning":"the state of being stretched","meaningCN":"被拉伸的状态；张力","example":"The rope was under tension.","exampleCN":"绳子处于绷紧状态。"}],"latinEntries":[{"word":"tendere","structure":"tendere, tetendi, tensum (verb, third conjugation)","meaning":"to stretch, extend","meaningCN":"伸展；拉长"},{"word":"intendere","structure":"intendere, intendi, intentum (verb, third conjugation)","meaning":"to stretch toward, aim at","meaningCN":"朝……伸展；瞄准"},{"word":"intentio","structure":"intentio, intentionis (f., third declension)","meaning":"a stretching, effort, aim","meaningCN":"拉伸；用力；意图"},{"word":"intentus","structure":"intentus, -a, -um (adjective)","meaning":"stretched tight, attentive","meaningCN":"绷紧的；专注的"}],"derivatives":[{"word":"intent","structure":"intend + past-participle form → the aim fixed in the mind","meaning":"a settled purpose","meaningCN":"意图；目的"},{"word":"intentional","structure":"intention + -al (relational) → marked by a held aim","meaning":"done on purpose","meaningCN":"故意的"},{"word":"intentionally","structure":"intentional + -ly (adverb) → in a purposeful way","meaning":"on purpose","meaningCN":"故意地"},{"word":"intentionality","structure":"intentional + -ity (abstract noun) → the property of being directed at an object","meaning":"the aboutness of consciousness","meaningCN":"意识的指向性"},{"word":"attention","structure":"ad- toward + tendere stretch + -ion → a stretching toward something","meaning":"notice or care directed at something","meaningCN":"注意；关照"}]}},{"word":"intentional","ipa_uk":"/ɪnˈtenʃənl/","ipa_us":"/ɪnˈtenʃənəl/","definition_zh":"故意的；有意的；经过设计的；[哲学] 有意向性的；[法律] 蓄意的","definition_en":"done on purpose rather than by accident, or showing a conscious design","core_image":"一个人在画布上先画下淡淡的辅助线，再照着线一笔一笔落下颜色","scene":"修复室里，技师指着画上一处不自然的补色，The restorer found an intentional patch where the varnish had been scraped.","sceneCN":"这里 intentional 指「有意为之、并非偶然」（第 1 个义项：出于有意而非意外）；句意为修复师发现一块有意留下的补色，那里的清漆被刮去过。图中可辨识物件：放大镜、刮痕、补色块、工作灯。","pos":[{"tag":"adj.","zh":"故意的；有意的；经过设计的；有意向性的"}],"collocations":[{"phrase":"intentional act","zh":"故意行为"},{"phrase":"intentional damage","zh":"故意造成的损害"},{"phrase":"intentional harm","zh":"故意伤害"},{"phrase":"intentional design","zh":"有意的设计"},{"phrase":"intentional omission","zh":"有意省略"},{"phrase":"deliberate and intentional","zh":"深思熟虑且蓄意的"}],"forms":[{"label":"原级","form":"intentional"},{"label":"比较级","form":"more intentional"},{"label":"最高级","form":"most intentional"},{"label":"副词（故意地）","form":"intentionally"},{"label":"名词（意图）","form":"intention"},{"label":"名词（意向性，哲学用语）","form":"intentionality"},{"label":"反义形容词（无意的）","form":"unintentional"}],"derivatives":[{"word":"intention","pos":"n.","zh":"意图；打算"},{"word":"intentionally","pos":"adv.","zh":"故意地"},{"word":"intentionality","pos":"n.","zh":"意向性（哲学用语）"},{"word":"unintentional","pos":"adj.","zh":"无意的"},{"word":"unintentionally","pos":"adv.","zh":"无意地"}],"senses":[{"no":"01","title":"Done on purpose, not by accident","titleCN":"有意而为，并非偶然","definition":"done deliberately rather than by accident","definitionCN":"出于有意，而不是出于偶然","example":"The omission was intentional.","exampleCN":"这次省略是有意为之。","why":"The adjective adds a relation to a held aim, so an intentional act is one that carries a purpose.","whyCN":"这个形容词加上了「与某个既定目的相关」的意思，因此有意的行为就是带着目的的行为。"},{"no":"02","title":"Showing a conscious design","titleCN":"显出有意识的设计","definition":"showing that something was planned rather than left to chance","definitionCN":"显示出某物经过筹划，而不是任由偶然摆布","example":"The room has an intentional simplicity.","exampleCN":"这个房间有一种刻意为之的简朴。","why":"A plan can be seen in an object, and the word then praises or blames the design rather than the act.","whyCN":"计划可以从物件上被看见，于是这个词评价的是设计，而不是行为。"},{"no":"03","title":"Directed toward an object, in philosophy","titleCN":"哲学上指意识指向对象","definition":"in philosophy, relating to the property of being about something","definitionCN":"在哲学上，指具有「关于某物」这一性质","example":"Intentional states are about objects beyond themselves.","exampleCN":"意向状态总是关于自身之外的对象。","why":"The same image of aiming became a technical word for the way thoughts point at things.","whyCN":"同一个瞄准的形象，在这里变成了描述思想如何指向事物的术语。"},{"no":"04","title":"Done with a purpose the law treats as blameworthy","titleCN":"带有法律视为可责目的的","definition":"in law, done with a designed purpose for which the actor can be held responsible","definitionCN":"在法律上，带着行为人须为其负责的既定目的而做","example":"The damage was intentional and therefore actionable.","exampleCN":"这项损害是故意的，因此可以起诉。","why":"Law separates what merely happened from what was aimed at, and this adjective marks the second.","whyCN":"法律把「只是发生了的事」与「被瞄准的事」分开，这个形容词标记的是后者。"},{"no":"05","title":"Planned as a shared way of living","titleCN":"作为共同生活方式而筹划的","definition":"describing a community whose shared life is planned rather than conventional","definitionCN":"描述一种共同生活经过筹划、而非沿袭常规的社群","example":"They live in an intentional community that shares meals.","exampleCN":"他们住在一个共同用餐的意向社群。","why":"Here intention leaves the single mind and becomes a design for a group.","whyCN":"在这里，意图离开单个的心，变成为一群人做的设计。"},{"no":"06","title":"The meaning a speaker meant to convey","titleCN":"说话人有意传达的意思","definition":"in semantics, relating to the meaning a speaker meant rather than the literal one","definitionCN":"在语义学上，指说话人有意表达的意思，而非字面意思","example":"The intentional reading differs from the literal one.","exampleCN":"有意表达的那层读法与字面读法不同。","why":"Speech has an aim behind it, and meaning can be judged by that aim rather than by the words alone.","whyCN":"话语背后有目的，因此意义可以按那个目的来判断，而不只看字面。"},{"no":"07","title":"Calculated to produce an effect","titleCN":"为产生某种效果而计算的","definition":"done in a calculated way to produce a particular effect on others","definitionCN":"以经过计算的方式去做，以便对他人产生某种效果","example":"Her pause was intentional, timed to let the room go quiet.","exampleCN":"她的停顿是故意的，掐准了让全场安静下来的时机。","why":"An aim can be aimed at an audience, and the act is then a tool rather than a habit.","whyCN":"目的可以对准听众，行为于是成了工具，而不是习惯。"},{"no":"08","title":"A mark of purpose left on a thing","titleCN":"留在事物上的目的印记","definition":"the quality of carrying a visible trace of someone's purpose","definitionCN":"带着某人目的之可见痕迹的性质","example":"Every fold in the paper looked intentional.","exampleCN":"纸上的每一道折痕看起来都像是有意留下的。","why":"Purpose becomes visible as style, and what was planned reads as a mark on the surface.","whyCN":"目的以风格的形式变得可见，被筹划过的东西就表现为表面上的一道印记。"}],"etymology":{"intro":{"en":"Intentional is formed from intention plus the adjective ending -al, with a parallel Medieval Latin form intentionalis. Dates are approximate.","cn":"intentional 由 intention 加形容词词尾 -al 构成，中世纪拉丁语中也有并行的 intentionalis。年代均为约数。"},"items":[{"era":"LATIN INTENTIO","en":"The base noun intentio named a stretching or an aim, from intendere, to stretch toward.","cn":"基础名词 intentio 指拉伸或瞄准，来自表示「朝……伸展」的 intendere。"},{"era":"MEDIEVAL LATIN","en":"Scholastic Latin used intentionalis for qualities belonging to an intentio, especially in discussions of signs and thought.","cn":"经院拉丁语用 intentionalis 表示属于 intentio 的性质，尤见于关于符号与思想的讨论。"},{"era":"ENGLISH SIXTEENTH CENTURY","en":"English intentional appeared in the sixteenth century with the plain sense of done with a purpose.","cn":"英语 intentional 在十六世纪出现，带有「有目的而做」的朴素含义。"},{"era":"PHILOSOPHICAL REVIVAL","en":"Nineteenth and twentieth century philosophy revived the technical sense of being directed at an object.","cn":"十九与二十世纪的哲学复活了「指向对象」这一技术义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation is not fixed, and the philosophical sense entered through translation rather than through one author's coinage.","cn":"来源不确定：英语最早书证年代无定论；哲学义是经翻译进入的，并非某位作者独自创制。"}]},"similar":{"note":{"en":"The first group is built on the same intention stock but differs in word class or shade; the second holds adjectives of purposeful action.","cn":"第一组建立在同一个 intention 词干上，只是词性或侧重不同；第二组是表示「有目的行动」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"intention","ipa":"/ɪnˈtenʃn/","tag":"same root, noun","definition":"The noun that names the aim; intentional describes an act or design that carries it.","definitionCN":"命名目的的名词；intentional 则描述带着这个目的的行为或设计。"},{"word":"intent","ipa":"/ɪnˈtent/","tag":"same root, legal noun","definition":"A fixed purpose, especially in law; as an adjective it means absorbed or determined, not done on purpose.","definitionCN":"固定的目的，尤用于法律；作形容词时意为专注或坚决，而不是「故意」。"},{"word":"intentionality","ipa":"/ɪnˌtenʃəˈnæləti/","tag":"same root, abstract noun","definition":"The philosophical property of being about something; it names the property, while intentional describes what has it.","definitionCN":"哲学上「关于某物」的性质；它命名性质，intentional 描述具有该性质的东西。"},{"word":"inattentive","ipa":"/ˌɪnəˈtentɪv/","tag":"different prefix and sense","definition":"Not paying attention; it is formed with the negative prefix in- plus attentive, which itself comes from ad- meaning toward and tendere meaning stretch, so it describes notice rather than purpose.","definitionCN":"指不注意；它由否定前缀 in- 加 attentive 构成，而 attentive 本身来自 ad-「朝向」与 tendere「伸展」，因此它描述注意力，不描述目的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"deliberate","ipa":"/dɪˈlɪbərət/","tag":"weighed first","definition":"Done after careful consideration; intentional says a purpose was held, deliberate adds that the purpose was weighed.","definitionCN":"经过仔细考虑后做的；intentional 说怀有目的，deliberate 再加一层「目的经过权衡」。"},{"word":"purposeful","ipa":"/ˈpɜːpəsfəl/","tag":"full of aim","definition":"Showing a clear aim in behaviour; it describes the manner, while intentional marks the act as planned.","definitionCN":"在行为中显出明确目标；它描述方式，intentional 则标记行为是筹划过的。"},{"word":"designed","ipa":"/dɪˈzaɪnd/","tag":"made to a plan","definition":"Made according to a plan; intentional can describe a choice as well as an object.","definitionCN":"按方案做成的；intentional 既能描述物件，也能描述选择。"},{"word":"wilful","ipa":"/ˈwɪlfəl/","tag":"stubbornly intended","definition":"Done on purpose and often against advice; it adds a note of obstinacy that intentional does not carry.","definitionCN":"故意做的，且常是不听劝告地做；它多了「执拗」的意味，intentional 没有。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real noun base, the real adjective ending, the real family and the phrases the word keeps.","cn":"正常联想：真实的名词基础、真实的形容词词尾、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"intention plus -al: the ending turns a held aim into a description of an act.","cn":"intention 加 -al：这个词尾把怀有的目的变成对行为的描述。"},{"en":"The family runs intention, intentional, intentionally, intentionality and unintentional.","cn":"同族词包括 intention（意图）、intentional（故意的）、intentionally（故意地）、intentionality（意向性）、unintentional（无意的）。"},{"en":"Fixed phrases mark the field: intentional act, intentional damage, intentional omission.","cn":"固定搭配标出领域：故意行为、故意损害、有意省略。"},{"en":"Adding un- reverses it: unintentional means it happened without a held aim.","cn":"加上 un- 就反过来：unintentional 指没有怀着目的却发生了。"},{"en":"Philosophy uses the same word for thoughts being about objects, so the aim image stretches further.","cn":"哲学用同一个词表示思想「关于对象」，于是瞄准的形象伸得更远。"}],"abstract":[{"en":"Picture faint guide lines on a canvas before any colour arrives.","cn":"想象画布上先有淡淡的辅助线，颜色还没上。"},{"en":"Picture a pause held one beat longer than conversation requires.","cn":"想象一次停顿比对话所需多停了半拍。"},{"en":"Picture a fold pressed into paper by a deliberate thumb.","cn":"想象一根拇指有意在纸上压出一道折痕。"}]},"examples":[{"en":"The delay was intentional, not an oversight.","cn":"这次延迟是故意的，不是疏忽。"},{"en":"Critics praised the intentional spareness of the design.","cn":"评论家称赞这个设计有意为之的简洁。"},{"en":"The law treats intentional harm differently from negligence.","cn":"法律对故意伤害与过失的处理不同。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「因疼神诺」——心里揣着目的做事，每一步都不是白走 → intentional 故意的、有意的","word":"intentional"},"root":"由 intention 加形容词词尾 -al 构成；intention 来自拉丁 intentio，后者出自 intendere = in-「朝向」+ tendere「伸展」。","sensesIntro":{"en":"Eight senses follow one aim made visible: an act that was purposed, a design that shows it, a thought that points at an object, a blameworthy purpose, a planned community, a speaker's meaning, a calculated effect and a trace of purpose on a surface.","cn":"八个义项沿同一个被看见的目的展开：带着目的的行为、显出目的的设计、指向对象的思想、可责的目的、被筹划的社群、说话人的本意、经过计算的效果，以及留在表面上的目的痕迹。"},"semanticMap":{"core":{"en":"CORE IMAGE: faint guide lines drawn on a canvas before a single stroke of colour.","cn":"核心意象：画布上先画出淡淡的辅助线，颜色一笔都还没落。"},"chain":["AIM HELD","MEANS CHOSEN","OBJECT POINTED AT","WHOLE DESIGNED","RESULT ANSWERED FOR","PURPOSE VISIBLE"],"branches":[{"senses":"01 · 08","en":"PURPOSE VERSUS ACCIDENT: a held aim is what separates an intentional act from a chance event.","cn":"目的与偶然：怀着的目的，正是有意行为与偶然事件的分界。"},{"senses":"02 · 05","en":"DESIGN: a plan can shape an object or an entire shared life.","cn":"设计：方案既能塑造一件物件，也能塑造一整套共同生活。"},{"senses":"03 · 06","en":"DIRECTEDNESS: a thought points at an object, and a speaker points at a meaning.","cn":"指向性：思想指向对象，说话人指向意义。"},{"senses":"04","en":"BLAME: the law asks whether the aim deserves responsibility.","cn":"责任：法律追问这个目的是否应当担责。"},{"senses":"07","en":"CALCULATION: an act timed for an audience turns purpose into a tool.","cn":"计算：为听众掐准时机的行为，把目的变成了工具。"}]},"affixes":{"intro":{"en":"Intentional is a noun base plus a Latin adjective ending, and the base itself is built from a prefix and a verb of stretching.","cn":"intentional 是一个名词基础加拉丁形容词词尾，而这个基础本身又由前缀与表示伸展的动词构成。"},"latinIntro":{"en":"Latin intendere gives intention and intent, and the ending -al, from Latin -alis, turns the noun into a description; the same stock also gives attention.","cn":"拉丁语 intendere 衍生 intention 与 intent，来自拉丁语 -alis 的词尾 -al 把名词变成描述；同一词干还衍生 attention。"},"items":[{"word":"in-","structure":"in- (Latin prefix, toward)","meaning":"toward","meaningCN":"朝向","example":"The prefix also appears in intend and incline.","exampleCN":"这个前缀也出现在 intend（打算）与 incline（倾斜）里。"},{"word":"tendere","structure":"tendere (Latin verb, to stretch)","meaning":"to stretch; to extend","meaningCN":"伸展；拉长","example":"Its stem survives in tension.","exampleCN":"它的词干留在 tension（张力）里。"},{"word":"intention","structure":"intend + -ion (action noun)","meaning":"the aim held in mind","meaningCN":"心里怀着的意图","example":"The intention was never stated.","exampleCN":"这个意图从未被说明。"},{"word":"intentional","structure":"intention + -al (relational adjective)","meaning":"marked by a held aim","meaningCN":"带有既定目的的；故意的","example":"The choice was intentional.","exampleCN":"这个选择是故意的。"},{"word":"intentionally","structure":"intentional + -ly (adverb ending)","meaning":"in a purposeful manner","meaningCN":"以有目的的方式；故意地","example":"She spoke slowly, intentionally.","exampleCN":"她故意说得很慢。"},{"word":"intentionality","structure":"intentional + -ity (abstract noun)","meaning":"the property of being about something","meaningCN":"关于某物的性质；意向性","example":"The debate concerns intentionality.","exampleCN":"这场争论关乎意向性。"},{"word":"unintentional","structure":"un- (not) + intentional","meaning":"done without a held aim","meaningCN":"没有怀着目的而做的；无意的","example":"The slight was unintentional.","exampleCN":"这次冒犯是无意的。"},{"word":"attention","structure":"ad- (toward) + tendere + -ion, a parallel formation","meaning":"the mind turned toward something","meaningCN":"心转向某物；注意","example":"The detail escaped my attention.","exampleCN":"这个细节没引起我的注意。"}],"latinEntries":[{"word":"intendere","structure":"intendere, intendi, intentum (verb, third conjugation)","meaning":"to stretch toward, aim at","meaningCN":"朝……伸展；瞄准"},{"word":"intentio","structure":"intentio, intentionis (f., third declension)","meaning":"a stretching, aim, attention","meaningCN":"拉伸；意图；注意"},{"word":"intentus","structure":"intentus, -a, -um (adjective)","meaning":"stretched tight, attentive","meaningCN":"绷紧的；专注的"},{"word":"-alis","structure":"-alis (Latin adjective suffix, relating to)","meaning":"relating to; belonging to","meaningCN":"与……相关的；属于……的"}],"derivatives":[{"word":"intentionally","structure":"intentional + -ly (adverb) → in the manner of a held aim","meaning":"on purpose","meaningCN":"故意地"},{"word":"intentionality","structure":"intentional + -ity (abstract noun) → the property of pointing at an object","meaning":"aboutness of thought","meaningCN":"意向性"},{"word":"unintentional","structure":"un- (negation) + intentional → without a held aim","meaning":"not done on purpose","meaningCN":"无意的"},{"word":"unintentionally","structure":"unintentional + -ly (adverb) → without meaning to","meaning":"by accident","meaningCN":"无意地"},{"word":"intent","structure":"intend + participle form → the aim as a fixed fact","meaning":"a settled purpose","meaningCN":"意图；目的"}]}},{"word":"deliberate","ipa_uk":"/dɪˈlɪbərət/","ipa_us":"/dɪˈlɪbərət/","definition_zh":"故意的；从容的；审慎的；仔细考虑；正式商议","definition_en":"done after careful thought, or to think about something carefully before acting","core_image":"一只手上托着天平，两端各放一枚砝码，指针慢慢停在中线","scene":"议事厅里，议员们把两份预算摆在长桌上逐条比对，The council deliberated for two hours before the vote.","sceneCN":"这里 deliberate 指「仔细商议、反复考虑」（第 4 个义项：作动词表示仔细考虑或商议）；句意为议会在投票前商议了两个小时。图中可辨识物件：长桌、两份预算册、天平、投票箱。","pos":[{"tag":"adj.","zh":"故意的；从容的；审慎的"},{"tag":"vi./vt.","zh":"仔细考虑；正式商议"}],"collocations":[{"phrase":"deliberate attempt","zh":"故意的尝试"},{"phrase":"deliberate choice","zh":"有意的选择"},{"phrase":"deliberate speed","zh":"从容的速度"},{"phrase":"deliberate on","zh":"就……进行商议"},{"phrase":"deliberate over","zh":"反复斟酌……"},{"phrase":"deliberate carefully","zh":"仔细权衡"}],"forms":[{"label":"原级（形容词）","form":"deliberate"},{"label":"比较级","form":"more deliberate"},{"label":"最高级","form":"most deliberate"},{"label":"三单（动词）","form":"deliberates"},{"label":"过去式","form":"deliberated"},{"label":"过去分词","form":"deliberated"},{"label":"现在分词","form":"deliberating"},{"label":"名词（审议；从容）","form":"deliberation"},{"label":"形容词（审议的）","form":"deliberative"},{"label":"副词（故意地；从容地）","form":"deliberately"}],"derivatives":[{"word":"deliberately","pos":"adv.","zh":"故意地；从容地"},{"word":"deliberation","pos":"n.","zh":"审议；仔细考虑；从容"},{"word":"deliberative","pos":"adj.","zh":"审议的；商议性的"},{"word":"deliberateness","pos":"n.","zh":"故意；从容"}],"senses":[{"no":"01","title":"Done on purpose","titleCN":"故意做的","definition":"done intentionally rather than by accident","definitionCN":"出于有意而非偶然地做","example":"The insult was deliberate.","exampleCN":"那句侮辱是故意的。","why":"The Latin verb meant to weigh thoroughly, so an act done on purpose is one whose weight was felt beforehand.","whyCN":"这个拉丁动词意为「彻底称量」，因此故意的行为就是事先掂过分量的行为。"},{"no":"02","title":"Slow and steady in movement","titleCN":"动作缓慢而稳","definition":"unhurried and steady, especially in movement or pace","definitionCN":"不慌不忙、平稳，尤指动作或速度","example":"He crossed the room with deliberate steps.","exampleCN":"他以从容的步子穿过房间。","why":"A weighed action is not rushed, so the same word came to describe a controlled pace.","whyCN":"称量过的动作不会匆忙，因此同一个词也用来描述受控的速度。"},{"no":"03","title":"Careful and considered","titleCN":"仔细而周到的","definition":"showing care and thought in judgment or style","definitionCN":"在判断或风格上显出用心与思考","example":"The report is a deliberate piece of work.","exampleCN":"这份报告是一件用心斟酌的作品。","why":"What is weighed before it is made keeps the marks of the scale in its finish.","whyCN":"做事之前称量过的东西，会在成品上留下天平的痕迹。"},{"no":"04","title":"Think carefully before deciding","titleCN":"作决定前仔细考虑","definition":"to consider a matter carefully before making a choice","definitionCN":"在作出选择之前仔细考虑一件事","example":"The jury deliberated for a day.","exampleCN":"陪审团考虑了一整天。","why":"The verb keeps the literal act: the mind holds the matter on a scale until it settles.","whyCN":"动词保留了字面动作：心把事情托在天平上，直到它稳定下来。"},{"no":"05","title":"Discuss a matter formally","titleCN":"就某事正式商议","definition":"to discuss and weigh a matter in a formal assembly","definitionCN":"在正式会议上讨论并权衡一件事","example":"The committee deliberated on the merger.","exampleCN":"委员会就合并一事进行了商议。","why":"Weighing is shared when a body must reach one decision, so the verb moved from one mind to many.","whyCN":"当一个机构必须得出同一个决定时，称量就成了共同的事，动词于是从一颗心移到许多颗心。"},{"no":"06","title":"Measured in speech","titleCN":"说话有分寸的","definition":"of speech, slow and restrained, with each word placed carefully","definitionCN":"指说话缓慢克制，每个字都放得很稳","example":"She spoke in a deliberate whisper.","exampleCN":"她用一种有分寸的低语说话。","why":"Speech can be weighed word by word, and then the adjective describes the manner rather than the decision.","whyCN":"话语可以一个字一个字地称量，这时形容词描述的是方式，而不是决定。"},{"no":"07","title":"Unhurried in manner","titleCN":"举止从容的","definition":"of a person, steady and unhurried in manner","definitionCN":"指一个人举止沉稳、不慌不忙","example":"A deliberate man, he never answered at once.","exampleCN":"他是个从容的人，从不马上回答。","why":"A person who weighs everything acquires the pace of the scale, and the word becomes a trait.","whyCN":"凡事都称量的人会沾上天平的节奏，这个词于是变成一种性格。"},{"no":"08","title":"Weighed against alternatives","titleCN":"与各种可能反复权衡过的","definition":"settled only after comparing the weight of competing considerations","definitionCN":"在比较过各种相互竞争的分量之后才定下的","example":"Every clause was deliberate, weighed against the others.","exampleCN":"每一条款都是权衡过的，与其余条款彼此称量。","why":"The core image is comparison itself: nothing is chosen until the other pan has been felt.","whyCN":"核心形象就是比较本身：不先感受另一端的盘子，就什么也不选。"}],"etymology":{"intro":{"en":"Deliberate comes from Latin deliberare, to weigh thoroughly, built on de- and librare, from libra meaning a balance. Dates are approximate.","cn":"deliberate 来自拉丁语 deliberare「彻底称量」，由 de- 与 librare 构成，后者出自表示「天平」的 libra。年代均为约数。"},"items":[{"era":"LATIN LIBRA","en":"Libra meant a balance or a pair of scales, and it also named a unit of weight. Its deeper origin is uncertain, so any older root proposed for it is a reconstruction.","cn":"libra 意为「天平、秤」，也指一个重量单位。它更深的来源不确定，因此为它提出的更早词根都属重构形式。"},{"era":"LATIN LIBRARE","en":"Librare meant to weigh or to balance, and it kept the concrete image of holding something level on a scale.","cn":"librare 意为「称量、使平衡」，保留了把东西放在秤上使之水平的具象画面。"},{"era":"LATIN DELIBERARE","en":"De- plus librare produced deliberare, to weigh thoroughly or to consult, and Latin already used it for both thinking and assembly.","cn":"de- 加 librare 构成 deliberare，意为「彻底称量、商议」，拉丁语里已兼指思考与集会讨论。"},{"era":"ENGLISH ADJECTIVE","en":"The adjective appeared in English in the early fifteenth century with the sense of done with consideration.","cn":"形容词在十五世纪初进入英语，意为「经过考虑的」。"},{"era":"ENGLISH VERB","en":"The verb use is recorded later than the adjective, and reference works differ on the exact date.","cn":"动词用法的记录晚于形容词，各家参考资料对确切年代说法不一。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the deeper origin of libra is unsettled, and the first English citations for both word classes are given differently across reference works.","cn":"来源不确定：libra 的更早来源无定论；两个词性在英语中的最早书证，各家参考资料给出的年代也不一致。"}]},"similar":{"note":{"en":"The first group shares the Latin stock of weighing but differs in form; the second holds words for careful or intended action. One look-alike has a different root.","cn":"第一组共享拉丁语「称量」的词干，只是形态不同；第二组是表示仔细或有意图的行动的词。有一个形似词词根不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"deliberation","ipa":"/dɪˌlɪbəˈreɪʃn/","tag":"same root, noun","definition":"The act of weighing a matter, especially in an assembly; it names the process, while deliberate names the act or the quality.","definitionCN":"权衡一件事的动作，尤指在会议中；它命名过程，而 deliberate 命名动作或性质。"},{"word":"deliberative","ipa":"/dɪˈlɪbərətɪv/","tag":"same root, adjective","definition":"Describing a body whose function is to discuss and weigh, such as a council; it describes a role, not a person's pace.","definitionCN":"描述以讨论和权衡为职能的机构，如议会；它描述职能，而不是人的步调。"},{"word":"deliberately","ipa":"/dɪˈlɪbərətli/","tag":"same root, adverb","definition":"The adverb from the adjective, used for actions done on purpose or at a measured pace.","definitionCN":"由形容词变来的副词，用于有意做出的行为或有节制的步调。"},{"word":"liberate","ipa":"/ˈlɪbəreɪt/","tag":"different origin","definition":"From Latin liber meaning free, not libra meaning a balance; the resemblance is accidental.","definitionCN":"来自拉丁语 liber「自由的」，而非 libra「天平」；形似只是巧合。"}]},{"heading":"NEAR MEANING","entries":[{"word":"intentional","ipa":"/ɪnˈtenʃənl/","tag":"purpose held","definition":"Done with a held aim; deliberate adds that the aim was weighed before it was adopted.","definitionCN":"带着既定目的做的；deliberate 再加一层「目的在采纳之前被权衡过」。"},{"word":"purposeful","ipa":"/ˈpɜːpəsfəl/","tag":"clearly aimed","definition":"Showing a clear aim in behaviour; it does not say whether the aim was weighed.","definitionCN":"在行为中显出明确目标；它不说这个目的有没有被权衡过。"},{"word":"unhurried","ipa":"/ʌnˈhʌrid/","tag":"pace only","definition":"Moving without haste; it describes pace alone, while deliberate also carries intention.","definitionCN":"不慌不忙地移动；它只描述速度，而 deliberate 还带着意图。"},{"word":"consider","ipa":"/kənˈsɪdə/","tag":"the plain verb","definition":"To think about something; deliberate is its more formal relative and often implies weighing alternatives.","definitionCN":"思考某事；deliberate 是它更正式的亲属词，常含权衡各种替代项之意。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the root of the balance, the real family and the phrases the word keeps.","cn":"正常联想：真实的前缀、表示天平的古词根、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"de- plus librare from libra, a balance: to weigh something thoroughly before acting.","cn":"de- 加出自 libra「天平」的 librare：行动之前先彻底称一称。"},{"en":"The family runs deliberate, deliberately, deliberation, deliberative and deliberateness.","cn":"同族词包括 deliberate（故意的）、deliberately（故意地）、deliberation（审议）、deliberative（审议的）、deliberateness（故意）。"},{"en":"Fixed phrases mark the field: deliberate attempt, deliberate choice, deliberate speed, deliberate on.","cn":"固定搭配标出领域：故意的尝试、有意的选择、从容的速度、就……商议。"},{"en":"A deliberative body is one whose job is to weigh, so the adjective describes the institution.","cn":"审议机构就是以权衡为职责的机构，因此这个形容词描述的是制度。"},{"en":"Liberate looks close but comes from free, not from a balance, so the two should not be confused.","cn":"liberate 看似相近，却来自「自由」而不是「天平」，两者不应混淆。"}],"abstract":[{"en":"Picture a balance that takes a long time to stop moving.","cn":"想象一架天平要很久才停止摆动。"},{"en":"Picture a hand placing one coin on a scale, then waiting.","cn":"想象一只手把一枚硬币放上秤，然后等着。"},{"en":"Picture a speaker who lets a full second pass before each sentence.","cn":"想象一个人每句话之前都留足一秒钟。"}]},"examples":[{"en":"The leak was a deliberate act, not an error.","cn":"这次泄露是故意行为，不是失误。"},{"en":"She walked at a deliberate pace down the corridor.","cn":"她以从容的步伐走过走廊。"},{"en":"The senate deliberated on the treaty for three days.","cn":"参议院就这项条约商议了三天。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「地里拨拉」——把每颗种子都拨拉过来称一称再种 → deliberate 仔细权衡的","word":"deliberate"},"root":"拉丁 deliberare「彻底称量、商议」= de- + librare「称量」，librare 出自 libra「天平、秤」；libra 更早的来源不确定。英语 deliberate 经法语进入。","sensesIntro":{"en":"Eight senses follow one balance: a matter is held level, weighed, given time, compared with others, settled, and then the same steadiness shows in speech, in a person and in a finished work.","cn":"八个义项沿同一架天平展开：把事情托平、称量、留出时间、与别的放在一起比较、定下来；随后同一种稳当又显现在话语里、一个人身上和一件成品里。"},"semanticMap":{"core":{"en":"CORE IMAGE: a balance held in one hand, one weight in each pan, the needle settling on the middle line.","cn":"核心意象：一只手托着天平，两端各有一枚砝码，指针慢慢停在中线。"},"chain":["PLACE ON THE SCALE","WEIGH IT","GIVE IT TIME","COMPARE THE PANS","SETTLE THE ACT","KEEP THE PACE"],"branches":[{"senses":"01 · 02","en":"PURPOSE AND PACE: an act that was weighed is both intended and unhurried.","cn":"目的与步调：被称量过的行为既是有意的，也是不慌不忙的。"},{"senses":"03 · 07","en":"CAREFUL MANNER: the finish of a work and the manner of a person both show the same steadiness.","cn":"用心的举止：成品的完成度与人的举止，显出同一种稳当。"},{"senses":"04 · 08","en":"WEIGHING: thinking and comparing alternatives are the same act on the scale.","cn":"权衡：独自思考与比较各种替代项，是天平上的同一个动作。"},{"senses":"05","en":"SHARED SCALE: an assembly weighs one matter with many minds.","cn":"共用的天平：一个机构用许多颗心共同称量一件事。"},{"senses":"06","en":"MEASURED SPEECH: words are placed one by one, as weights on a pan.","cn":"有分寸的话语：字一个一个放上去，像往盘里加砝码。"}]},"affixes":{"intro":{"en":"Deliberate can be read from a Latin prefix and a verb of weighing that also builds a small English family.","cn":"deliberate 可以按一个拉丁前缀与一个表示「称量」的动词逐段读出，这两部分也构成一小族英语词。"},"latinIntro":{"en":"Latin libra gives librare and deliberare; the same noun also names the zodiac sign Libra and the unit of weight.","cn":"拉丁语 libra 衍生 librare 与 deliberare；同一个名词还命名黄道十二宫的天秤座与重量单位。"},"items":[{"word":"de-","structure":"de- (Latin prefix, thoroughly, down)","meaning":"thoroughly; down","meaningCN":"彻底；向下","example":"The prefix also appears in declare and descend.","exampleCN":"这个前缀也出现在 declare（宣布）与 descend（下降）里。"},{"word":"libra","structure":"libra (Latin noun, balance, scales)","meaning":"a balance; a pair of scales","meaningCN":"天平；秤","example":"The noun also gives the name Libra.","exampleCN":"这个名词也是天秤座名称的来源。"},{"word":"librare","structure":"librare (Latin verb, to weigh, balance)","meaning":"to weigh; to make level","meaningCN":"称量；使平衡","example":"The verb keeps the image of a level beam.","exampleCN":"这个动词保留了横梁水平的形象。"},{"word":"deliberate","structure":"de- + librare","meaning":"to weigh thoroughly, hence to consider","meaningCN":"彻底称量，因而仔细考虑","example":"They deliberated before signing.","exampleCN":"他们在签署之前反复权衡。"},{"word":"deliberation","structure":"deliberate + -ion (action noun)","meaning":"the act of weighing a matter","meaningCN":"审议；权衡","example":"The deliberation lasted a week.","exampleCN":"审议持续了一周。"},{"word":"deliberative","structure":"deliberate + -ive (tending adjective)","meaning":"given to weighing matters","meaningCN":"以权衡审议为职能的","example":"The assembly is deliberative, not executive.","exampleCN":"这个机构负责审议，而非执行。"},{"word":"deliberately","structure":"deliberate + -ly (adverb ending)","meaning":"on purpose, or at a measured pace","meaningCN":"故意地；从容地","example":"He moved deliberately toward the door.","exampleCN":"他从容地朝门口走去。"},{"word":"deliberateness","structure":"deliberate + -ness (quality)","meaning":"the quality of being weighed and intentional","meaningCN":"有意而经权衡的性质","example":"The deliberateness of her tone was unmistakable.","exampleCN":"她语气中的刻意十分明显。"}],"latinEntries":[{"word":"libra","structure":"libra, librae (f., first declension)","meaning":"balance, scales; a unit of weight","meaningCN":"天平；秤；重量单位"},{"word":"librare","structure":"librare, libravi, libratum (verb, first conjugation)","meaning":"to weigh, balance","meaningCN":"称量；使平衡"},{"word":"deliberare","structure":"deliberare, deliberavi, deliberatum (verb, first conjugation)","meaning":"to weigh thoroughly, consult","meaningCN":"彻底权衡；商议"},{"word":"deliberatio","structure":"deliberatio, deliberationis (f., third declension)","meaning":"a weighing, a consultation","meaningCN":"权衡；商议"}],"derivatives":[{"word":"deliberately","structure":"deliberate + -ly (adverb) → in a weighed or intentional manner","meaning":"on purpose; without haste","meaningCN":"故意地；从容地"},{"word":"deliberation","structure":"deliberate + -ion (action noun) → the process of weighing a matter","meaning":"careful discussion","meaningCN":"审议；权衡"},{"word":"deliberative","structure":"deliberate + -ive (tendency adjective) → given to weighing matters","meaning":"having a role of discussion","meaningCN":"审议的"},{"word":"deliberateness","structure":"deliberate + -ness (quality) → the state of being weighed","meaning":"intentional and unhurried quality","meaningCN":"有意而从容"}]}},{"word":"impulse","ipa_uk":"/ˈɪmpʌls/","ipa_us":"/ɪmˈpʌls/","definition_zh":"冲动；突发的行动欲望；推动力；刺激；[物理] 冲量；[神经] 神经冲动；[电子] 脉冲","definition_en":"a sudden urge to act, or a force that drives something forward","core_image":"一只手刚要伸向橱窗里的蛋糕，另一只手在手腕上轻轻按住","scene":"商场橱窗前，一个人原本只想路过，An impulse made him stop and buy the cake in the window.","sceneCN":"这里 impulse 指「突然想做某事的冲动」（第 1 个义项：突发的行动欲望）；句意为一股冲动让他停下来买橱窗里的蛋糕。图中可辨识物件：橱窗、蛋糕、购物袋、玻璃反光。","pos":[{"tag":"n.","zh":"冲动；突发的欲望；推动力；冲量；神经冲动；脉冲"}],"collocations":[{"phrase":"on impulse","zh":"一时冲动之下"},{"phrase":"impulse buying","zh":"冲动购买"},{"phrase":"a sudden impulse","zh":"突然的冲动"},{"phrase":"resist an impulse","zh":"克制冲动"},{"phrase":"act on impulse","zh":"凭冲动行事"},{"phrase":"first impulse","zh":"第一反应；最初的冲动"}],"forms":[{"label":"复数","form":"impulses"},{"label":"形容词（冲动的）","form":"impulsive"},{"label":"副词（冲动地）","form":"impulsively"},{"label":"名词（冲动性）","form":"impulsiveness"},{"label":"动词（推动）","form":"impel"}],"derivatives":[{"word":"impulsive","pos":"adj.","zh":"冲动的；凭冲动行事的"},{"word":"impulsively","pos":"adv.","zh":"冲动地"},{"word":"impulsiveness","pos":"n.","zh":"冲动性"},{"word":"impel","pos":"v.","zh":"推动；驱使"}],"senses":[{"no":"01","title":"A sudden urge to act","titleCN":"突然想做某事的冲动","definition":"a sudden strong wish to do something, often without planning","definitionCN":"突然产生的强烈行动欲望，常未经计划","example":"She felt an impulse to laugh.","exampleCN":"她突然想笑。","why":"The Latin verb means to drive against, so the urge arrives like a push from inside the body.","whyCN":"这个拉丁动词意为「朝前推」，因此冲动像从身体内部推来的一股力。"},{"no":"02","title":"A push or stimulus from outside","titleCN":"来自外部的推动或刺激","definition":"a force or stimulus that drives something to move or respond","definitionCN":"促使某物移动或作出反应的力量或刺激","example":"The first impulse came from the crowd outside.","exampleCN":"最初的推动来自外面的人群。","why":"The push need not begin inside a person; any external force that starts a movement is an impulse.","whyCN":"推力不必起于人的内部；任何引发运动的外力都是冲量意义上的推动。"},{"no":"03","title":"Force multiplied by time in physics","titleCN":"物理中力与时间的乘积","definition":"in physics, the product of a force and the time during which it acts","definitionCN":"物理学中，一个力与它作用时间的乘积","example":"The impulse changed the cart's momentum.","exampleCN":"这个冲量改变了小车的动量。","why":"Physics measures a push by how long it lasts, so the word becomes a precise quantity.","whyCN":"物理学用推力持续多久来度量推，于是这个词成了一个精确的量。"},{"no":"04","title":"A signal travelling along a nerve","titleCN":"沿神经传导的信号","definition":"a brief electrical change that travels along a nerve fibre","definitionCN":"沿神经纤维传导的短暂电变化","example":"The nerve carries impulses from the finger to the spine.","exampleCN":"神经把冲动从手指传到脊柱。","why":"A signal is a short burst of driving force, so physiology borrowed the same word.","whyCN":"信号是一小段驱动力的爆发，因此生理学也借用了这个词。"},{"no":"05","title":"A short burst of signal in electronics","titleCN":"电子学中的短促信号脉冲","definition":"a short sudden change in voltage or current, used to carry information","definitionCN":"电压或电流的短促突变，用来承载信息","example":"Each key sends an impulse to the circuit.","exampleCN":"每按一个键，都会向电路发出一个脉冲。","why":"The physical push shrinks to a brief burst, and the word follows it into circuitry.","whyCN":"物理的推力缩小成一次短暂爆发，这个词便跟着进入电路。"},{"no":"06","title":"A purchase made without planning","titleCN":"未经计划的购买","definition":"a purchase made suddenly, without prior planning","definitionCN":"没有事先计划、突然作出的购买","example":"The chocolates were an impulse at the checkout.","exampleCN":"这些巧克力是结账时一时冲动买的。","why":"Commerce names the urge by its result, so the bought thing becomes an impulse.","whyCN":"商业用结果来命名欲望，于是被买下的东西本身就成了「冲动」。"},{"no":"07","title":"The drive behind creative work","titleCN":"创作背后的驱动力","definition":"a strong inner drive that leads to creative work","definitionCN":"促使人创作作品的强烈内在驱动","example":"He painted from an impulse rather than a plan.","exampleCN":"他作画是凭一股冲动，而不是按计划。","why":"The surge that moves the hand can also move the brush, and art calls it an impulse.","whyCN":"推动手的那股涌动也能推动画笔，艺术便称之为冲动。"},{"no":"08","title":"The drive behind behaviour","titleCN":"行为背后的心理驱力","definition":"in psychology, an inner force that pushes a person toward action","definitionCN":"心理学中，促使人行动的内在力量","example":"The therapist traced the impulse behind his spending.","exampleCN":"治疗师追溯他消费行为背后的驱力。","why":"Psychology formalizes the push as a drive, keeping the physics of motion inside the mind.","whyCN":"心理学把这股推力正式化为驱力，把运动的物理留在了心里。"}],"etymology":{"intro":{"en":"Impulse comes from Latin impulsus, a noun of action from impellere, to drive into or against. Dates are approximate.","cn":"impulse 来自拉丁语 impulsus，是动词 impellere 的动名词，后者意为「推入、推向」。年代均为约数。"},"items":[{"era":"LATIN PELLERE","en":"Pellere meant to push or drive. Its older Indo-European source is reconstructed as a root meaning to thrust or strike, and that form is not recorded.","cn":"pellere 意为「推、驱动」。它更早的印欧语来源被重构为一个表示「推、击」的词根，该词形没有记录。"},{"era":"LATIN IMPELLERE","en":"In- meaning into plus pellere produced impellere, to drive into or against something.","cn":"in-「进入」加 pellere 构成 impellere，意为「推入、撞向某物」。"},{"era":"LATIN IMPULSUS","en":"The noun impulsus named a push or a shock, and classical Latin already used it for both physical and mental driving.","cn":"名词 impulsus 指推击或冲击，古典拉丁语已用它兼指物理与心理上的驱动。"},{"era":"ENGLISH SIXTEENTH CENTURY","en":"English adopted impulse in the sixteenth century, first as a physical push and soon after as a sudden urge.","cn":"英语在十六世纪引入 impulse，先指物理的推击，很快又指突然的欲望。"},{"era":"SCIENTIFIC SENSES","en":"Physics, physiology and electronics each gave the word a precise technical sense from the nineteenth century onward.","cn":"物理学、生理学与电子学从十九世纪起各自赋予这个词一个精确的技术义。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation is not fixed, and the pre-Latin root of pellere is a reconstruction rather than a recorded word.","cn":"来源不确定：英语最早书证年代无定论；pellere 在拉丁语之前的词根属重构形式，并非有记录的真实词。"}]},"similar":{"note":{"en":"The first group shares the Latin verb pellere but differs in prefix; the second holds words for urges and driving forces. One look-alike comes from a different root.","cn":"第一组共享拉丁动词 pellere，只是前缀不同；第二组是表示欲望与驱动力的词。有一个形似词来自不同词根。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impel","ipa":"/ɪmˈpel/","tag":"same root, verb","definition":"To drive someone to act; it is the verb behind the noun impulse.","definitionCN":"驱使某人行动；它正是名词 impulse 背后的动词。"},{"word":"compel","ipa":"/kəmˈpel/","tag":"same root, stronger","definition":"Com- plus pellere: to drive together or force; it implies pressure that leaves little choice.","definitionCN":"com- 加 pellere：驱使到一处或强迫；它含几乎没有选择余地的压力。"},{"word":"repel","ipa":"/rɪˈpel/","tag":"same root, opposite direction","definition":"Re- meaning back plus pellere: to drive away, as a surface drives off water.","definitionCN":"re-「向后」加 pellere：把东西推走，如同表面把水排开。"},{"word":"impetus","ipa":"/ˈɪmpɪtəs/","tag":"different root","definition":"From Latin impetere, built on petere meaning to seek or attack, not pellere; it means momentum or driving force.","definitionCN":"来自拉丁语 impetere，词根是 petere「寻求、攻击」而非 pellere；意为势头或推动力。"}]},{"heading":"NEAR MEANING","entries":[{"word":"urge","ipa":"/ɜːdʒ/","tag":"the feeling itself","definition":"A strong desire to do something; impulse adds the note of suddenness and of arriving without planning.","definitionCN":"想做某事的强烈愿望；impulse 多了「突然」与「未经计划」两层意思。"},{"word":"drive","ipa":"/draɪv/","tag":"sustained force","definition":"A continuing force that keeps someone working; an impulse is usually a short burst.","definitionCN":"使人持续工作的力量；impulse 通常是短促的一次爆发。"},{"word":"stimulus","ipa":"/ˈstɪmjələs/","tag":"outside trigger","definition":"Something external that causes a response; impulse can also name the inner wish.","definitionCN":"引起反应的外在事物；impulse 也可以指内在的欲望。"},{"word":"momentum","ipa":"/məˈmentəm/","tag":"motion already gained","definition":"The force of a body already moving; an impulse is what starts or changes that motion.","definitionCN":"已经在运动的物体所具有的力；impulse 是启动或改变该运动的推击。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the root of driving, the real family and the phrases the noun keeps.","cn":"正常联想：真实的前缀、表示「驱动」的词根、真实的同族词，以及这个名词实际常用的搭配。"},"normal":[{"en":"in- meaning into plus pellere meaning drive: a push that enters and sets something moving.","cn":"in-「进入」加 pellere「驱动」：一股推进来，把东西带动起来。"},{"en":"The family runs impulse, impel, impulsive, impulsively and impulsiveness.","cn":"同族词包括 impulse（冲动）、impel（推动）、impulsive（冲动的）、impulsively（冲动地）、impulsiveness（冲动性）。"},{"en":"Fixed phrases mark the field: on impulse, impulse buying, resist an impulse, act on impulse.","cn":"固定搭配标出领域：一时冲动、冲动购买、克制冲动、凭冲动行事。"},{"en":"Physics measures impulse as force times time, which makes the everyday push exact.","cn":"物理学把冲量度量成力乘时间，让日常的「推」变得精确。"},{"en":"Impetus looks like impulse but comes from seeking, not driving, so the roots differ.","cn":"impetus 看似与 impulse 同族，却来自「寻求」而不是「驱动」，词根并不相同。"}],"abstract":[{"en":"Picture a hand reaching for a cake and another hand holding the wrist.","cn":"想象一只手伸向蛋糕，另一只手按住了手腕。"},{"en":"Picture a short shove that sends a swing moving and then lets it coast.","cn":"想象一次短促的推，把秋千送出去，然后任它滑行。"},{"en":"Picture a spark crossing a gap for only a moment.","cn":"想象一粒火花只一瞬间穿过缝隙。"}]},"examples":[{"en":"He bought the guitar on impulse and never learned to play.","cn":"他一时冲动买了那把吉他，却一直没学。"},{"en":"Her first impulse was to deny everything.","cn":"她的第一反应是把一切都否认掉。"},{"en":"A nerve impulse travels faster than a spoken word can follow.","cn":"神经冲动的传导比话语跟得上的速度还快。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「一木炮死」——一股劲突然推过来，人还没想就先动了 → impulse 冲动","word":"impulse"},"root":"拉丁 impulsus「推击、冲击」来自 impellere = in-「进入」+ pellere「推、驱动」；pellere 更早的印欧语词根被重构为表示「推、击」的形式。英语 impulse 经法语进入。","sensesIntro":{"en":"Eight senses follow one push: a surge inside a person, a force from outside, a measured quantity in physics, a signal in a nerve, a burst in a circuit, a sudden purchase, a creative drive and a psychological drive.","cn":"八个义项沿同一次推动展开：人体内的一股涌动、外部的一股力、物理学里可度量的量、神经里的信号、电路里的爆发、突如其来的购买、创作上的驱动，以及心理上的驱力。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand reaching for a cake while another hand presses the wrist down.","cn":"核心意象：一只手已经伸向蛋糕，另一只手把它的手腕按下去。"},"chain":["SURGE WITHIN","PUSH FROM OUTSIDE","SHORT BURST","SIGNAL ALONG A NERVE","FORCE OVER TIME","DRIVE BEHIND ACTION"],"branches":[{"senses":"01 · 06","en":"URGE AND PURCHASE: the wish arrives suddenly and is sometimes named by the thing it bought.","cn":"欲望与购买：愿望突然到来，有时又被它所买下的东西命名。"},{"senses":"02 · 08","en":"PUSH AND DRIVE: an outside stimulus and an inner drive are the same force seen from two sides.","cn":"推力与驱力：外在刺激与内在驱动是同一股力从两边看。"},{"senses":"03 · 05","en":"MEASURED BURST: physics turns the push into force over time, and electronics into a pulse.","cn":"可度量的爆发：物理学把推力变成力乘时间，电子学把它变成脉冲。"},{"senses":"04","en":"NERVE SIGNAL: the body carries the same burst along a fibre.","cn":"神经信号：身体把同样的爆发沿纤维传下去。"},{"senses":"07","en":"CREATIVE DRIVE: the surge that moves a hand can also move a brush.","cn":"创作驱动：推动手的那股涌动，也能推动画笔。"}]},"affixes":{"intro":{"en":"Impulse can be read from a Latin prefix and a verb of driving that also build a wide English family.","cn":"impulse 可以按一个拉丁前缀与一个表示「驱动」的动词逐段读出，两者还构成一大族英语词。"},"latinIntro":{"en":"Latin pellere gives impel, compel, expel, repel and propel through related forms; in- adds direction into something.","cn":"拉丁语 pellere 通过相关形态衍生 impel、compel、expel、repel 与 propel；in- 加上「进入某物」的方向。"},"items":[{"word":"in-","structure":"in- (Latin prefix, into, against)","meaning":"into; against","meaningCN":"进入；朝向","example":"The prefix also appears in inject and invade.","exampleCN":"这个前缀也出现在 inject（注入）与 invade（侵入）里。"},{"word":"pellere","structure":"pellere (Latin verb, to drive, push)","meaning":"to drive; to push","meaningCN":"驱动；推","example":"Its stem survives in propel and repel.","exampleCN":"它的词干留在 propel（推进）与 repel（击退）里。"},{"word":"impulse","structure":"in- + pellere (noun form)","meaning":"a push, hence a sudden urge","meaningCN":"一推，因而指突然的冲动","example":"He acted on impulse.","exampleCN":"他凭冲动行事。"},{"word":"impel","structure":"in- + pellere (verb)","meaning":"to drive someone to act","meaningCN":"驱使某人行动","example":"Fear impelled her to run.","exampleCN":"恐惧驱使她跑起来。"},{"word":"impulsive","structure":"impulse + -ive (tending adjective)","meaning":"acting on a sudden push","meaningCN":"凭一时冲动行事的","example":"It was an impulsive decision.","exampleCN":"那是个冲动的决定。"},{"word":"impulsively","structure":"impulsive + -ly (adverb ending)","meaning":"in a sudden, unplanned way","meaningCN":"以突然、无计划的方式","example":"She left impulsively.","exampleCN":"她一时冲动就离开了。"},{"word":"impulsiveness","structure":"impulsive + -ness (quality)","meaning":"the tendency to act on sudden urges","meaningCN":"凭冲动行事的倾向","example":"His impulsiveness cost him the job.","exampleCN":"他的冲动让他丢了工作。"},{"word":"compel","structure":"com- (together, strongly) + pellere","meaning":"to force someone to act","meaningCN":"强迫某人行动","example":"The law compels disclosure.","exampleCN":"法律强制要求披露。"},{"word":"propel","structure":"pro- (forward) + pellere","meaning":"to drive forward","meaningCN":"向前推进","example":"The engine propels the boat.","exampleCN":"发动机推动船只前进。"}],"latinEntries":[{"word":"pellere","structure":"pellere, pepuli, pulsum (verb, third conjugation)","meaning":"to drive, push, strike","meaningCN":"驱动；推；击"},{"word":"impellere","structure":"impellere, impuli, impulsum (verb, third conjugation)","meaning":"to drive into, impel","meaningCN":"推入；驱使"},{"word":"impulsus","structure":"impulsus, impulsus (m., fourth declension)","meaning":"a push, a shock","meaningCN":"推击；冲击"},{"word":"pulsus","structure":"pulsus, pulsus (m., fourth declension)","meaning":"a beating, a pulse","meaningCN":"跳动；脉搏"}],"derivatives":[{"word":"impulsive","structure":"impulse + -ive (tendency) → tending to follow a sudden push","meaning":"acting without planning","meaningCN":"冲动的"},{"word":"impulsively","structure":"impulsive + -ly (adverb) → in the manner of a sudden push","meaning":"without thinking first","meaningCN":"冲动地"},{"word":"impulsiveness","structure":"impulsive + -ness (quality) → the tendency to act on urges","meaning":"a readiness to act suddenly","meaningCN":"冲动性"},{"word":"impel","structure":"in- into + pellere drive → to drive someone into action","meaning":"to urge forward","meaningCN":"推动；驱使"},{"word":"compel","structure":"com- strongly + pellere drive → to drive with force","meaning":"to force","meaningCN":"强迫"}]}},{"word":"impulsive","ipa_uk":"/ɪmˈpʌlsɪv/","ipa_us":"/ɪmˈpʌlsɪv/","definition_zh":"冲动的；凭一时冲动行事的；未经思索的；[物理] 由冲量引起的","definition_en":"acting or done suddenly on a urge, without planning or thinking first","core_image":"话还没在脑子里排好队，嘴已经先张开了","scene":"会议桌上，那句反驳还没想清楚就说了出口，Her impulsive reply ended the discussion before it began.","sceneCN":"这里 impulsive 指「凭一时冲动、不加思索就行动的」（第 1 个义项：易凭冲动行事）；句意为她那句脱口而出的反驳让讨论还没开始就结束了。图中可辨识物件：会议桌、半举的手、翻开的笔记本、冷掉的咖啡。","pos":[{"tag":"adj.","zh":"冲动的；不经思索的；由冲量引起的"}],"collocations":[{"phrase":"impulsive behaviour","zh":"冲动行为"},{"phrase":"impulsive decision","zh":"冲动的决定"},{"phrase":"impulsive buy","zh":"冲动购买的东西"},{"phrase":"impulsive reaction","zh":"冲动反应"},{"phrase":"impulsive person","zh":"易冲动的人"},{"phrase":"impulsive spending","zh":"冲动消费"}],"forms":[{"label":"原级","form":"impulsive"},{"label":"比较级","form":"more impulsive"},{"label":"最高级","form":"most impulsive"},{"label":"副词（冲动地）","form":"impulsively"},{"label":"名词（冲动性）","form":"impulsiveness"},{"label":"名词（冲动）","form":"impulse"},{"label":"名词（冲动性，心理学用语）","form":"impulsivity"}],"derivatives":[{"word":"impulsively","pos":"adv.","zh":"冲动地"},{"word":"impulsiveness","pos":"n.","zh":"冲动性"},{"word":"impulse","pos":"n.","zh":"冲动；冲量"},{"word":"impulsivity","pos":"n.","zh":"冲动性（心理学用语）"}],"senses":[{"no":"01","title":"Acting on a sudden urge","titleCN":"凭一时冲动行事","definition":"given to acting suddenly on a strong urge rather than after thought","definitionCN":"惯于凭强烈欲望突然行动，而不是先思考","example":"He is impulsive and buys things he never uses.","exampleCN":"他很冲动，常买些从不用到的东西。","why":"The adjective attaches the push of impulse to a person, so it describes a tendency rather than one act.","whyCN":"这个形容词把 impulse 的推力附着在人身上，因此描述的是一种倾向，而不是一次行为。"},{"no":"02","title":"Done without planning","titleCN":"未经计划就做的","definition":"of an action, done suddenly without prior planning","definitionCN":"指行为突然发生，事先没有计划","example":"Their move abroad was impulsive.","exampleCN":"他们搬去国外是一时冲动。","why":"The same push can be attached to the act, and then the word judges the deed rather than the person.","whyCN":"同一股推力也可以附着在行为上，于是这个词评价的是行为，而不是人。"},{"no":"03","title":"Blurted out in speech","titleCN":"脱口而出的话语","definition":"of words, said suddenly before they have been considered","definitionCN":"指话语未经考虑就突然说出","example":"It was an impulsive remark, and she apologized at once.","exampleCN":"那是一句脱口而出的话，她马上道了歉。","why":"Speech can be pushed out as quickly as a hand can reach, so the adjective covers words too.","whyCN":"话可以像手伸出去一样被推出来，因此这个形容词也涵盖言语。"},{"no":"04","title":"Produced by a sudden force in physics","titleCN":"物理上由冲量产生的","definition":"in physics and engineering, caused by a short applied force","definitionCN":"在物理与工程中，由短时施加的力造成","example":"The impulsive load bent the beam for a moment.","exampleCN":"冲击载荷让横梁短暂弯曲。","why":"Technicians keep the original physical sense: a force that arrives in a short burst.","whyCN":"技术人员保留了最初的物理义：以短促爆发形式到来的力。"},{"no":"05","title":"A trait studied in psychology","titleCN":"心理学研究的冲动特质","definition":"in psychology, describing behaviour that responds to urges with little restraint","definitionCN":"在心理学中，描述对欲望几乎不加克制就作出反应的行为","example":"The scale measures impulsive tendencies in children.","exampleCN":"这个量表测量儿童的冲动倾向。","why":"A tendency can be measured, and the adjective becomes a clinical description.","whyCN":"倾向可以被测量，这个形容词于是成了临床描述。"},{"no":"06","title":"Bought without planning","titleCN":"未经计划就买下的","definition":"of a purchase, made on a sudden wish rather than a plan","definitionCN":"指购买出于突然的欲望，而不是出于计划","example":"The impulsive purchase sat unused in the cupboard.","exampleCN":"那件冲动买下的东西一直放在柜子里没用。","why":"Commerce applies the word to the object, and the deed becomes a label on the goods.","whyCN":"商业把这个词用到物件上，行为于是变成了贴在货物上的标签。"},{"no":"07","title":"Energetic and ungoverned in style","titleCN":"风格上奔放不羁的","definition":"of a style or performance, energetic and ungoverned","definitionCN":"指风格或表演充满劲头、不受拘束","example":"The band played with an impulsive energy.","exampleCN":"乐队演奏出一股不受拘束的劲头。","why":"Art values the push for its freshness, so the same word can become praise.","whyCN":"艺术看重这种推力带来的新鲜感，因此同一个词也能变成称赞。"},{"no":"08","title":"Pushed rather than weighed","titleCN":"被推着走而非称量过的","definition":"the abstract quality of being driven by a push rather than by deliberation","definitionCN":"被推力带着走、而不是经过权衡的抽象性质","example":"The whole decision felt impulsive rather than reasoned.","exampleCN":"整个决定感觉是被推着作出的，而不是推理出来的。","why":"The core contrast is between a push and a scale, and this sense states the contrast directly.","whyCN":"核心对照就是「推力」与「天平」之间，这个义项直接把这层对照说出来。"}],"etymology":{"intro":{"en":"Impulsive is formed from impulse plus -ive, with a parallel Medieval Latin impulsivus. Dates are approximate.","cn":"impulsive 由 impulse 加 -ive 构成，中世纪拉丁语中有并行的 impulsivus。年代均为约数。"},"items":[{"era":"LATIN IMPULSUS","en":"The base noun impulsus named a push or shock, from impellere, to drive into.","cn":"基础名词 impulsus 指推击或冲击，来自表示「推入」的 impellere。"},{"era":"MEDIEVAL LATIN","en":"Scholastic and medical Latin used impulsivus for forces or movements that arrive as a sudden push.","cn":"经院与医学拉丁语用 impulsivus 指以突然推力到来的力或运动。"},{"era":"ENGLISH SEVENTEENTH CENTURY","en":"English adopted impulsive in the seventeenth century, first for physical pushes and soon for a person's sudden acts.","cn":"英语在十七世纪引入 impulsive，先指物理上的推动，很快又指人的突然行为。"},{"era":"PSYCHOLOGICAL USE","en":"The nineteenth and twentieth centuries made the word a standard description of behaviour that follows urges without restraint.","cn":"十九与二十世纪使这个词成为描述「不加克制就跟随欲望」的行为的标准用语。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation is not fixed, and the shift from physical pushes to human tendency is dated differently across reference works.","cn":"来源不确定：英语最早书证年代无定论；从物理推力转向人的倾向这一变化，各家参考资料给出的年代也不一致。"}]},"similar":{"note":{"en":"The first group shares the Latin verb pellere but differs in prefix; the second holds adjectives for hasty action. One look-alike comes from a different root.","cn":"第一组共享拉丁动词 pellere，只是前缀不同；第二组是表示仓促行动的形容词。有一个形似词来自不同词根。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impulse","ipa":"/ˈɪmpʌls/","tag":"same root, noun","definition":"The noun for the push itself; impulsive describes a person or act moved by it.","definitionCN":"命名推力本身的名词；impulsive 描述被它推动的人或行为。"},{"word":"impulsiveness","ipa":"/ɪmˈpʌlsɪvnəs/","tag":"same root, noun of quality","definition":"The tendency to act on impulses; impulsive is the adjective that names the same tendency.","definitionCN":"凭冲动行事的倾向；impulsive 是命名同一倾向的形容词。"},{"word":"compulsive","ipa":"/kəmˈpʌlsɪv/","tag":"same root, different prefix","definition":"Com- plus pellere: driven by an inner compulsion that feels hard to resist; it is not the same as acting on a passing urge.","definitionCN":"com- 加 pellere：被一种难以抗拒的内在强迫驱使；与凭一时冲动行事并不相同。"},{"word":"impetuous","ipa":"/ɪmˈpetjuəs/","tag":"different root","definition":"From Latin impetere, built on petere meaning to seek or attack, not pellere; it means rash and forceful.","definitionCN":"来自拉丁语 impetere，词根是 petere「寻求、攻击」而非 pellere；意为鲁莽而猛烈的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"spontaneous","ipa":"/spɒnˈteɪniəs/","tag":"unplanned but not reckless","definition":"Arising from one's own impulse without outside force; it can be warm and welcome, while impulsive often carries a warning.","definitionCN":"出于自身意愿而非外力；它可以是温暖可人的，而 impulsive 常带警示意味。"},{"word":"rash","ipa":"/ræʃ/","tag":"clearly unwise","definition":"Acting too quickly and without seeing the danger; it is more clearly critical than impulsive.","definitionCN":"行动过快且没看到危险；比 impulsive 更明显地带有批评意味。"},{"word":"hasty","ipa":"/ˈheɪsti/","tag":"too fast","definition":"Done too quickly, often with poor results; it stresses speed, while impulsive stresses the inner push.","definitionCN":"做得太快，常带来糟糕结果；它强调速度，impulsive 强调内在的推力。"},{"word":"impetuous","ipa":"/ɪmˈpetjuəs/","tag":"forceful rush","definition":"Rushed forward with force and little thought; it adds violence of movement that impulsive need not have.","definitionCN":"带着猛劲冲出去、很少思考；它多了动作上的猛烈，而 impulsive 未必有。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real noun base, the real adjective ending, the real family and the phrases the word keeps.","cn":"正常联想：真实的名词基础、真实的形容词词尾、真实的同族词，以及这个词实际常用的搭配。"},"normal":[{"en":"impulse plus -ive: the ending turns a push into a tendency of a person or act.","cn":"impulse 加 -ive：这个词尾把一推之力变成人或行为的一种倾向。"},{"en":"The family runs impulse, impulsively, impulsiveness and impulsivity.","cn":"同族词包括 impulse（冲动）、impulsively（冲动地）、impulsiveness（冲动性）、impulsivity（冲动性，心理学用语）。"},{"en":"Fixed phrases mark the field: impulsive behaviour, impulsive decision, impulsive buy, impulsive spending.","cn":"固定搭配标出领域：冲动行为、冲动的决定、冲动买下的东西、冲动消费。"},{"en":"Compulsive shares the root but adds a prefix of forcing: it is pressure that will not let go, not a passing urge.","cn":"compulsive 共享词根，但加上了表「强迫」的前缀：那是甩不掉的压迫，不是一时的欲望。"},{"en":"Impetuous looks like impulsive but comes from seeking, not driving, so the roots differ.","cn":"impetuous 看似与 impulsive 同族，却来自「寻求」而不是「驱动」，词根并不相同。"}],"abstract":[{"en":"Picture a mouth opening before the sentence has been arranged.","cn":"想象句子还没排好，嘴已经先张开。"},{"en":"Picture a shopping basket filled before the list is read.","cn":"想象购物清单还没看，篮子已经装满了。"},{"en":"Picture a hand pushed forward by a spring it cannot see.","cn":"想象一只手被一根看不见的弹簧推向前。"}]},"examples":[{"en":"He tends to make impulsive decisions at the end of a long day.","cn":"他在漫长的一天结束时容易作出冲动的决定。"},{"en":"The letter was an impulsive response, written in anger.","cn":"这封信是气头上的冲动回应。"},{"en":"Engineers test how the bridge bears an impulsive load.","cn":"工程师测试这座桥如何承受冲击载荷。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「一木跑媳妇」——没想清楚就先冲出去 → impulsive 冲动的","word":"impulsive"},"root":"由 impulse 加形容词词尾 -ive 构成；impulse 来自拉丁 impulsus，后者出自 impellere = in-「进入」+ pellere「推、驱动」。","sensesIntro":{"en":"Eight senses follow one push attached to a person: a tendency, an unplanned act, a blurted word, a sudden physical load, a measured trait, a purchase, an ungoverned style and the abstract contrast with deliberation.","cn":"八个义项沿同一股附着在人身上的推力展开：一种倾向、一次无计划的行为、一句脱口而出的话、一次突然的物理载荷、一种被测量的特质、一次购买、一种不受拘束的风格，以及与权衡相对的抽象性质。"},"semanticMap":{"core":{"en":"CORE IMAGE: a mouth that opens before the sentence inside it has been arranged.","cn":"核心意象：句子还没在脑中排好，嘴已经先张开了。"},"chain":["PUSH ARRIVES","PAUSE SKIPPED","ACT FOLLOWS","WORDS FOLLOW","MEASURE DROPPED","PATTERN SET"],"branches":[{"senses":"01 · 05","en":"PERSON AND TRAIT: a single sudden act hardens into a measurable tendency.","cn":"人与特质：一次突然的行为会凝固成可测量的倾向。"},{"senses":"02 · 06","en":"UNPLANNED DEED: the same lack of planning covers a journey and a purchase.","cn":"无计划之举：同一种缺乏计划，既涵盖一趟远行，也涵盖一次购买。"},{"senses":"03","en":"SPEECH: words are pushed out as directly as a hand reaches.","cn":"言语：话语像手伸出去一样直接被推出。"},{"senses":"04","en":"PHYSICAL LOAD: engineering keeps the original short burst of force.","cn":"物理载荷：工程学保留了最初那股短促的力。"},{"senses":"07 · 08","en":"STYLE AND CONTRAST: art may praise the push, while reasoning sets it against the scale.","cn":"风格与对照：艺术可能称赞这股推力，推理则把它与天平对立起来。"}]},"affixes":{"intro":{"en":"Impulsive is a noun base plus an adjective ending, and the base itself goes back to a prefix and a verb of driving.","cn":"impulsive 是一个名词基础加形容词词尾，而这个基础本身可追到前缀与表示「驱动」的动词。"},"latinIntro":{"en":"Latin impellere gives impulse and impel, and the ending -ive, from Latin -ivus, turns the noun into a tendency; the same stock also gives compulsive and repulsive.","cn":"拉丁语 impellere 衍生 impulse 与 impel，来自拉丁语 -ivus 的词尾 -ive 把名词变成倾向；同一词干还衍生 compulsive 与 repulsive。"},"items":[{"word":"in-","structure":"in- (Latin prefix, into)","meaning":"into","meaningCN":"进入","example":"The prefix also appears in inject.","exampleCN":"这个前缀也出现在 inject（注入）里。"},{"word":"pellere","structure":"pellere (Latin verb, to drive)","meaning":"to drive; to push","meaningCN":"驱动；推","example":"Its stem survives in propel.","exampleCN":"它的词干留在 propel（推进）里。"},{"word":"impulse","structure":"in- + pellere (noun)","meaning":"a push; a sudden urge","meaningCN":"一推；突然的冲动","example":"The impulse came without warning.","exampleCN":"这股冲动来得毫无预兆。"},{"word":"impulsive","structure":"impulse + -ive (tending adjective)","meaning":"moved by a sudden push","meaningCN":"被突然的推力带动；冲动的","example":"He is impulsive by nature.","exampleCN":"他天生冲动。"},{"word":"impulsively","structure":"impulsive + -ly (adverb ending)","meaning":"in a sudden, unplanned way","meaningCN":"以突然、无计划的方式","example":"She agreed impulsively.","exampleCN":"她冲口就答应了。"},{"word":"impulsiveness","structure":"impulsive + -ness (quality)","meaning":"the tendency to act on urges","meaningCN":"凭冲动行事的倾向","example":"Impulsiveness ran in the family.","exampleCN":"这种冲动倾向在这个家族里代代都有。"},{"word":"compulsive","structure":"com- (strongly) + pellere + -ive","meaning":"driven by a force that will not release","meaningCN":"被难以摆脱的力量驱使的","example":"He had a compulsive need to check the lock.","exampleCN":"他有一种难以摆脱的检查门锁的需要。"},{"word":"repulsive","structure":"re- (back) + pellere + -ive","meaning":"driving one away; repelling","meaningCN":"把人推开的；令人反感的","example":"The smell was repulsive.","exampleCN":"那股气味令人反感。"}],"latinEntries":[{"word":"pellere","structure":"pellere, pepuli, pulsum (verb, third conjugation)","meaning":"to drive, push","meaningCN":"驱动；推"},{"word":"impellere","structure":"impellere, impuli, impulsum (verb, third conjugation)","meaning":"to drive into, impel","meaningCN":"推入；驱使"},{"word":"impulsus","structure":"impulsus, impulsus (m., fourth declension)","meaning":"a push, a shock","meaningCN":"推击；冲击"},{"word":"-ivus","structure":"-ivus (Latin adjective suffix, tending to)","meaning":"tending to; having the nature of","meaningCN":"倾向于；具有……性质的"}],"derivatives":[{"word":"impulsively","structure":"impulsive + -ly (adverb) → in the manner of a sudden push","meaning":"without thinking first","meaningCN":"冲动地"},{"word":"impulsiveness","structure":"impulsive + -ness (quality) → the state of following urges","meaning":"a readiness to act suddenly","meaningCN":"冲动性"},{"word":"impulsivity","structure":"impulsive + -ity (abstract noun) → the measurable trait of acting on urges","meaning":"the clinical trait","meaningCN":"冲动性（心理学用语）"},{"word":"compulsive","structure":"com- strongly + pellere drive + -ive → driven by an irresistible force","meaning":"forced from within","meaningCN":"强迫性的"},{"word":"repulsive","structure":"re- back + pellere drive + -ive → driving the observer away","meaning":"causing strong dislike","meaningCN":"令人反感的"}]}},{"word":"impulsiveness","ipa_uk":"/ɪmˈpʌlsɪvnəs/","ipa_us":"/ɪmˈpʌlsɪvnəs/","definition_zh":"冲动性；易冲动的倾向；不加思索就行动的特质","definition_en":"the tendency to act suddenly on urges without stopping to think","core_image":"脚下的刹车片磨得很薄，车还是滑出去半米才停住","scene":"停车场的出口，一位司机差点撞上柱子，The report blamed impulsiveness rather than poor brakes for the crash.","sceneCN":"这里 impulsiveness 指「不加思索就行动的倾向」（第 1 个义项：易凭冲动行动的倾向）；句意为报告把这次碰撞归因于冲动，而不是刹车不良。图中可辨识物件：停车场、柱子、刹车痕、事故报告。","pos":[{"tag":"n.","zh":"冲动性；易冲动的倾向"}],"collocations":[{"phrase":"sheer impulsiveness","zh":"纯粹的冲动"},{"phrase":"an act of impulsiveness","zh":"一次冲动的行为"},{"phrase":"a trait of impulsiveness","zh":"冲动性的特质"},{"phrase":"impulsiveness score","zh":"冲动性得分"},{"phrase":"youthful impulsiveness","zh":"年轻人的冲动"},{"phrase":"restrain one's impulsiveness","zh":"克制自己的冲动"}],"forms":[{"label":"原形（不可数名词）","form":"impulsiveness"},{"label":"复数（少见，指多次冲动表现）","form":"impulsivenesses"},{"label":"形容词（冲动的）","form":"impulsive"},{"label":"副词（冲动地）","form":"impulsively"},{"label":"名词（冲动）","form":"impulse"},{"label":"名词（冲动性，心理学用语）","form":"impulsivity"}],"derivatives":[{"word":"impulsive","pos":"adj.","zh":"冲动的"},{"word":"impulsively","pos":"adv.","zh":"冲动地"},{"word":"impulse","pos":"n.","zh":"冲动；冲量"},{"word":"impulsivity","pos":"n.","zh":"冲动性（心理学用语）"}],"senses":[{"no":"01","title":"The tendency to act on a sudden urge","titleCN":"凭一时冲动行事的倾向","definition":"the tendency to act suddenly on a strong urge rather than after thought","definitionCN":"倾向于凭强烈欲望突然行动，而不是先思考","example":"Her impulsiveness got her into debt.","exampleCN":"她的冲动让她背上了债。","why":"The ending -ness turns the adjective into a standing tendency, so the word names a pattern rather than one act.","whyCN":"词尾 -ness 把形容词变成一种持续存在的倾向，因此这个词命名的是模式，而不是一次行为。"},{"no":"02","title":"The quality of action done without a pause","titleCN":"行动缺少停顿的性质","definition":"the quality of an action that happens before reflection has time to occur","definitionCN":"行为在反思还来不及发生之前就已经做出的性质","example":"The impulsiveness of the decision surprised everyone.","exampleCN":"这个决定之冲动让所有人都吃惊。","why":"A quality can belong to an act as well as to a person, and here it names the missing pause.","whyCN":"一种性质既可以属于人，也可以属于行为，这里它命名的是那个缺席的停顿。"},{"no":"03","title":"A trait measured in psychology","titleCN":"心理学中可测量的特质","definition":"in psychology, a measurable trait of responding to urges with little delay","definitionCN":"心理学中，对欲望几乎不延迟就作出反应的可测量特质","example":"The study scored impulsiveness on a ten-point scale.","exampleCN":"这项研究用十分制给冲动性打分。","why":"Once a tendency can be scored, it becomes a variable rather than a moral failing.","whyCN":"一种倾向一旦可以被评分，就成了变量，而不是道德缺陷。"},{"no":"04","title":"A clinical sign of weak regulation","titleCN":"调节能力薄弱的临床征象","definition":"in clinical use, a sign that a person has difficulty holding back urges","definitionCN":"在临床上，指一个人难以克制欲望的征象","example":"The assessment noted impulsiveness alongside poor sleep.","exampleCN":"评估在记录冲动性的同时，也记录了睡眠不佳。","why":"Medicine reads the trait as a symptom, so the same word becomes part of a diagnosis.","whyCN":"医学把这种特质读成症状，同一个词于是成了诊断的一部分。"},{"no":"05","title":"A tendency toward unplanned buying","titleCN":"未经计划就消费的倾向","definition":"in commerce, the tendency to buy on a sudden wish rather than a plan","definitionCN":"在商业上，指凭突然的欲望而非计划购物的倾向","example":"Discounts are designed to exploit impulsiveness.","exampleCN":"折扣就是为了利用冲动而设计的。","why":"Commerce gives the trait a market value: the pause that is missing is the pause before payment.","whyCN":"商业给这种特质标上了市场价值：所缺的那个停顿，正是付款之前的停顿。"},{"no":"06","title":"The rashness often ascribed to youth","titleCN":"常被归给年轻人的莽撞","definition":"the rashness that is often attributed to young people and inexperience","definitionCN":"常被归因于年轻与缺乏经验的莽撞","example":"They forgave his youthful impulsiveness.","exampleCN":"他们原谅了他年轻人的冲动。","why":"Age is used as an excuse for the trait, so the word acquires a social label.","whyCN":"年龄被拿来为这种特质开脱，于是这个词又获得了一个社会标签。"},{"no":"07","title":"Spontaneity visible in a style","titleCN":"风格中可见的自发劲头","definition":"the quality of a style that looks spontaneous and unplanned","definitionCN":"某种风格显得自发、未经安排的性质","example":"The impulsiveness of the brushwork gives the painting life.","exampleCN":"笔触的冲动感让这幅画有了生气。","why":"In art the missing pause becomes a virtue, because freshness is valued over finish.","whyCN":"在艺术里，缺席的停顿反而成了优点，因为新鲜感比精修更受看重。"},{"no":"08","title":"The push outrunning the scale","titleCN":"推力跑在天平之前","definition":"the abstract condition in which a drive acts before any weighing can take place","definitionCN":"驱动力在任何权衡发生之前就已行动起来的抽象状态","example":"At bottom, impulsiveness is a race the scale always loses.","exampleCN":"说到底，冲动性是一场天平总是输掉的赛跑。","why":"The whole family rests on a contrast between a push and a balance, and this sense names the race itself.","whyCN":"整个词族都建立在「推力」与「天平」的对照上，这个义项命名的正是那场赛跑。"}],"etymology":{"intro":{"en":"Impulsiveness is impulsive plus the native noun ending -ness, recorded in English usage from the eighteenth century onward. Dates are approximate.","cn":"impulsiveness 由 impulsive 加本族语名词词尾 -ness 构成，英语用法自十八世纪起有记录。年代均为约数。"},"items":[{"era":"LATIN IMPULSUS","en":"The base noun impulsus named a push or shock, from impellere, to drive into.","cn":"基础名词 impulsus 指推击或冲击，来自表示「推入」的 impellere。"},{"era":"ENGLISH IMPULSIVE","en":"The adjective impulsive entered English in the seventeenth century, first for physical pushes and then for sudden human acts.","cn":"形容词 impulsive 在十七世纪进入英语，先指物理上的推动，后指人的突然行为。"},{"era":"NATIVE SUFFIX","en":"The ending -ness turns an adjective into a noun of quality, and it has been productive in English since Old English.","cn":"词尾 -ness 把形容词变成表示性质的名词，自上古英语以来一直是能产后缀。"},{"era":"MODERN USE","en":"The noun became common in moral writing and later in psychology, where it names a measurable trait.","cn":"这个名词先在道德论述中常见，后来进入心理学，用来命名一种可测量的特质。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: reference works give different first dates for the noun, and the exact route from moral comment to clinical use is not documented in one line.","cn":"来源不确定：各家参考资料给这个名词的首见年代不一；从道德评语走向临床用语的具体路径，也没有单一文献记录。"}]},"similar":{"note":{"en":"The first group is built on the same impulse stock but differs in form or prefix; the second holds nouns of haste and self-drive.","cn":"第一组建立在同一个 impulse 词干上，只是形态或前缀不同；第二组是表示仓促与自发的名词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"impulsive","ipa":"/ɪmˈpʌlsɪv/","tag":"same root, adjective","definition":"The adjective describing a person or act moved by a sudden push; impulsiveness is the noun for that quality.","definitionCN":"描述被突然推力带动的人或行为的形容词；impulsiveness 是表示该性质的名词。"},{"word":"impulse","ipa":"/ˈɪmpʌls/","tag":"same root, noun","definition":"The push itself; impulsiveness names the standing tendency to follow such pushes.","definitionCN":"推力本身；impulsiveness 命名跟随这种推力的持续倾向。"},{"word":"impulsivity","ipa":"/ˌɪmpʌlˈsɪvəti/","tag":"same root, technical","definition":"The clinical and psychological term for the trait; it is close to impulsiveness but belongs to professional registers.","definitionCN":"指该特质的临床与心理学术语；与 impulsiveness 相近，但属于专业语域。"},{"word":"compulsiveness","ipa":"/kəmˈpʌlsɪvnəs/","tag":"same root, different prefix","definition":"The quality of being driven by a compulsion that feels unavoidable; it is stronger than a passing urge.","definitionCN":"被一种似乎无法避免的强迫驱使的性质；比一时的欲望更强。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rashness","ipa":"/ˈræʃnəs/","tag":"unwise speed","definition":"The quality of acting too quickly and without seeing the risk; it is more clearly critical than impulsiveness.","definitionCN":"行动过快且没看到风险的性质；比 impulsiveness 更明显带批评意味。"},{"word":"haste","ipa":"/heɪst/","tag":"speed itself","definition":"The quality of doing something too quickly; it need not involve an inner urge at all.","definitionCN":"做事过快的性质；它完全可以不涉及内在欲望。"},{"word":"spontaneity","ipa":"/spɒnˌteɪˈniːəti/","tag":"welcome freedom","definition":"The quality of arising freely from oneself; it is usually praised, while impulsiveness is often warned against.","definitionCN":"自由地出于自身的性质；它通常受称赞，而 impulsiveness 常被警告。"},{"word":"impetuosity","ipa":"/ˌɪmpəˈtjuːəsəti/","tag":"forceful rush","definition":"Rushed forcefulness of movement or feeling; it comes from a different root and adds violence that impulsiveness need not have.","definitionCN":"动作或情绪上的猛烈冲劲；它来自不同词根，多了 impulsiveness 未必有的猛烈。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real adjective base, the native noun ending, the real family and the phrases the noun keeps.","cn":"正常联想：真实的形容词基础、本族语名词词尾、真实的同族词，以及这个名词实际常用的搭配。"},"normal":[{"en":"impulsive plus -ness: the ending turns a way of acting into a standing trait.","cn":"impulsive 加 -ness：这个词尾把一种行事方式变成一种持续的特质。"},{"en":"The family runs impulse, impulsive, impulsively, impulsiveness and impulsivity.","cn":"同族词包括 impulse（冲动）、impulsive（冲动的）、impulsively（冲动地）、impulsiveness（冲动性）、impulsivity（冲动性，心理学用语）。"},{"en":"Fixed phrases mark the field: sheer impulsiveness, a trait of impulsiveness, impulsiveness score.","cn":"固定搭配标出领域：纯粹的冲动、冲动性的特质、冲动性得分。"},{"en":"Psychology prefers the shorter technical doublet impulsivity, while everyday speech uses impulsiveness.","cn":"心理学更爱用较短的技术对偶词 impulsivity，日常口语则用 impulsiveness。"},{"en":"The word names the missing pause, so any phrase about stopping to think is a fair test of its meaning.","cn":"这个词命名的是那个缺席的停顿，因此任何关于「停下来想一想」的说法都能检验它的含义。"}],"abstract":[{"en":"Picture worn brake pads that let the car slide past the line.","cn":"想象磨薄的刹车片，让车滑过了停止线。"},{"en":"Picture a hand already in the jar before the question is asked.","cn":"想象问题还没问出口，手已经伸进罐子里。"},{"en":"Picture a runner who starts on the gun and never checks the lane.","cn":"想象一名听见枪响就冲出去、从不看道的跑者。"}]},"examples":[{"en":"His impulsiveness made the apology necessary.","cn":"他的冲动让那句道歉成了必要。"},{"en":"The questionnaire measures impulsiveness in adolescents.","cn":"这份问卷测量青少年的冲动性。"},{"en":"Age had not cured her impulsiveness.","cn":"年纪并没有治好她的冲动。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「一木跑媳妇，拿死」——冲出去就收不住的那股劲 → impulsiveness 冲动性","word":"impulsiveness"},"root":"由 impulsive 加本族语名词词尾 -ness 构成；impulsive 出自 impulse，后者来自拉丁 impulsus，再追溯到 impellere = in-「进入」+ pellere「推、驱动」。","sensesIntro":{"en":"Eight senses follow one missing pause: a tendency, a quality of acts, a measured trait, a clinical sign, a shopping habit, the rashness of youth, a praised spontaneity and finally a race the balance always loses.","cn":"八个义项沿同一个缺席的停顿展开：一种倾向、行为的一种性质、被测量的特质、临床征象、购物习惯、年轻人的莽撞、被称赞的自发，最后是一场天平总是输掉的赛跑。"},"semanticMap":{"core":{"en":"CORE IMAGE: brake pads worn thin, and the car still slides half a metre past the line.","cn":"核心意象：刹车片磨得很薄，车还是滑出去半米才停住。"},"chain":["URGE SURFACES","PAUSE ABSENT","ACT LEAPS","PATTERN FORMS","TRAIT MEASURED","STYLE SHOWS"],"branches":[{"senses":"01 · 02","en":"URGE AND ACT: a push arrives and the deed follows before reflection.","cn":"欲望与行为：推力一到，行为就在反思之前跟着发生。"},{"senses":"03 · 04","en":"TRAIT AND SIGN: the same tendency becomes a score and then a symptom.","cn":"特质与征象：同一种倾向先变成分数，再变成症状。"},{"senses":"05 · 06","en":"MARKET AND YOUTH: the missing pause is sold to shoppers and excused in the young.","cn":"市场与年轻：缺席的停顿被卖给消费者，也被拿来为年轻人开脱。"},{"senses":"07","en":"ART: in a style the missing pause can turn into freshness.","cn":"艺术：在风格里，缺席的停顿可以变成新鲜感。"},{"senses":"08","en":"THE RACE: drive and deliberation compete, and drive starts first.","cn":"赛跑：驱力与权衡在比，而驱力先起跑。"}]},"affixes":{"intro":{"en":"Impulsiveness is a chain of three pieces: a Latin verb of driving, an adjective ending and a native noun ending.","cn":"impulsiveness 是三段接起来的：表示驱动的拉丁动词、形容词词尾，以及本族语名词词尾。"},"latinIntro":{"en":"Latin pellere gives impulse and impel, the ending -ive turns impulse into a tendency, and the native -ness turns that tendency into a noun.","cn":"拉丁语 pellere 衍生 impulse 与 impel，词尾 -ive 把 impulse 变成倾向，本族语词尾 -ness 再把这种倾向变成名词。"},"items":[{"word":"pellere","structure":"pellere (Latin verb, to drive)","meaning":"to drive; to push","meaningCN":"驱动；推","example":"Its stem survives in propel and repel.","exampleCN":"它的词干留在 propel（推进）与 repel（击退）里。"},{"word":"impulse","structure":"in- (into) + pellere (drive), noun form","meaning":"a push; a sudden urge","meaningCN":"一推；突然的冲动","example":"The impulse came without warning.","exampleCN":"这股冲动来得毫无预兆。"},{"word":"-ive","structure":"-ive (Latin adjective ending, tending to)","meaning":"tending to; having the nature of","meaningCN":"倾向于；具有……性质的","example":"The same ending builds compulsive and repulsive.","exampleCN":"同一词尾也构成 compulsive（强迫性的）与 repulsive（令人反感的）。"},{"word":"impulsive","structure":"impulse + -ive","meaning":"moved by a sudden push","meaningCN":"被突然推力带动的","example":"He is impulsive by nature.","exampleCN":"他天生冲动。"},{"word":"-ness","structure":"-ness (native noun ending, quality)","meaning":"the quality of being so","meaningCN":"处于某种状态的性质","example":"The same ending builds rashness and boldness.","exampleCN":"同一词尾也构成 rashness（鲁莽）与 boldness（大胆）。"},{"word":"impulsiveness","structure":"impulsive + -ness","meaning":"the tendency to act on urges","meaningCN":"凭冲动行事的倾向","example":"Impulsiveness can be measured.","exampleCN":"冲动性可以被测量。"},{"word":"impulsively","structure":"impulsive + -ly (adverb ending)","meaning":"in a sudden, unplanned way","meaningCN":"以突然、无计划的方式","example":"She agreed impulsively.","exampleCN":"她冲口就答应了。"},{"word":"impulsivity","structure":"impulsive + -ity (abstract noun)","meaning":"the trait as a technical variable","meaningCN":"作为技术变量的冲动性","example":"Impulsivity is studied in clinics.","exampleCN":"冲动性在临床中被研究。"}],"latinEntries":[{"word":"pellere","structure":"pellere, pepuli, pulsum (verb, third conjugation)","meaning":"to drive, push","meaningCN":"驱动；推"},{"word":"impellere","structure":"impellere, impuli, impulsum (verb, third conjugation)","meaning":"to drive into, impel","meaningCN":"推入；驱使"},{"word":"impulsus","structure":"impulsus, impulsus (m., fourth declension)","meaning":"a push, a shock","meaningCN":"推击；冲击"},{"word":"-ivus","structure":"-ivus (Latin adjective suffix, tending to)","meaning":"tending to","meaningCN":"倾向于……的"}],"derivatives":[{"word":"impulsively","structure":"impulsive + -ly (adverb) → in the manner of a sudden push","meaning":"without thinking first","meaningCN":"冲动地"},{"word":"impulsivity","structure":"impulsive + -ity (abstract noun) → the measurable trait","meaning":"the clinical variable","meaningCN":"冲动性（心理学用语）"},{"word":"impulse","structure":"in- into + pellere drive → the push itself","meaning":"a sudden urge","meaningCN":"冲动"},{"word":"compulsiveness","structure":"com- strongly + pellere drive + -ive + -ness → the quality of being driven without relief","meaning":"an unrelieved inner force","meaningCN":"强迫性"}]}},{"word":"self-control","ipa_uk":"/ˌself kənˈtrəʊl/","ipa_us":"/ˌself kənˈtroʊl/","definition_zh":"自我控制；自制力；镇定；[工程] 自控（系统对自身的控制）","definition_en":"the ability to hold back one's impulses and keep one's behaviour in order","core_image":"一个人左手握住右手手腕，把已经伸向糖罐的手拉回来","scene":"甜品台前，孩子的手伸出去又缩回来，Her self-control kept her from taking a third cake.","sceneCN":"这里 self-control 指「克制自己欲望的能力」（第 1 个义项：抑制自身冲动的能力）；句意为她的自制力让她没有拿第三块蛋糕。图中可辨识物件：甜品台、蛋糕、缩回的手、餐巾。","pos":[{"tag":"n.","zh":"自我控制；自制力；镇定；自控（工程用语）"}],"collocations":[{"phrase":"exercise self-control","zh":"运用自制力"},{"phrase":"lose self-control","zh":"失去自制"},{"phrase":"lack self-control","zh":"缺乏自制力"},{"phrase":"a model of self-control","zh":"自制力的典范"},{"phrase":"self-control training","zh":"自制力训练"},{"phrase":"maintain self-control","zh":"保持自制"}],"forms":[{"label":"原形（不可数名词）","form":"self-control"},{"label":"复数（少见，指多次自控表现）","form":"self-controls"},{"label":"形容词（有自制力的）","form":"self-controlled"},{"label":"形容词（自我控制的）","form":"self-controlling"},{"label":"动词（控制）","form":"control"},{"label":"名词（控制器）","form":"controller"}],"derivatives":[{"word":"self-controlled","pos":"adj.","zh":"有自制力的"},{"word":"self-controlling","pos":"adj.","zh":"自我控制的"},{"word":"control","pos":"n./v.","zh":"控制；管理"},{"word":"controller","pos":"n.","zh":"控制器；管理者"}],"senses":[{"no":"01","title":"The ability to hold back one's impulses","titleCN":"克制自身冲动的能力","definition":"the ability to stop oneself from acting on a strong urge","definitionCN":"阻止自己凭强烈欲望行动的能力","example":"Her self-control kept her from taking a third cake.","exampleCN":"她的自制力让她没有拿第三块蛋糕。","why":"Self names the same person as both the one who wants and the one who holds back, so the control runs in a loop.","whyCN":"self 让同一个人既是想要的人，也是拉住的人，因此这种控制在一个人身上绕成环。"},{"no":"02","title":"Composure under provocation","titleCN":"受刺激时保持镇定","definition":"the ability to stay calm when someone tries to provoke or upset you","definitionCN":"在别人试图激怒或扰乱你时保持平静的能力","example":"He answered the insult with self-control.","exampleCN":"他以镇定回应那句侮辱。","why":"Holding back an impulse is most visible when the impulse is anger, and then the word names composure.","whyCN":"当被克制的冲动是愤怒时，克制最容易被看见，这时这个词命名的是镇定。"},{"no":"03","title":"Self-regulation studied in psychology","titleCN":"心理学研究的自我调节","definition":"in psychology, the capacity to regulate one's own attention, emotion and behaviour","definitionCN":"心理学中，调节自身注意、情绪与行为的能力","example":"The study links self-control to long-term outcomes.","exampleCN":"这项研究把自我控制与长期结果联系起来。","why":"Psychology treats the loop as a capacity that can be trained and measured.","whyCN":"心理学把这个环看成一种可以训练、可以测量的能力。"},{"no":"04","title":"Resisting a temptation","titleCN":"抵挡诱惑","definition":"the act of refusing something attractive that is within reach","definitionCN":"拒绝某件近在手边、颇具吸引力之物的行为","example":"Self-control at the checkout is hardest of all.","exampleCN":"在收银台前的自制最难。","why":"The general capacity is tested at particular points, and the word can name the test itself.","whyCN":"一般的能力在具体节点上受检验，这个词也可以命名那次检验。"},{"no":"05","title":"Discipline in performance","titleCN":"技艺上的自律","definition":"the discipline that keeps a performer within a chosen technique","definitionCN":"使表演者留在既定技艺范围里的自律","example":"Her self-control on stage never shows in the playing.","exampleCN":"她在台上的自律从不在演奏中显露出来。","why":"Artistic restraint is the same holding back, applied to a technique rather than to a desire.","whyCN":"艺术上的克制是同一种拉住，只是对象是技艺而不是欲望。"},{"no":"06","title":"Moral or ascetic restraint","titleCN":"道德或苦修上的克制","definition":"the moral discipline of denying oneself permitted pleasures","definitionCN":"拒绝自己本可享受的乐趣的道德自律","example":"The rule was meant to teach self-control, not shame.","exampleCN":"这条规矩意在教人自律，而不是使人羞愧。","why":"Religious and moral traditions treat the loop as the training ground of character.","whyCN":"宗教与道德传统把这个环当作性格的训练场。"},{"no":"07","title":"A system controlling itself, in engineering","titleCN":"工程学中系统对自身的控制","definition":"in engineering, the regulation of a system by its own feedback rather than by an outside operator","definitionCN":"工程学中，系统靠自身反馈而非外部操作者来调节","example":"The thermostat gives the furnace a simple self-control.","exampleCN":"恒温器让锅炉具备一种简单的自控。","why":"The loop that runs in a person also runs in a machine: output is fed back to adjust input.","whyCN":"在人身上绕成环的东西，在机器里也绕成环：输出被送回以调整输入。"},{"no":"08","title":"Governing the self as a system","titleCN":"把自我当作系统来治理","definition":"the abstract idea of the self as both governor and governed","definitionCN":"把自我同时看成治理者与被治理者的抽象观念","example":"The essay treats self-control as a constitution written inside one mind.","exampleCN":"这篇文章把自制看成一部位于单一心灵内部的宪法。","why":"Once the loop is seen whole, it becomes a model of the self as a governed system.","whyCN":"当这个环被整体看见时，它就成了「自我作为被治理系统」的模型。"}],"etymology":{"intro":{"en":"Self-control joins the native pronoun self with control, a word borrowed from Medieval Latin contrarotulus, a counter-roll kept for checking accounts. Dates are approximate.","cn":"self-control 把本族语代词 self 与 control 组合起来；control 借自中世纪拉丁语 contrarotulus，指用来核对账目的对照卷。年代均为约数。"},"items":[{"era":"OLD ENGLISH SELF","en":"Self began as a pronoun and adjective meaning the same person, and it has always been able to form compounds with nouns.","cn":"self 起初是代词兼形容词，指「同一个人」，一直都能与名词构成复合词。"},{"era":"MEDIEVAL LATIN CONTRAROTULUS","en":"Contrarotulus joined contra meaning against and rotulus meaning a roll, and it named a duplicate roll kept to check an account.","cn":"contrarotulus 由 contra「对着」与 rotulus「卷」构成，指用来核对账目的副本卷。"},{"era":"FRENCH CONTROLLE","en":"The word passed through Old French as contrerolle and into English as control, first meaning a check or a register.","cn":"这个词经古法语 contrerolle 进入英语作 control，最初指核对或登记册。"},{"era":"ENGLISH CONTROL","en":"By the sixteenth century control had widened from checking a record to directing or restraining anything.","cn":"到十六世纪，control 已从核对记录扩展到指挥或约束任何事情。"},{"era":"EIGHTEENTH-CENTURY COMPOUND","en":"Self-control appeared in the early eighteenth century as the power of controlling one's own actions and desires.","cn":"self-control 在十八世纪初出现，指控制自身行为与欲望的力量。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation for the compound is not fixed, and the deeper origin of rotulus beyond its diminutive form is unsettled.","cn":"来源不确定：这个复合词的最早英语书证年代无定论；rotulus 在指小形式之外的更深来源亦无定论。"}]},"similar":{"note":{"en":"The first group shares wording with self-control or its second element; the second holds nouns for holding back. The self- element is what separates the first entry from the rest.","cn":"第一组与 self-control 或其第二部分共用词形；第二组是表示克制的名词。self- 这一部分正是第一条与其余各条的分界。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"self-restraint","ipa":"/ˌself rɪˈstreɪnt/","tag":"near twin","definition":"Holding oneself back from action; it stresses not doing something, while self-control also covers keeping order and staying calm.","definitionCN":"拉住自己不去行动；它强调「不做」，而 self-control 还涵盖维持秩序与保持镇定。"},{"word":"self-controlled","ipa":"/ˌself kənˈtrəʊld/","tag":"same compound, adjective","definition":"The adjective describing a person who has self-control.","definitionCN":"描述具有自制力之人的形容词。"},{"word":"control","ipa":"/kənˈtrəʊl/","tag":"second element alone","definition":"Direction or restraint of something; without self- it usually points to power over other people or things.","definitionCN":"对某物的指挥或约束；不带 self- 时通常指对他者或他物的权力。"},{"word":"self-esteem","ipa":"/ˌself ɪˈstiːm/","tag":"same first element","definition":"The value one places on oneself; the self- is the same, but the second element concerns judgement, not restraint.","definitionCN":"一个人对自己的评价；self- 相同，但第二部分涉及判断，而不是克制。"}]},{"heading":"NEAR MEANING","entries":[{"word":"willpower","ipa":"/ˈwɪlpaʊə/","tag":"force of will","definition":"The strength of deliberate intention; self-control is the holding back, willpower is the force that does it.","definitionCN":"有意的决心所带的强度；self-control 是那个拉住的动作，willpower 是拉住它的力量。"},{"word":"discipline","ipa":"/dɪˈsɪplɪn/","tag":"trained order","definition":"Order produced by training or rule; self-control is the inner capacity, discipline often the outward habit.","definitionCN":"经由训练或规则产生的秩序；self-control 是内在能力，discipline 常指外在习惯。"},{"word":"composure","ipa":"/kəmˈpəʊʒə/","tag":"calm surface","definition":"A calm appearance under pressure; it covers the look of control rather than the whole capacity.","definitionCN":"压力下的平静外表；它涵盖的是控制的外观，而不是整套能力。"},{"word":"restraint","ipa":"/rɪˈstreɪnt/","tag":"holding back","definition":"The act or habit of holding back; it can also name an external limit, which self-control cannot.","definitionCN":"拉住自己的行为或习惯；它也能指外部限制，而 self-control 不能。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the two real halves of the compound, the real phrase family and the technical sense that keeps the same loop.","cn":"正常联想：这个复合词真实的两半、真实的搭配家族，以及保留同一个环的技术义。"},"normal":[{"en":"Self plus control: the same person is both the one who wants and the one who says no.","cn":"self 加 control：同一个人既是要的那个人，也是说不的那个人。"},{"en":"The family runs self-control, self-controlled, self-controlling and control.","cn":"同族词包括 self-control（自制）、self-controlled（有自制力的）、self-controlling（自我控制的）、control（控制）。"},{"en":"Fixed phrases mark the field: exercise self-control, lose self-control, a model of self-control.","cn":"固定搭配标出领域：运用自制力、失去自制、自制力的典范。"},{"en":"Control itself came from a counter-roll kept to check accounts, so the oldest image is a second record that catches an error.","cn":"control 本身来自用来核对账目的对照卷，因此最古老的画面是一份能查出错误的第二记录。"},{"en":"Engineering uses the same compound for a system that regulates itself by feedback.","cn":"工程学用同一个复合词指靠反馈自我调节的系统。"}],"abstract":[{"en":"Picture one hand closing over the other wrist.","cn":"想象一只手握住另一只手的腕子。"},{"en":"Picture a thermostat that turns the flame down without being asked.","cn":"想象一个不用人吩咐就把火调小的恒温器。"},{"en":"Picture a second ledger opened beside the first to catch a false entry.","cn":"想象在正账旁翻开第二本账，好查出记错的一笔。"}]},"examples":[{"en":"It took real self-control not to answer back.","cn":"忍住不顶嘴需要真正的自制力。"},{"en":"The training programme builds self-control in young athletes.","cn":"这个训练计划培养年轻运动员的自制力。"},{"en":"The valve gives the tank a measure of self-control.","cn":"这个阀门让储罐具备一定程度的自控。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「自我康戳」——自己把自己按住，不让手乱伸 → self-control 自制力","word":"self-control"},"root":"self 为本族语代词「自身」，control 借自中世纪拉丁语 contrarotulus「对照卷」= contra「对着」+ rotulus「卷」；两者在十八世纪组合成 self-control。","sensesIntro":{"en":"Eight senses follow one loop: the same person both wants and refuses, and that loop is then applied to anger, to psychology, to a single temptation, to technique, to morals, to a machine and finally to the self seen as a governed system.","cn":"八个义项沿同一个环展开：同一个人既想要又拒绝；这个环再依次用于愤怒、心理学、一次具体的诱惑、技艺、道德、机器，最后用于被看成被治理系统的自我。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand closing over the other wrist and pulling the reaching hand back.","cn":"核心意象：一只手握住另一只手的手腕，把已经伸出去的手拉回来。"},"chain":["DESIRE RISES","HAND CHECKED","IMPULSE HELD","COURSE KEPT","PATTERN TRAINED","SYSTEM GOVERNS ITSELF"],"branches":[{"senses":"01 · 04","en":"IMPULSE AND TEMPTATION: the general capacity is tested at one tempting object.","cn":"冲动与诱惑：一般的能力在一件诱人的东西上受检验。"},{"senses":"02 · 06","en":"COMPOSURE AND MORAL: holding back anger and denying a permitted pleasure use the same grip.","cn":"镇定与道德：压住怒气与拒绝本可享受的乐趣，用的是同一种握力。"},{"senses":"03 · 05","en":"REGULATION AND TECHNIQUE: psychology measures the loop, and performance keeps within it.","cn":"调节与技艺：心理学测量这个环，表演则留在环内。"},{"senses":"07","en":"MACHINE: feedback makes a system its own governor.","cn":"机器：反馈让系统成为自己的治理者。"},{"senses":"08","en":"SELF AS STATE: the whole loop becomes a constitution inside one mind.","cn":"自我如国：整个环变成一部写在单颗心里的宪法。"}]},"affixes":{"intro":{"en":"Self-control is a native pronoun joined to a borrowed noun, and each half can be read on its own.","cn":"self-control 是本族语代词加上借来的名词，两半都可以单独读。"},"latinIntro":{"en":"The second half comes from Medieval Latin contrarotulus, built on contra meaning against and rotulus meaning a roll; the same stock gives controller and the verb control.","cn":"后半部分来自中世纪拉丁语 contrarotulus，由 contra「对着」与 rotulus「卷」构成；同一词干衍生 controller 与动词 control。"},"items":[{"word":"self","structure":"self (native pronoun and noun, the same person)","meaning":"one's own person","meaningCN":"自身；同一个人","example":"The pronoun has formed compounds since Old English.","exampleCN":"这个代词自上古英语以来就能构成复合词。"},{"word":"contra-","structure":"contra- (Latin prefix, against)","meaning":"against; opposite","meaningCN":"对着；相反","example":"The prefix also appears in contrast and contradict.","exampleCN":"这个前缀也出现在 contrast（对照）与 contradict（反驳）里。"},{"word":"rotulus","structure":"rotulus (Medieval Latin noun, a roll)","meaning":"a roll of writing","meaningCN":"一卷文书","example":"The noun is a diminutive of rota, a wheel.","exampleCN":"这个名词是 rota「轮子」的指小形式。"},{"word":"contrarotulus","structure":"contra- + rotulus","meaning":"a counter-roll kept for checking","meaningCN":"用来核对的对照卷","example":"The clerk compared the two rolls.","exampleCN":"书吏把两卷记录对照起来。"},{"word":"control","structure":"contrarotulus through French contrerolle","meaning":"to check, then to direct or restrain","meaningCN":"核对，后指指挥或约束","example":"She controls the budget.","exampleCN":"她掌管预算。"},{"word":"controller","structure":"control + -er (agent or instrument)","meaning":"one who or that which controls","meaningCN":"控制者；控制器","example":"The controller adjusts the flow.","exampleCN":"控制器调节流量。"},{"word":"self-control","structure":"self + control","meaning":"control exercised on oneself","meaningCN":"施加于自身的控制","example":"Self-control can be trained.","exampleCN":"自制力可以训练。"},{"word":"self-controlled","structure":"self-control + -ed (having the quality)","meaning":"having self-control","meaningCN":"具有自制力的","example":"He remained self-controlled throughout.","exampleCN":"他始终保持着自制。"},{"word":"self-controlling","structure":"self-control + -ing (active adjective)","meaning":"acting to control oneself","meaningCN":"自我控制的","example":"The system is self-controlling.","exampleCN":"这个系统是自我控制的。"}],"latinEntries":[{"word":"contra","structure":"contra (Latin preposition and prefix, against)","meaning":"against, opposite","meaningCN":"对着；相反"},{"word":"rotulus","structure":"rotulus, rotuli (m., second declension, a roll)","meaning":"a roll of writing","meaningCN":"一卷文书"},{"word":"contrarotulus","structure":"contrarotulus, contrarotuli (m., second declension)","meaning":"a counter-roll for checking accounts","meaningCN":"用于核对账目的对照卷"},{"word":"rota","structure":"rota, rotae (f., first declension)","meaning":"a wheel","meaningCN":"轮子"}],"derivatives":[{"word":"self-controlled","structure":"self-control + -ed (possessing) → possessing the ability to hold oneself back","meaning":"having self-control","meaningCN":"有自制力的"},{"word":"self-controlling","structure":"self-control + -ing (active) → keeping oneself under control","meaning":"regulating itself","meaningCN":"自我控制的"},{"word":"control","structure":"contrarotulus through French → a check, then direction","meaning":"direction or restraint","meaningCN":"控制；管理"},{"word":"controller","structure":"control + -er (agent) → the one or the device that regulates","meaning":"a regulating person or device","meaningCN":"控制者；控制器"}]}},{"word":"restraint","ipa_uk":"/rɪˈstreɪnt/","ipa_us":"/rɪˈstreɪnt/","definition_zh":"克制；自制；限制；约束；[法律] 限制措施；[医] 身体约束；[艺术] 含蓄","definition_en":"the act of holding something back, or a limit placed on action","core_image":"一根绷紧的绳把鼓起的帆角拉住，风再大也鼓不成整面","scene":"风暴中的码头上，水手把松脱的缆绳重新系紧，A second rope was added as a restraint on the swinging boom.","sceneCN":"这里 restraint 指「起限制作用的约束物」（第 3 个义项：限制或约束之物）；句意为又加了一根绳，作为对摆动帆桁的约束。图中可辨识物件：缆绳、帆桁、风暴、码头。","pos":[{"tag":"n.","zh":"克制；自制；限制；约束；约束装置；含蓄"}],"collocations":[{"phrase":"exercise restraint","zh":"保持克制"},{"phrase":"with restraint","zh":"有节制地"},{"phrase":"impose restraints","zh":"施加限制"},{"phrase":"restraint of trade","zh":"贸易限制（法律用语）"},{"phrase":"a restraint on","zh":"对……的约束"},{"phrase":"show restraint","zh":"表现出克制"}],"forms":[{"label":"复数","form":"restraints"},{"label":"动词（克制；约束）","form":"restrain"},{"label":"形容词（克制的）","form":"restrained"},{"label":"副词（克制地，较少用）","form":"restrainedly"},{"label":"名词（施加约束者，较少用）","form":"restrainer"}],"derivatives":[{"word":"restrain","pos":"v.","zh":"克制；约束；阻止"},{"word":"restrained","pos":"adj.","zh":"克制的；有节制的"},{"word":"restraining","pos":"adj.","zh":"起约束作用的"},{"word":"restrict","pos":"v.","zh":"限制（同源词）"}],"senses":[{"no":"01","title":"The act of holding something back","titleCN":"拉住某物的动作","definition":"the act of holding something back or keeping it under control","definitionCN":"把某物拉住或置于控制之下的动作","example":"The restraint of the crowd took a full hour.","exampleCN":"控制住人群花了整整一小时。","why":"The Latin verb means to draw tight, so restraint begins as a cord pulled against movement.","whyCN":"这个拉丁动词意为「拉紧」，因此克制最初是一根绷紧的绳对抗运动。"},{"no":"02","title":"Self-discipline in one's own conduct","titleCN":"对自己行为的自律","definition":"the quality of controlling one's own desires or behaviour","definitionCN":"控制自身欲望或行为的品质","example":"She spoke of the case with restraint.","exampleCN":"她谈起这件事时很克制。","why":"The cord is turned inward, and the movement held back is one's own impulse.","whyCN":"绳子转向内部，被拉住的是自己的冲动。"},{"no":"03","title":"A limit placed on action","titleCN":"施加于行动的限制","definition":"a rule or measure that limits what someone may do","definitionCN":"限定某人可以做什么的规则或措施","example":"A second rope was added as a restraint on the swinging boom.","exampleCN":"又加了一根绳，作为对摆动帆桁的约束。","why":"A limit is a rope on conduct, and the same word names the rope and the rule.","whyCN":"限制就是加在行为上的绳，同一个词既命名绳子，也命名规则。"},{"no":"04","title":"A device that holds a body","titleCN":"约束身体的装置","definition":"a physical device used to keep a person or an animal from moving freely","definitionCN":"用来阻止人或动物自由活动的实体装置","example":"The ambulance carried soft restraints for the stretcher.","exampleCN":"救护车上备有担架用的软约束带。","why":"The cord becomes an object, and the abstract act turns into a thing with buckles.","whyCN":"绳子变成物件，抽象的动作变成一条带扣的东西。"},{"no":"05","title":"A legal limit on an activity","titleCN":"法律上对某项活动的限制","definition":"a legal measure that limits a person's or a company's freedom","definitionCN":"限制个人或公司自由的法律措施","example":"The contract was challenged as a restraint of trade.","exampleCN":"这份合同因构成贸易限制而受到质疑。","why":"Law turns the cord into a rule that binds conduct whether or not anyone feels it.","whyCN":"法律把绳子变成一条规则，无论当事人是否感觉到，都捆住行为。"},{"no":"06","title":"Understatement in art or speech","titleCN":"艺术或言语中的含蓄","definition":"deliberate understatement in style or expression","definitionCN":"风格或表达上刻意保持的含蓄","example":"The film's strength lies in its restraint.","exampleCN":"这部电影的力量在于它的含蓄。","why":"In art, holding back becomes a value, because what is not shown can carry more weight.","whyCN":"在艺术里，拉住反而成了价值，因为没被展示的部分能承载更多分量。"},{"no":"07","title":"Medical restraint of a patient","titleCN":"医疗上对病人的约束","definition":"in medicine, the use of physical or chemical means to limit a patient's movement","definitionCN":"医学上用实体或药物手段限制病人活动","example":"Nurses log every use of restraint.","exampleCN":"护士会记录每一次使用约束措施的情况。","why":"Care and coercion share one word here, which is why its use is so closely regulated.","whyCN":"照护与强制在这里共用同一个词，这正是其使用受到严格规范的原因。"},{"no":"08","title":"A cord drawn tight, as the core image","titleCN":"作为核心意象的绷紧之绳","definition":"the underlying image of something drawn tight so that it cannot spread or surge","definitionCN":"把某物拉紧、使其无法张开或涌出的底层意象","example":"Every sense of restraint keeps one picture: a line pulled taut.","exampleCN":"restraint 的每个义项都保留同一幅画面：一条被拉紧的线。","why":"The whole family comes from a verb of drawing tight, and this sense states the image plainly.","whyCN":"整个词族都出自一个表示「拉紧」的动词，这个义项把这幅画面直接说出来。"}],"etymology":{"intro":{"en":"Restraint comes from Old French restraint, from restreindre, from Latin restringere, to draw tight or bind back. Dates are approximate.","cn":"restraint 来自古法语 restraint，出自 restreindre，再追溯到拉丁语 restringere「拉紧、向后捆住」。年代均为约数。"},"items":[{"era":"LATIN STRINGERE","en":"Stringere meant to draw tight, bind or graze. Its older Indo-European source is reconstructed as a root meaning tight or narrow, and that form is not recorded.","cn":"stringere 意为「拉紧、捆住、擦过」。它更早的印欧语来源被重构为一个表示「紧、窄」的词根，该词形没有记录。"},{"era":"LATIN RESTRINGERE","en":"Re- meaning back plus stringere produced restringere, to draw tight back, to bind or to restrict.","cn":"re-「向后」加 stringere 构成 restringere，意为「向后拉紧、捆住、限制」。"},{"era":"OLD FRENCH RESTREINDRE","en":"Old French restreindre carried the verb into English around 1300, and the noun restraint followed in the next century.","cn":"古法语 restreindre 约在十四世纪初把这个动词带入英语，名词 restraint 在其后一个世纪出现。"},{"era":"LEGAL AND MEDICAL USE","en":"Law used the noun for limits on trade and liberty, and medicine later used it for devices that limit a patient's movement.","cn":"法律用这个名词指对贸易与自由的限制，医学后来用它指限制病人活动的装置。"},{"era":"ARTISTIC SENSE","en":"Criticism adopted the word for understatement, where holding back is praised rather than merely required.","cn":"文艺批评采用这个词指含蓄，在那里「拉住」是被称赞的，而不只是被要求的。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation for the noun is not fixed, and the pre-Latin root of stringere is a reconstruction rather than a recorded word.","cn":"来源不确定：这个名词的最早英语书证年代无定论；stringere 在拉丁语之前的词根属重构形式，并非有记录的真实词。"}]},"similar":{"note":{"en":"The first group shares the Latin verb stringere but differs in prefix; the second holds nouns of limitation and moderation. One look-alike comes from a different root.","cn":"第一组共享拉丁动词 stringere，只是前缀不同；第二组是表示限制与节制的名词。有一个形似词来自不同词根。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"restrain","ipa":"/rɪˈstreɪn/","tag":"same root, verb","definition":"The verb that performs the holding back; restraint is the act, quality or device that results.","definitionCN":"执行拉住这个动作的动词；restraint 是结果的动作、性质或装置。"},{"word":"restrained","ipa":"/rɪˈstreɪnd/","tag":"same root, adjective","definition":"Describing someone or something that is held back or kept quiet in style.","definitionCN":"描述被拉住或在风格上保持克制的人或物。"},{"word":"restriction","ipa":"/rɪˈstrɪkʃn/","tag":"same root, limit","definition":"A rule that limits action; it is the limit itself, while restraint can also be the inner holding back.","definitionCN":"限定行动的规则；它是限制本身，而 restraint 也可以指内在的自我拉住。"},{"word":"constraint","ipa":"/kənˈstreɪnt/","tag":"same root, different prefix","definition":"Con- plus stringere: a pressure that compresses or forces; it stresses outside compulsion more than restraint does.","definitionCN":"con- 加 stringere：压紧或强迫的力量；比 restraint 更强调外来强迫。"}]},{"heading":"NEAR MEANING","entries":[{"word":"self-control","ipa":"/ˌself kənˈtrəʊl/","tag":"inner capacity","definition":"The ability to hold oneself back; restraint can name the act, the habit or an outside limit as well.","definitionCN":"拉住自己的能力；restraint 还可指动作、习惯或外部限制。"},{"word":"moderation","ipa":"/ˌmɒdəˈreɪʃn/","tag":"keeping within bounds","definition":"Avoiding extremes in amount or behaviour; restraint stresses the pull that keeps one back.","definitionCN":"在数量或行为上避免极端；restraint 强调把人拉回来的那股力。"},{"word":"limitation","ipa":"/ˌlɪmɪˈteɪʃn/","tag":"a boundary","definition":"A boundary on what is possible or allowed; restraint is the act or device that enforces it.","definitionCN":"对可能性或允许范围的边界；restraint 是执行这条边界的动作或装置。"},{"word":"discipline","ipa":"/dɪˈsɪplɪn/","tag":"trained order","definition":"Order produced by training; restraint is the holding back at a particular moment.","definitionCN":"由训练产生的秩序；restraint 是具体时刻的拉住。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the root of drawing tight, the real family and the phrases the noun keeps.","cn":"正常联想：真实的前缀、表示「拉紧」的词根、真实的同族词，以及这个名词实际常用的搭配。"},"normal":[{"en":"re- meaning back plus stringere meaning draw tight: a cord pulled backward against movement.","cn":"re-「向后」加 stringere「拉紧」：一根把运动向后拉住的绳。"},{"en":"The family runs restrain, restrained, restraining, restraint and restriction.","cn":"同族词包括 restrain（克制）、restrained（克制的）、restraining（起约束作用的）、restraint（克制；约束）、restriction（限制）。"},{"en":"Fixed phrases mark the field: exercise restraint, with restraint, restraint of trade, a restraint on.","cn":"固定搭配标出领域：保持克制、有节制地、贸易限制、对……的约束。"},{"en":"Constraint uses the same root with con- instead of re-, so the pressure comes from outside rather than from pulling back.","cn":"constraint 用同一词根但换成 con- 前缀，因此压力来自外部，而不是向后拉。"},{"en":"In art the word becomes praise: what is held back can be stronger than what is shown.","cn":"在艺术里这个词变成称赞：被拉住的部分可以比展示出来的更有力。"}],"abstract":[{"en":"Picture a rope pulled taut against a sail that wants to fill.","cn":"想象一根绳绷紧，拉着一面想要鼓起来的帆。"},{"en":"Picture a hand on a gate that would otherwise swing open.","cn":"想象一只手按在一扇本来会荡开的门上。"},{"en":"Picture a speaker who stops one sentence before the obvious ending.","cn":"想象一个人把话在显而易见的结尾之前停住。"}]},"examples":[{"en":"The government called for restraint on both sides.","cn":"政府呼吁双方保持克制。"},{"en":"The treaty imposed restraints on the size of the fleet.","cn":"这项条约对舰队规模施加了限制。"},{"en":"Her prose is admired for its restraint.","cn":"她的文笔因含蓄而受赞赏。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞士穿特」——把绳子穿紧、拉住在瑞士山道上不让人乱跑 → restraint 约束、克制","word":"restraint"},"root":"拉丁 restringere「向后拉紧、捆住」= re-「向后」+ stringere「拉紧、捆」；stringere 更早的印欧语词根被重构为表示「紧、窄」的形式。英语 restraint 经古法语进入。","sensesIntro":{"en":"Eight senses follow one taut cord: something is held back, the self is held back, a limit is set, a body is bound, law binds an activity, art holds its tongue, medicine binds a patient and finally the cord itself is named.","cn":"八个义项沿同一根绷紧的绳展开：拉住某物、拉住自己、设下限制、捆住身体、法律捆住某项活动、艺术收住话头、医学约束病人，最后命名那根绳本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a rope drawn tight against a sail corner, so that even a strong wind cannot fill the whole canvas.","cn":"核心意象：一根绳把帆角绷紧拉住，风再大也鼓不成整面帆。"},"chain":["CORD DRAWN TIGHT","PULL CHECKED","BODY HELD","LIMIT SET","STYLE QUIETED","ORDER KEPT"],"branches":[{"senses":"01 · 08","en":"THE CORD: the act of pulling back and the cord itself are the same image.","cn":"绳子：向后拉的动作与绳子本身是同一幅画面。"},{"senses":"02","en":"INWARD PULL: the cord is turned on one's own impulse.","cn":"向内的拉：绳子转向自己的冲动。"},{"senses":"03 · 05","en":"LIMIT: a measure and a law both shorten the rope of what may be done.","cn":"限制：一项措施与一条法律，都缩短了「可以做」的绳长。"},{"senses":"04 · 07","en":"BOUND BODY: a device and a medical order both keep a body from moving freely.","cn":"被捆的身体：装置与医疗指令都让身体不能自由活动。"},{"senses":"06","en":"QUIET STYLE: in art the held-back sentence carries the weight.","cn":"收住的风格：在艺术里，被拉住的那句话承载分量。"}]},"affixes":{"intro":{"en":"Restraint can be read from a Latin prefix and a verb of drawing tight that also build a large English family.","cn":"restraint 可以按一个拉丁前缀与一个表示「拉紧」的动词逐段读出，两者还构成一大族英语词。"},"latinIntro":{"en":"Latin stringere gives restrain, restriction, strict and stringent through related forms; re- adds the sense of pulling back.","cn":"拉丁语 stringere 通过相关形态衍生 restrain、restriction、strict 与 stringent；re- 加上「向后拉」的意思。"},"items":[{"word":"re-","structure":"re- (Latin prefix, back)","meaning":"back; again","meaningCN":"向后；再","example":"The prefix also appears in repel and return.","exampleCN":"这个前缀也出现在 repel（击退）与 return（返回）里。"},{"word":"stringere","structure":"stringere (Latin verb, to draw tight, bind)","meaning":"to draw tight; to bind","meaningCN":"拉紧；捆住","example":"Its stem survives in strict and stringent.","exampleCN":"它的词干留在 strict（严格的）与 stringent（严厉的）里。"},{"word":"restrain","structure":"re- + stringere (verb)","meaning":"to hold back, keep under control","meaningCN":"拉住；使受控制","example":"He restrained the dog.","exampleCN":"他把狗拉住。"},{"word":"restraint","structure":"restrain + -t (noun of the act)","meaning":"the act, quality or device of holding back","meaningCN":"拉住的动作、性质或装置","example":"She showed restraint.","exampleCN":"她表现出克制。"},{"word":"restrained","structure":"restrain + -ed (past participle as adjective)","meaning":"held back; kept quiet in style","meaningCN":"被拉住的；风格克制的","example":"The colours are restrained.","exampleCN":"色彩很克制。"},{"word":"restraining","structure":"restrain + -ing (active adjective)","meaning":"acting to hold something back","meaningCN":"起约束作用的","example":"A restraining order was issued.","exampleCN":"一份限制令被签发。"},{"word":"restriction","structure":"restrict + -ion (action noun)","meaning":"a limit on what may be done","meaningCN":"对可做之事的限制","example":"The restriction applies to imports.","exampleCN":"这项限制适用于进口。"},{"word":"constraint","structure":"con- (together, strongly) + stringere","meaning":"a compressing or forcing limit","meaningCN":"压紧或强迫性的限制","example":"Time was the main constraint.","exampleCN":"时间是最主要的限制。"},{"word":"strict","structure":"strictus (past participle of stringere)","meaning":"drawn tight, hence severe","meaningCN":"被拉紧的，因而严厉的","example":"The rules are strict.","exampleCN":"规则很严。"}],"latinEntries":[{"word":"stringere","structure":"stringere, strinxi, strictum (verb, third conjugation)","meaning":"to draw tight, bind, graze","meaningCN":"拉紧；捆住；擦过"},{"word":"restringere","structure":"restringere, restinxi, restrictum (verb, third conjugation)","meaning":"to draw back tight, restrict","meaningCN":"向后拉紧；限制"},{"word":"strictus","structure":"strictus, -a, -um (past participle of stringere)","meaning":"drawn tight, strict","meaningCN":"被拉紧的；严格的"},{"word":"restrictio","structure":"restrictio, restrictionis (f., third declension)","meaning":"a drawing back, a restriction","meaningCN":"拉回；限制"}],"derivatives":[{"word":"restrain","structure":"re- back + stringere draw tight → to pull a thing back from movement","meaning":"to hold back","meaningCN":"克制；约束"},{"word":"restrained","structure":"restrain + -ed (participial adjective) → kept back, hence quiet in style","meaning":"held back; understated","meaningCN":"克制的；含蓄的"},{"word":"restriction","structure":"restrict + -ion (action noun) → the act of drawing a boundary","meaning":"a limiting rule","meaningCN":"限制；限制措施"},{"word":"constraint","structure":"con- strongly + stringere draw tight + -t (noun) → a force that compresses","meaning":"an external compulsion","meaningCN":"外部强迫；约束"},{"word":"strict","structure":"stringere + past participle → drawn tight, hence severe","meaning":"severe, tightly regulated","meaningCN":"严格的"}]}},{"word":"restrain","ipa_uk":"/rɪˈstreɪn/","ipa_us":"/rɪˈstreɪn/","definition_zh":"克制；抑制；约束；阻止；拉住","definition_en":"to hold someone or something back from acting or moving","core_image":"一只手死死拽住缰绳，马的前蹄已经抬起却迈不出去","scene":"雨后的街道上，狗突然冲向马路，The owner restrained the dog at the kerb just in time.","sceneCN":"这里 restrain 指「用力拉住、不让某人某物冲出去」（第 1 个义项：用力拉住某人或某物）；句意为主人在路沿及时把狗拉住了。图中可辨识物件：缰绳、狗、路沿、湿地面。","pos":[{"tag":"vt.","zh":"克制；抑制；约束；阻止；拉住"}],"collocations":[{"phrase":"restrain oneself","zh":"克制自己"},{"phrase":"restrain from doing","zh":"克制住不做某事"},{"phrase":"restrain a smile","zh":"忍住笑"},{"phrase":"restrain an urge","zh":"抑制冲动"},{"phrase":"restrain the dog","zh":"拉住狗"},{"phrase":"be restrained from","zh":"被阻止做……"}],"forms":[{"label":"三单（he/she/it）","form":"restrains"},{"label":"过去式","form":"restrained"},{"label":"过去分词","form":"restrained"},{"label":"现在分词","form":"restraining"},{"label":"名词（克制；约束）","form":"restraint"},{"label":"形容词（克制的）","form":"restrained"},{"label":"名词（施加约束者，较少用）","form":"restrainer"}],"derivatives":[{"word":"restraint","pos":"n.","zh":"克制；约束；限制"},{"word":"restrained","pos":"adj.","zh":"克制的；有节制的"},{"word":"restraining","pos":"adj.","zh":"起约束作用的"},{"word":"restrainer","pos":"n.","zh":"施加约束者"}],"senses":[{"no":"01","title":"Hold a body back by force","titleCN":"用力把身体拉住","definition":"to hold a person or animal back so that it cannot move forward","definitionCN":"把一个人或动物拉住，使它不能向前","example":"The owner restrained the dog at the kerb.","exampleCN":"主人在路沿把狗拉住了。","why":"The Latin verb means to draw tight, so restraining begins as a physical pull on a body.","whyCN":"这个拉丁动词意为「拉紧」，因此克制最初是对身体的一次实体拉扯。"},{"no":"02","title":"Hold back an emotion or an impulse","titleCN":"压住情绪或冲动","definition":"to keep oneself from expressing a feeling or acting on an urge","definitionCN":"使自己不表露某种情绪，或不凭冲动行动","example":"She restrained a smile during the interview.","exampleCN":"面试时她忍住了笑。","why":"The cord is turned inward and the body held back is one's own.","whyCN":"绳子转向内部，被拉住的身体就是自己的身体。"},{"no":"03","title":"Prevent someone from doing something","titleCN":"阻止某人做某事","definition":"to stop another person from carrying out an action","definitionCN":"阻止另一个人实施某个行动","example":"The officers restrained him from entering the site.","exampleCN":"警员阻止他进入场地。","why":"A pull on one body can also stop another body, and the verb takes an object between the two.","whyCN":"拉住一具身体，也能拦住另一具身体，动词于是在两者之间加上了宾语。"},{"no":"04","title":"Keep a force or a growth within limits","titleCN":"把某种力量或增长控制在限度内","definition":"to keep something such as growth or spending within limits","definitionCN":"把增长、开支之类限制在一定范围内","example":"The bank restrained lending after the warning.","exampleCN":"警告发出后，银行收紧了放贷。","why":"An abstract force can be pulled back as if it were a body, so the verb extends to economics.","whyCN":"抽象的力量可以像身体一样被拉住，于是这个动词延伸到经济领域。"},{"no":"05","title":"Immobilize a patient in medicine","titleCN":"医疗上固定病人","definition":"in medicine, to limit a patient's movement for safety or treatment","definitionCN":"医学上为安全或治疗而限制病人的活动","example":"The nurses restrained the patient during the seizure.","exampleCN":"病人在发作期间，护士对其进行了约束。","why":"Care needs the body to stay still, and the oldest physical sense serves that need.","whyCN":"照护需要身体不动，最古老的实体义正好服务这一需要。"},{"no":"06","title":"Forbid an act by legal order","titleCN":"以法律命令禁止某行为","definition":"in law, to forbid someone by order from doing something","definitionCN":"在法律上以命令禁止某人做某事","example":"The court restrained the company from selling the shares.","exampleCN":"法院禁止这家公司出售这些股份。","why":"Law turns the physical pull into a command that binds at a distance.","whyCN":"法律把实体的拉扯变成一条能在远处生效的命令。"},{"no":"07","title":"Keep a style quiet","titleCN":"使风格保持收敛","definition":"to keep colours, words or effects from becoming too strong","definitionCN":"不让色彩、辞句或效果变得过于强烈","example":"The director restrained the colours to a grey range.","exampleCN":"导演把色彩收在灰调范围内。","why":"Holding back is also an aesthetic choice, and the verb can act on a palette rather than a body.","whyCN":"拉住也是一种审美选择，动词作用的可以是调色板，而不是身体。"},{"no":"08","title":"Draw the cord tight, as the core image","titleCN":"作为核心意象的拉紧绳子","definition":"the underlying image of pulling something taut so that it cannot surge forward","definitionCN":"把某物拉紧、使其无法向前涌出的底层意象","example":"To restrain is to keep a hand on the rope, whatever the rope is made of.","exampleCN":"所谓克制，就是无论那根绳是什么做的，手都不松开。","why":"All eight uses keep one gesture, and this sense names the gesture itself.","whyCN":"八种用法都保留同一个手势，这个义项命名的正是那个手势。"}],"etymology":{"intro":{"en":"Restrain comes from Old French restreindre, from Latin restringere, to draw tight back. Dates are approximate.","cn":"restrain 来自古法语 restreindre，再追溯到拉丁语 restringere「向后拉紧」。年代均为约数。"},"items":[{"era":"LATIN STRINGERE","en":"Stringere meant to draw tight, bind or graze. Its older Indo-European source is reconstructed as a root meaning tight or narrow, and that form is not recorded.","cn":"stringere 意为「拉紧、捆住、擦过」。它更早的印欧语来源被重构为一个表示「紧、窄」的词根，该词形没有记录。"},{"era":"LATIN RESTRINGERE","en":"Re- meaning back plus stringere produced restringere, to draw tight back, to bind or to keep within bounds.","cn":"re-「向后」加 stringere 构成 restringere，意为「向后拉紧、捆住、限制在范围内」。"},{"era":"OLD FRENCH RESTREINDRE","en":"Old French restreindre brought the verb into English around 1300, at first for holding a person or animal back.","cn":"古法语 restreindre 约在十四世纪初把这个动词带入英语，最初指把人或动物拉住。"},{"era":"EXTENDED USES","en":"Later English used the verb for holding back feelings, spending and legal acts, and the noun restraint followed.","cn":"后来的英语用这个动词指压住情绪、收紧开支与限制法律行为，名词 restraint 随后出现。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation is not fixed, and the pre-Latin root of stringere is a reconstruction rather than a recorded word.","cn":"来源不确定：英语最早书证年代无定论；stringere 在拉丁语之前的词根属重构形式，并非有记录的真实词。"}]},"similar":{"note":{"en":"The first group shares the Latin verb stringere but differs in prefix or form; the second holds verbs of holding back. Two look-alikes come from different roots.","cn":"第一组共享拉丁动词 stringere，只是前缀或形态不同；第二组是表示拉住的动词。有两个形似词来自不同词根。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"restraint","ipa":"/rɪˈstreɪnt/","tag":"same root, noun","definition":"The act, quality or device of holding back; restrain is the verb that performs it.","definitionCN":"拉住的动作、性质或装置；restrain 是执行它的动词。"},{"word":"restrict","ipa":"/rɪˈstrɪkt/","tag":"same root, boundary","definition":"To set a boundary on what may be done; restrain stresses the pull on a moving force.","definitionCN":"对可做之事设定边界；restrain 强调对运动之力的拉住。"},{"word":"retain","ipa":"/rɪˈteɪn/","tag":"different root","definition":"From re- plus tenere meaning to hold, so it means to keep something in place, not to pull it back from acting.","definitionCN":"来自 re- 加 tenere「握住」，意为把某物留在原处，而不是把它从行动中拉回。"},{"word":"refrain","ipa":"/rɪˈfreɪn/","tag":"different root","definition":"From re- plus frenum meaning a bridle, so it means to stop oneself, especially from doing something; the image is a horse's bit, not a rope.","definitionCN":"来自 re- 加 frenum「马辔」，意为管住自己，尤指不做某事；画面是马嚼子，而不是绳索。"}]},{"heading":"NEAR MEANING","entries":[{"word":"control","ipa":"/kənˈtrəʊl/","tag":"general direction","definition":"To direct or keep in order; restrain adds the note of a force that is actively pulling back.","definitionCN":"指挥或维持秩序；restrain 多了「有股力正在往回拉」的意思。"},{"word":"curb","ipa":"/kɜːb/","tag":"keep within limits","definition":"To keep something under control, especially something excessive; the image is a curb rein.","definitionCN":"把某物控制住，尤指过度之物；其形象是勒马的缰绳。"},{"word":"suppress","ipa":"/səˈpres/","tag":"press down","definition":"To put down by force, often something already active; restrain can act before the movement grows.","definitionCN":"用力量压下去，常针对已经活跃的东西；restrain 可以在动作变大之前就拉住。"},{"word":"hold back","ipa":"/həʊld ˈbæk/","tag":"the plain phrase","definition":"The everyday phrase for the same act; restrain is its formal single-word equivalent.","definitionCN":"同一动作的日常说法；restrain 是它正式的单字对应词。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the root of drawing tight, the real family and the phrases the verb keeps.","cn":"正常联想：真实的前缀、表示「拉紧」的词根、真实的同族词，以及这个动词实际常用的搭配。"},"normal":[{"en":"re- meaning back plus stringere meaning draw tight: to pull a thing back from where it wants to go.","cn":"re-「向后」加 stringere「拉紧」：把东西从它想去的地方拉回来。"},{"en":"The family runs restrain, restraint, restrained, restraining and restriction.","cn":"同族词包括 restrain（克制）、restraint（克制；约束）、restrained（克制的）、restraining（起约束作用的）、restriction（限制）。"},{"en":"Fixed phrases mark the field: restrain oneself, restrain from doing, restrain a smile, restrain an urge.","cn":"固定搭配标出领域：克制自己、克制住不做、忍住笑、抑制冲动。"},{"en":"Retain looks like restrain but comes from holding, not from drawing tight, so the two should be separated.","cn":"retain 看似与 restrain 同族，却来自「握住」而不是「拉紧」，两者应当分开。"},{"en":"Refrain also means holding back, but its image is a horse's bridle, not a rope.","cn":"refrain 也表示忍住，但它的画面是马辔，而不是绳索。"}],"abstract":[{"en":"Picture a hand wrapped twice around a reins strap.","cn":"想象一只手在缰绳上绕了两圈。"},{"en":"Picture a horse's front hoof lifted and held in the air.","cn":"想象马的前蹄已经抬起，却停在半空。"},{"en":"Picture a tap turned down to a thin thread of water.","cn":"想象水龙头被拧到只剩一线细流。"}]},"examples":[{"en":"He could hardly restrain his anger.","cn":"他几乎压不住怒火。"},{"en":"The police restrained the crowd from entering the building.","cn":"警察阻止人群进入大楼。"},{"en":"The company restrained hiring during the downturn.","cn":"公司在低迷期收紧了招聘。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「瑞士穿」——把缰绳穿紧一拉，马就跑不出去 → restrain 克制、约束","word":"restrain"},"root":"拉丁 restringere「向后拉紧、捆住」= re-「向后」+ stringere「拉紧、捆」；stringere 更早的印欧语词根被重构为表示「紧、窄」的形式。英语 restrain 经古法语进入。","sensesIntro":{"en":"Eight senses follow one pull: a body is held, an impulse is checked, a person is stopped, a force is kept within limits, a patient is immobilized, a court forbids, a style is quieted and finally the taut cord itself is named.","cn":"八个义项沿同一次拉扯展开：拉住身体、压住冲动、拦住一个人、把某种力量收在限度内、固定病人、由法庭禁止、让风格收敛，最后命名那根绷紧的绳。"},"semanticMap":{"core":{"en":"CORE IMAGE: one hand locked on a rein while the horse's front hoof hangs in the air.","cn":"核心意象：一只手死死拽住缰绳，马的前蹄悬在半空。"},"chain":["CORD IN HAND","BODY PULLED BACK","IMPULSE CHECKED","GROWTH HELD","ORDER ISSUED","STYLE QUIETED"],"branches":[{"senses":"01 · 08","en":"THE PULL: the physical grip and the abstract cord are one gesture.","cn":"拉：实体的握紧与抽象的绳是同一次动作。"},{"senses":"02 · 04","en":"INNER AND ECONOMIC: an urge and a growth rate are both forces that can be pulled back.","cn":"内心与经济：冲动与增长率都是可以被拉回的力。"},{"senses":"03 · 06","en":"STOPPING OTHERS: a hand stops a person, and a court stops an act at a distance.","cn":"拦住他人：手在近处拦住人，法庭在远处禁止行为。"},{"senses":"05","en":"MEDICAL HOLD: care keeps a body still for its own safety.","cn":"医疗固定：照护为安全让身体保持不动。"},{"senses":"07","en":"AESTHETIC HOLD: a palette is restrained as a body is restrained.","cn":"审美收束：调色板被收住，就像身体被拉住。"}]},"affixes":{"intro":{"en":"Restrain can be read from a Latin prefix and a verb of drawing tight that also build a large English family.","cn":"restrain 可以按一个拉丁前缀与一个表示「拉紧」的动词逐段读出，两者还构成一大族英语词。"},"latinIntro":{"en":"Latin stringere gives restrain, strict, stringent and restriction through related forms; re- adds the sense of pulling back.","cn":"拉丁语 stringere 通过相关形态衍生 restrain、strict、stringent 与 restriction；re- 加上「向后拉」的意思。"},"items":[{"word":"re-","structure":"re- (Latin prefix, back)","meaning":"back","meaningCN":"向后","example":"The prefix also appears in repel and return.","exampleCN":"这个前缀也出现在 repel（击退）与 return（返回）里。"},{"word":"stringere","structure":"stringere (Latin verb, to draw tight, bind)","meaning":"to draw tight; to bind","meaningCN":"拉紧；捆住","example":"Its stem survives in strict.","exampleCN":"它的词干留在 strict（严格的）里。"},{"word":"restrain","structure":"re- + stringere","meaning":"to hold back, keep under control","meaningCN":"拉住；使受控制","example":"He restrained the dog.","exampleCN":"他把狗拉住。"},{"word":"restraint","structure":"restrain + -t (noun of the act)","meaning":"the act, quality or device of holding back","meaningCN":"拉住的动作、性质或装置","example":"She showed restraint.","exampleCN":"她表现出克制。"},{"word":"restrained","structure":"restrain + -ed (past participle as adjective)","meaning":"held back; quiet in style","meaningCN":"被拉住的；风格克制的","example":"The colours are restrained.","exampleCN":"色彩很克制。"},{"word":"restraining","structure":"restrain + -ing (active adjective)","meaning":"acting to hold something back","meaningCN":"起约束作用的","example":"A restraining order was issued.","exampleCN":"一份限制令被签发。"},{"word":"restrict","structure":"re- + strictus (drawn tight), a related formation","meaning":"to set bounds on something","meaningCN":"给某物设定边界","example":"The rule restricts access.","exampleCN":"这条规则限制进入。"},{"word":"strict","structure":"strictus (past participle of stringere)","meaning":"drawn tight, hence severe","meaningCN":"被拉紧的，因而严厉的","example":"The rules are strict.","exampleCN":"规则很严。"},{"word":"constrain","structure":"con- (strongly) + stringere","meaning":"to force or confine","meaningCN":"强迫；约束","example":"Lack of time constrained the plan.","exampleCN":"时间不足限制了这个计划。"}],"latinEntries":[{"word":"stringere","structure":"stringere, strinxi, strictum (verb, third conjugation)","meaning":"to draw tight, bind","meaningCN":"拉紧；捆住"},{"word":"restringere","structure":"restringere, restinxi, restrictum (verb, third conjugation)","meaning":"to draw back tight","meaningCN":"向后拉紧"},{"word":"strictus","structure":"strictus, -a, -um (past participle of stringere)","meaning":"drawn tight, strict","meaningCN":"被拉紧的；严格的"},{"word":"restrictio","structure":"restrictio, restrictionis (f., third declension)","meaning":"a drawing back, a restriction","meaningCN":"拉回；限制"}],"derivatives":[{"word":"restraint","structure":"restrain + -t (action noun) → the result of pulling back","meaning":"the act or device of holding back","meaningCN":"克制；约束"},{"word":"restrained","structure":"restrain + -ed (participial adjective) → kept back, hence quiet","meaning":"held back; understated","meaningCN":"克制的；含蓄的"},{"word":"restraining","structure":"restrain + -ing (active adjective) → acting to hold back","meaning":"serving to limit","meaningCN":"起约束作用的"},{"word":"restrainer","structure":"restrain + -er (agent) → the one or the thing that holds back","meaning":"a person or device that restrains","meaningCN":"约束者；约束装置"},{"word":"restriction","structure":"restrict + -ion (action noun) → the setting of a boundary","meaning":"a limiting rule","meaningCN":"限制"}]}},{"word":"disciplined","ipa_uk":"/dɪˈsɪplɪnd/","ipa_us":"/dɪˈsɪplɪnd/","definition_zh":"有纪律的；自律的；训练有素的；有条理的","definition_en":"trained to follow rules and to control one's own behaviour","core_image":"一队人踏着完全相同的步幅走过操场，鞋跟落地声只响成一下","scene":"军训场上，整排人踏着同一节拍，The disciplined squad moved as one line across the field.","sceneCN":"这里 disciplined 指「训练有素、守纪律的」（第 1 个义项：受过训练并遵守规则的）；句意为这支有纪律的队伍像一条线一样穿过场地。图中可辨识物件：队列、军帽、操场白线、节拍鼓。","pos":[{"tag":"adj.","zh":"有纪律的；自律的；训练有素的；有条理的"}],"collocations":[{"phrase":"disciplined approach","zh":"有条理的方法"},{"phrase":"disciplined team","zh":"有纪律的团队"},{"phrase":"highly disciplined","zh":"高度自律的"},{"phrase":"disciplined mind","zh":"训练有素的头脑"},{"phrase":"disciplined spending","zh":"有节制的开支"},{"phrase":"remain disciplined","zh":"保持自律"}],"forms":[{"label":"原级","form":"disciplined"},{"label":"比较级","form":"more disciplined"},{"label":"最高级","form":"most disciplined"},{"label":"名词（纪律；学科）","form":"discipline"},{"label":"动词（训练；惩戒）","form":"discipline"},{"label":"形容词（纪律的）","form":"disciplinary"},{"label":"名词（严格执行纪律者）","form":"disciplinarian"}],"derivatives":[{"word":"discipline","pos":"n./v.","zh":"纪律；学科；训练；惩戒"},{"word":"disciplinary","pos":"adj.","zh":"纪律的；惩戒的"},{"word":"disciplinarian","pos":"n.","zh":"严格执行纪律者"},{"word":"undisciplined","pos":"adj.","zh":"缺乏纪律的"}],"senses":[{"no":"01","title":"Trained to follow rules","titleCN":"受训练而遵守规则","definition":"trained to obey rules and keep order","definitionCN":"经过训练而服从规则、维持秩序","example":"The disciplined squad moved as one line.","exampleCN":"这支有纪律的队伍像一条线一样行进。","why":"The Latin base names instruction given to a learner, so a disciplined person is one shaped by teaching.","whyCN":"这个拉丁词干命名的是给学习者的一套教导，因此有纪律的人是被教导塑造过的人。"},{"no":"02","title":"Self-controlled in habits","titleCN":"习惯上能自我克制","definition":"able to control one's own desires and keep to a plan","definitionCN":"能够控制自身欲望并坚持计划","example":"She is disciplined about early nights.","exampleCN":"她在早睡这件事上很自律。","why":"Instruction is only half the work; the learner must also hold the line when no one is watching.","whyCN":"教导只是一半，学习者还必须在无人监督时守住这条线。"},{"no":"03","title":"Orderly and methodical in work","titleCN":"工作上有条理","definition":"carried out in an orderly and methodical way","definitionCN":"以有秩序、有章法的方式完成","example":"The research followed a disciplined method.","exampleCN":"这项研究遵循一套有条理的方法。","why":"A method is a rule of procedure, and disciplined work keeps to it even when shortcuts appear.","whyCN":"方法就是一套程序规则，有条理的工作即使遇到捷径也守住它。"},{"no":"04","title":"Strictly organized as a group","titleCN":"作为团体被严格组织","definition":"of a group, organized and controlled with strict order","definitionCN":"指团体以严格的秩序被组织与控制","example":"A disciplined unit wastes no time on confusion.","exampleCN":"一支有纪律的队伍不会把时间浪费在混乱上。","why":"Many bodies moving as one require each member to hold the same line.","whyCN":"许多身体像一具那样移动，需要每个成员守住同一条线。"},{"no":"05","title":"Trained within a field of study","titleCN":"在某一学科内受过训练","definition":"trained in the methods and standards of a particular field","definitionCN":"在某一领域的方法与标准上受过训练","example":"He has a disciplined historian's mind.","exampleCN":"他有一个受过史学训练的头脑。","why":"A discipline is also a field of study, and its practitioners are trained by its rules.","whyCN":"discipline 也指一个学科，从业者由该学科的规则训练出来。"},{"no":"06","title":"Keeping to tactics in sport","titleCN":"比赛中遵守战术","definition":"in sport, keeping to the agreed tactics under pressure","definitionCN":"在体育中，压力之下仍守住既定战术","example":"The team stayed disciplined even after the red card.","exampleCN":"即使在有人被红牌罚下之后，这支球队仍然保持战术纪律。","why":"Tactics are rules made for a contest, and discipline is obedience to them when emotion pushes otherwise.","whyCN":"战术是为比赛定的规则，纪律就是情绪想往别处走时仍服从这些规则。"},{"no":"07","title":"Following a rule of life","titleCN":"遵循一套生活规章","definition":"of a religious order, following a written rule of common life","definitionCN":"指修会遵循一套成文的共同生活规章","example":"The disciplined brothers rose before dawn.","exampleCN":"这些守规章的修士在天亮前起身。","why":"Monastic life formalized discipline into a rule, and the adjective describes those who keep it.","whyCN":"修道生活把纪律固定成一部规章，这个形容词描述遵守它的人。"},{"no":"08","title":"Shaped by instruction","titleCN":"被教导塑造过","definition":"the abstract quality of having been formed by teaching and practice","definitionCN":"经教导与练习而被塑造的抽象性质","example":"Every disciplined habit began as an awkward lesson.","exampleCN":"每一个自律的习惯，起初都是一堂别扭的课。","why":"The core image is a learner bent into a line, and this sense names the bending itself.","whyCN":"核心意象是一个学习者被扳成一条线，这个义项命名的正是那次扳直。"}],"etymology":{"intro":{"en":"Disciplined is discipline plus -ed; discipline comes from Latin disciplina, instruction, from discipulus, a learner. Dates are approximate.","cn":"disciplined 由 discipline 加 -ed 构成；discipline 来自拉丁语 disciplina「教导」，后者出自 discipulus「学习者」。年代均为约数。"},"items":[{"era":"LATIN DISCERE","en":"Discere meant to learn. Its older Indo-European source is generally reconstructed as a root meaning to show or point out, and that form is not recorded.","cn":"discere 意为「学习」。它更早的印欧语来源通常被重构为一个表示「显示、指出」的词根，该词形没有记录。"},{"era":"LATIN DISCIPULUS","en":"Discipulus meant a learner or pupil, and it stands behind the English word disciple as well as discipline.","cn":"discipulus 意为「学习者、学生」，它既是英语 discipline 的来源，也是 disciple 的来源。"},{"era":"LATIN DISCIPLINA","en":"Disciplina meant instruction, knowledge and orderly training, and it already covered both teaching and the order that teaching produced.","cn":"disciplina 意为「教导、知识、有秩序的训练」，已经兼指教学与教学所产生的秩序。"},{"era":"ENGLISH DISCIPLINE","en":"English took discipline in the fourteenth century for teaching and rule, and later for a field of study and for correction.","cn":"英语在十四世纪引入 discipline，指教导与规则，后来又指学科与惩戒。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the first English citation is not fixed, and the pre-Latin root of discere is a reconstruction rather than a recorded word.","cn":"来源不确定：英语最早书证年代无定论；discere 在拉丁语之前的词根属重构形式，并非有记录的真实词。"}]},"similar":{"note":{"en":"The first group shares the Latin stock of learning but differs in form; the second holds adjectives of order and self-control. One look-alike comes from a different verb of teaching.","cn":"第一组共享拉丁语「学习」的词干，只是形态不同；第二组是表示秩序与自制的形容词。有一个形似词来自另一个表示「教」的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"discipline","ipa":"/dɪˈsɪplɪn/","tag":"same root, noun and verb","definition":"The noun for training and order, and the verb for training or punishing; disciplined describes what results.","definitionCN":"名词指训练与秩序，动词指训练或惩戒；disciplined 描述由此形成的结果。"},{"word":"disciplinary","ipa":"/dɪˈsɪplɪnəri/","tag":"same root, adjective","definition":"Relating to rules or punishment, as in a disciplinary hearing; it describes procedure, not a person's habit.","definitionCN":"与规则或惩戒有关，如纪律听证；它描述程序，而不是人的习惯。"},{"word":"disciple","ipa":"/dɪˈsaɪpl/","tag":"same root, person","definition":"A learner or follower, from the same Latin word for pupil; it names the person being taught, not the order taught.","definitionCN":"学习者或追随者，来自同一个表示学生的拉丁词；它命名被教的人，而不是所教的秩序。"},{"word":"docile","ipa":"/ˈdəʊsaɪl/","tag":"different root","definition":"From Latin docere meaning to teach, not discere meaning to learn; it means easy to manage rather than trained by rule.","definitionCN":"来自拉丁语 docere「教」，而非 discere「学」；意为易管教的，而不是受规则训练的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"self-controlled","ipa":"/ˌself kənˈtrəʊld/","tag":"inner grip","definition":"Able to hold back one's own impulses; disciplined adds the layer of training and rule.","definitionCN":"能拉住自己的冲动；disciplined 又加上训练与规则这一层。"},{"word":"orderly","ipa":"/ˈɔːdəli/","tag":"arranged well","definition":"Neatly arranged or behaving without disorder; it describes the surface, while disciplined names the training behind it.","definitionCN":"排列整齐或行为不混乱；它描述表面，disciplined 命名其背后的训练。"},{"word":"methodical","ipa":"/məˈθɒdɪkl/","tag":"following a method","definition":"Working by a fixed method; disciplined can also refer to conduct and to a whole group.","definitionCN":"按固定方法工作；disciplined 还可以指品行与整个团体。"},{"word":"strict","ipa":"/strɪkt/","tag":"tightly ruled","definition":"Enforcing rules tightly; it describes the rule or the ruler, while disciplined describes the one who keeps them.","definitionCN":"严格执行规则；它描述规则或执行者，disciplined 描述遵守规则的人。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real learner root, the real family, the real phrases and the field sense that grew from training.","cn":"正常联想：真实的「学习者」词根、真实的同族词、真实的搭配，以及从训练生长出来的学科义。"},"normal":[{"en":"The base word for learner gives both disciple and discipline: the one taught and the teaching.","cn":"表示学习者的基础词同时给出 disciple 与 discipline：被教的人与所教的内容。"},{"en":"The family runs discipline, disciplined, disciplinary, disciplinarian and undisciplined.","cn":"同族词包括 discipline（纪律）、disciplined（有纪律的）、disciplinary（纪律的）、disciplinarian（严格执行纪律者）、undisciplined（缺乏纪律的）。"},{"en":"Fixed phrases mark the field: disciplined approach, disciplined team, disciplined spending.","cn":"固定搭配标出领域：有条理的方法、有纪律的团队、有节制的开支。"},{"en":"A discipline is also a field of study, so a disciplined mind is one trained by a subject.","cn":"discipline 也指学科，因此「训练有素的头脑」是被某一学科训练过的头脑。"},{"en":"Docile looks close but comes from teaching, not learning, so the roots differ.","cn":"docile 看似相近，却来自「教」而不是「学」，词根并不相同。"}],"abstract":[{"en":"Picture a line of marchers whose heels strike the ground as one sound.","cn":"想象一队行者的鞋跟落地，只响成一声。"},{"en":"Picture a notebook whose margins are all ruled to the same width.","cn":"想象一本笔记，每页边距都一样宽。"},{"en":"Picture a clock wound at the same hour every night.","cn":"想象一只每晚同一时刻上弦的钟。"}]},"examples":[{"en":"She kept a disciplined routine through the winter.","cn":"整个冬天她都保持着有规律的作息。"},{"en":"The most disciplined teams win the close games.","cn":"最有纪律的队伍赢下比分接近的比赛。"},{"en":"His disciplined reading shaped the book.","cn":"他有条理的阅读塑造了这本书。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「弟子普林」——弟子们排好队、按同一节拍走 → disciplined 有纪律的","word":"disciplined"},"root":"拉丁 disciplina「教导、有秩序的训练」出自 discipulus「学习者」，再追溯到 discere「学习」；discere 更早的印欧语词根通常被重构为表示「显示、指出」的形式。英语 discipline 经古法语进入。","sensesIntro":{"en":"Eight senses follow one learner bent into a line: rules taught, habits held, work ordered, a group aligned, a field mastered, tactics kept, a rule of life followed and finally the shaping itself.","cn":"八个义项沿同一个被扳成一条线的学习者展开：被教的规则、守住的习惯、有条理的工作、对齐的队伍、掌握的学科、守住的战术、遵循的生活规章，最后是那一次塑造本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line of marchers whose heels hit the ground at the same instant.","cn":"核心意象：一队行者的鞋跟在同一瞬间落地。"},"chain":["RULE GIVEN","LESSON LEARNED","HABIT FORMED","LINE KEPT","WORK ORDERED","SELF SHAPED"],"branches":[{"senses":"01 · 02","en":"RULE AND SELF: outer instruction becomes an inner grip.","cn":"规则与自我：外在的教导变成内在的握力。"},{"senses":"03 · 05","en":"WORK AND FIELD: a method and a subject both train the same mind.","cn":"工作与学科：方法与学科训练的是同一个头脑。"},{"senses":"04 · 06","en":"GROUP AND TACTICS: many bodies keep one line under pressure.","cn":"团体与战术：许多身体在压力下守住同一条线。"},{"senses":"07","en":"RULE OF LIFE: a religious order writes the line down.","cn":"生活规章：修会把这条线写成文字。"},{"senses":"08","en":"SHAPING: the learner is bent to the line, and that bend is the word's core.","cn":"塑造：学习者被扳向那条线，这次扳直就是这个词的核心。"}]},"affixes":{"intro":{"en":"Disciplined is a noun base plus a participle ending, and the base goes back to a Latin word for a learner.","cn":"disciplined 是一个名词基础加分词词尾，而这个基础可追到拉丁语中表示「学习者」的词。"},"latinIntro":{"en":"Latin discere gives disciple, discipline and disciplined; the ending -ed turns the noun into a description of someone trained.","cn":"拉丁语 discere 衍生 disciple、discipline 与 disciplined；词尾 -ed 把名词变成对受过训练者的描述。"},"items":[{"word":"discere","structure":"discere (Latin verb, to learn)","meaning":"to learn","meaningCN":"学习","example":"Its family includes disciple and discipline.","exampleCN":"它的词族包括 disciple（门徒）与 discipline（纪律）。"},{"word":"discipulus","structure":"discipulus (Latin noun, learner)","meaning":"a learner; a pupil","meaningCN":"学习者；学生","example":"The word also gives English disciple.","exampleCN":"这个词也是英语 disciple 的来源。"},{"word":"disciplina","structure":"discipulus + -ina (abstract noun)","meaning":"instruction, ordered training","meaningCN":"教导；有秩序的训练","example":"The noun covered both teaching and order.","exampleCN":"这个名词兼指教学与秩序。"},{"word":"discipline","structure":"disciplina through Old French","meaning":"training, rule, a field of study","meaningCN":"训练；规则；学科","example":"Discipline makes the work possible.","exampleCN":"纪律让工作成为可能。"},{"word":"disciplined","structure":"discipline + -ed (having the quality)","meaning":"trained and self-controlled","meaningCN":"受过训练且能自制的","example":"The team stayed disciplined.","exampleCN":"这支队伍保持着纪律。"},{"word":"disciplinary","structure":"discipline + -ary (relating to)","meaning":"relating to rules or punishment","meaningCN":"与规则或惩戒有关的","example":"The board opened a disciplinary case.","exampleCN":"委员会启动了纪律程序。"},{"word":"disciplinarian","structure":"discipline + -arian (one who upholds)","meaning":"one who enforces strict order","meaningCN":"严格执行纪律的人","example":"The coach was a known disciplinarian.","exampleCN":"这位教练以严格著称。"},{"word":"undisciplined","structure":"un- (not) + disciplined","meaning":"without training or order","meaningCN":"缺乏训练或秩序的","example":"The undisciplined line broke at once.","exampleCN":"那条缺乏纪律的队列立刻就散了。"},{"word":"disciple","structure":"discipulus (learner) through Latin and Old English","meaning":"a follower or pupil","meaningCN":"门徒；学生","example":"The disciple copied the master's method.","exampleCN":"门徒照着师父的方法做。"}],"latinEntries":[{"word":"discere","structure":"discere, didici (verb, third conjugation, no perfect participle in common use)","meaning":"to learn","meaningCN":"学习"},{"word":"discipulus","structure":"discipulus, discipuli (m., second declension)","meaning":"learner, pupil","meaningCN":"学习者；学生"},{"word":"disciplina","structure":"disciplina, disciplinae (f., first declension)","meaning":"instruction, training, order","meaningCN":"教导；训练；秩序"},{"word":"-ina","structure":"-ina (Latin noun suffix, abstract quality)","meaning":"abstract quality or activity","meaningCN":"抽象性质或活动"}],"derivatives":[{"word":"discipline","structure":"discipulus + -ina → the order produced by teaching","meaning":"training and rule","meaningCN":"纪律；学科"},{"word":"disciplinary","structure":"discipline + -ary (relating) → belonging to rule or punishment","meaning":"relating to discipline","meaningCN":"纪律的；惩戒的"},{"word":"disciplinarian","structure":"discipline + -arian (upholder) → one who insists on order","meaning":"a strict enforcer","meaningCN":"严格执行纪律者"},{"word":"undisciplined","structure":"un- (negation) + disciplined → not formed by training","meaning":"without order","meaningCN":"缺乏纪律的"},{"word":"disciple","structure":"discipulus (learner) → one who follows a teacher","meaning":"a pupil or follower","meaningCN":"门徒；学生"}]}},{"word":"perseverance","ipa_uk":"/ˌpɜːsəˈvɪərəns/","ipa_us":"/ˌpɜːrsəˈvɪrəns/","definition_zh":"坚持不懈；毅力；恒心；[神学] 圣徒的坚忍","definition_en":"the quality of continuing with something difficult until it is finished","core_image":"一个人在半山腰的石阶上坐下歇了几秒，又站起来继续往上走","scene":"登山道上，雨越下越大，Her perseverance brought her to the summit an hour after the others had turned back.","sceneCN":"这里 perseverance 指「面对困难仍持续下去的品质」（第 1 个义项：遇到困难仍坚持下去）；句意为她的毅力让她在别人折返一小时后登顶。图中可辨识物件：石阶、雨衣、折返路标、山顶旗。","pos":[{"tag":"n.","zh":"坚持不懈；毅力；恒心；坚忍"}],"collocations":[{"phrase":"sheer perseverance","zh":"纯粹的毅力"},{"phrase":"perseverance in","zh":"在……方面的坚持"},{"phrase":"with perseverance","zh":"凭借毅力"},{"phrase":"demonstrate perseverance","zh":"表现出毅力"},{"phrase":"perseverance pays off","zh":"坚持终有回报"},{"phrase":"dogged perseverance","zh":"顽强的坚持"}],"forms":[{"label":"原形（不可数名词）","form":"perseverance"},{"label":"动词（坚持）","form":"persevere"},{"label":"形容词（坚持不懈的）","form":"persevering"},{"label":"副词（坚持不懈地）","form":"perseveringly"},{"label":"形容词（坚忍的，较少用）","form":"perseverant"}],"derivatives":[{"word":"persevere","pos":"v.","zh":"坚持；不屈不挠"},{"word":"persevering","pos":"adj.","zh":"坚持不懈的"},{"word":"perseveringly","pos":"adv.","zh":"坚持不懈地"},{"word":"perseverant","pos":"adj.","zh":"坚忍的（较少用）"}],"senses":[{"no":"01","title":"Continuing despite difficulty","titleCN":"遇到困难仍持续下去","definition":"the quality of continuing with something difficult without giving up","definitionCN":"在困难面前仍持续做下去、不放弃的品质","example":"Her perseverance brought her to the summit.","exampleCN":"她的毅力把她带上了山顶。","why":"The Latin verb means to persist strictly, so the quality is a staying with a task rather than a single burst.","whyCN":"这个拉丁动词意为「严格地坚持到底」，因此这种品质是守着一件事，而不是一次爆发。"},{"no":"02","title":"Persistence in a chosen purpose","titleCN":"对既定目标的坚持","definition":"steady persistence in carrying out a chosen aim","definitionCN":"在执行既定目标时稳定持久地不松手","example":"He pursued the reform with quiet perseverance.","exampleCN":"他默默地坚持推进这项改革。","why":"An aim is chosen first, and perseverance is the long middle between choosing and arriving.","whyCN":"目标先被选定，毅力就是选定与抵达之间那段漫长的中间路程。"},{"no":"03","title":"Steady effort repeated over time","titleCN":"日复一日稳定的努力","definition":"the habit of steady effort continued over a long period","definitionCN":"长期保持稳定努力的习惯","example":"Daily perseverance matters more than talent.","exampleCN":"日复一日的坚持比天赋更重要。","why":"The word counts repeated acts rather than one heroic moment, so time is part of its meaning.","whyCN":"这个词计的是重复的行为，而不是一次英雄时刻，因此时间是其含义的一部分。"},{"no":"04","title":"Grit as measured in psychology","titleCN":"心理学中测量的坚毅","definition":"in psychology, the trait of sustained interest and effort toward long-term goals","definitionCN":"心理学中，对长期目标保持持续兴趣与努力的特质","example":"The scale scores perseverance alongside curiosity.","exampleCN":"这个量表在测量好奇心的同时也测量毅力。","why":"Psychology turns the moral virtue into a variable, but the long horizon stays the same.","whyCN":"心理学把这种道德德性变成变量，但那个长远的时间跨度没有变。"},{"no":"05","title":"Doggedness in the face of refusal","titleCN":"面对拒绝仍不罢休","definition":"the quality of continuing to ask or try after being refused","definitionCN":"在被拒绝之后仍继续请求或尝试的品质","example":"Her perseverance finally won the editor over.","exampleCN":"她的坚持最终打动了那位编辑。","why":"Refusal is the wall that makes the quality visible, and the word then shades into doggedness.","whyCN":"拒绝是让这种品质显形的墙，这时这个词的意味偏向「不罢休」。"},{"no":"06","title":"The perseverance of the saints in theology","titleCN":"神学中圣徒的坚忍","definition":"in theology, the doctrine that the elect continue in faith to the end","definitionCN":"神学上指蒙拣选者会持守信仰到底的教义","example":"The sermon took its text from the perseverance of the saints.","exampleCN":"这篇讲道以「圣徒的坚忍」为经文依据。","why":"Theology asks whether a long faithfulness can be guaranteed, and gives the virtue a doctrinal name.","whyCN":"神学追问长久的忠贞能否得到保证，于是给这种德性一个教义名称。"},{"no":"07","title":"Steadfastness in older usage","titleCN":"较早用法中的坚定","definition":"an older sense of constancy or steadfastness of character","definitionCN":"较古的义项，指性格上的恒定与坚定","example":"The old portrait praises patience and perseverance as one virtue.","exampleCN":"那幅古画把忍耐与坚定当作同一种德性来称赞。","why":"Before psychology measured it, the word named a settled character rather than a score.","whyCN":"在心理学测量它之前，这个词命名的是稳定的品格，而不是一个分数。"},{"no":"08","title":"Staying strict to the end","titleCN":"严格守到最后一刻","definition":"the core image of remaining strict and steady until the end is reached","definitionCN":"保持严格与稳定、直到终点为止的核心意象","example":"Perseverance is strictness that refuses to look at the clock.","exampleCN":"毅力就是一种拒绝看钟的严格。","why":"The Latin base carries a note of strictness, and the prefix carries through, so the virtue is strict to the end.","whyCN":"拉丁词干带着「严格」的意味，前缀带着「贯穿到底」，因此这种德性是严格到最后。"}],"etymology":{"intro":{"en":"Perseverance comes through Old French from Latin perseverantia, from perseverare, to persist, built on per- and severus. Dates are approximate.","cn":"perseverance 经古法语来自拉丁语 perseverantia，后者出自 perseverare「坚持」，由 per- 与 severus 构成。年代均为约数。"},"items":[{"era":"LATIN SEVERUS","en":"Severus meant grave, serious or strict. Its deeper origin is uncertain, so any earlier root proposed for it is a reconstruction.","cn":"severus 意为「严肃、庄重、严格」。它更深的来源不确定，因此为它提出的更早词根都属重构形式。"},{"era":"LATIN PERSEVERARE","en":"Per- meaning through or thoroughly plus severus produced perseverare, to continue strictly, to persist to the end.","cn":"per-「贯穿、彻底」加 severus 构成 perseverare，意为「严格地持续、坚持到底」。"},{"era":"LATIN PERSEVERANTIA","en":"The noun perseverantia named steadfastness and constancy, and it was used in both ordinary and religious Latin.","cn":"名词 perseverantia 指坚定与恒心，在普通拉丁语与宗教拉丁语中都有使用。"},{"era":"OLD FRENCH PERSEVERANCE","en":"Old French perseverance brought the noun into English in the fourteenth century as steadfastness in a course.","cn":"古法语 perseverance 在十四世纪把这个名词带入英语，指在一条道路上的坚定。"},{"era":"THEOLOGICAL SENSE","en":"Reformation theology gave the word a doctrinal sense, the perseverance of the saints, which is still its best-known specialized use.","cn":"宗教改革神学赋予这个词一个教义义，即「圣徒的坚忍」，至今仍是它最知名的专门用法。"},{"era":"UNCERTAIN DETAILS","en":"Source uncertain: the origin of severus is unsettled, and reference works give different first dates for the English noun.","cn":"来源不确定：severus 的来源无定论；各家参考资料对这个英语名词的首见年代说法也不一致。"}]},"similar":{"note":{"en":"The first group shares the Latin stock of perseverare but differs in form or meaning; the second holds nouns of sustained effort. One look-alike comes from a different root.","cn":"第一组共享拉丁语 perseverare 的词干，只是形态或意义不同；第二组是表示持续努力的名词。有一个形似词来自不同词根。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"persevere","ipa":"/ˌpɜːsəˈvɪə/","tag":"same root, verb","definition":"The verb meaning to keep going despite difficulty; perseverance is the quality it shows.","definitionCN":"意为遇到困难仍继续前进的动词；perseverance 是它所显现的品质。"},{"word":"persevering","ipa":"/ˌpɜːsəˈvɪərɪŋ/","tag":"same root, adjective","definition":"Describing a person who keeps going; it describes the person, while perseverance names the quality.","definitionCN":"描述坚持前行的人；它描述人，而 perseverance 命名品质。"},{"word":"severe","ipa":"/sɪˈvɪə/","tag":"same root, different branch","definition":"From the same Latin severus meaning strict or grave, but it describes harshness rather than persistence.","definitionCN":"来自同一个拉丁语 severus「严格、庄重」，但它描述严厉，而不是坚持。"},{"word":"severance","ipa":"/ˈsevərəns/","tag":"different origin","definition":"From Latin separare meaning to separate, not from severus; it means a cutting apart, almost the opposite of holding on.","definitionCN":"来自拉丁语 separare「分开」，而非 severus；意为切断分离，几乎与「守到底」相反。"}]},{"heading":"NEAR MEANING","entries":[{"word":"persistence","ipa":"/pəˈsɪstəns/","tag":"continuing anyway","definition":"Continuing in spite of opposition or difficulty; it can describe something annoying, while perseverance usually carries moral approval.","definitionCN":"不顾反对或困难继续下去；它可带惹人烦的意味，而 perseverance 通常带道德赞许。"},{"word":"tenacity","ipa":"/təˈnæsəti/","tag":"grip that will not let go","definition":"The quality of holding firmly to a purpose or an object; it stresses grip more than duration.","definitionCN":"牢牢抓住目标或物体的品质；它强调抓握，而不只是持续时间。"},{"word":"grit","ipa":"/ɡrɪt/","tag":"modern trait word","definition":"Courage and resolve sustained over long-term goals; it is the popular modern term, while perseverance is the older virtue word.","definitionCN":"在长期目标上保持勇气与决心；它是现代流行说法，perseverance 是更古老的德性词。"},{"word":"diligence","ipa":"/ˈdɪlɪdʒəns/","tag":"careful effort","definition":"Careful and steady effort in work; it stresses attention to the task rather than endurance through hardship.","definitionCN":"工作中仔细而稳定的努力；它强调对任务的用心，而不是在艰难中撑住。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: the real prefix, the root of strictness, the real family, the phrases the noun keeps and the doctrine that made it famous.","cn":"正常联想：真实的前缀、表示「严格」的词根、真实的同族词、这个名词实际常用的搭配，以及让它出名的教义。"},"normal":[{"en":"per- meaning through plus severus meaning strict: strict all the way through to the end.","cn":"per-「贯穿」加 severus「严格」：从头严格到尾。"},{"en":"The family runs persevere, perseverance, persevering, perseveringly and perseverant.","cn":"同族词包括 persevere（坚持）、perseverance（毅力）、persevering（坚持不懈的）、perseveringly（坚持不懈地）、perseverant（坚忍的）。"},{"en":"Fixed phrases mark the field: sheer perseverance, perseverance in, with perseverance, perseverance pays off.","cn":"固定搭配标出领域：纯粹的毅力、在……方面的坚持、凭借毅力、坚持终有回报。"},{"en":"Severe shares the same Latin root but went the other way, describing harshness rather than holding on.","cn":"severe 共享同一个拉丁词根，却走向另一边，描述严厉而不是守到底。"},{"en":"Severance looks close but comes from separating, so it means cutting apart rather than staying with a task.","cn":"severance 看似相近，却来自「分开」，意为切断而不是守着一件事。"}],"abstract":[{"en":"Picture a walker sitting on a stone step for ten seconds and then standing up again.","cn":"想象一名行者在石阶上坐十秒，然后重新站起来。"},{"en":"Picture a rope walked across one careful step at a time.","cn":"想象走绳索的人一步一步谨慎地往前挪。"},{"en":"Picture a candle relit on the tenth windy night.","cn":"想象一支蜡烛在第十个起风的夜里又被点亮。"}]},"examples":[{"en":"Perseverance, not luck, finished the project.","cn":"完成这个项目靠的是毅力，而不是运气。"},{"en":"Her perseverance in asking finally got an answer.","cn":"她一再坚持追问，终于得到了答复。"},{"en":"The old tradition speaks of the perseverance of the saints.","cn":"古老传统讲到「圣徒的坚忍」。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「怕死为了一人死」——再怕也不松手，硬撑到最后 → perseverance 毅力、坚持","word":"perseverance"},"root":"拉丁 perseverantia「坚定、恒心」出自 perseverare「坚持到底」= per-「贯穿」+ severus「严肃、严格」；severus 更早的来源不确定。英语 perseverance 经古法语进入。","sensesIntro":{"en":"Eight senses follow one long walk: the walker keeps going, keeps a purpose, repeats the step, is measured for grit, keeps asking after refusal, is promised faithfulness in theology, is praised as steadfast and finally stays strict to the end.","cn":"八个义项沿同一次长途行走展开：行者继续走、守住目标、重复脚步、被测量坚毅、被拒绝仍继续请求、在神学里被许诺忠贞、被称赞为坚定，最后严格守到终点。"},"semanticMap":{"core":{"en":"CORE IMAGE: a walker rests for a few seconds on a stone step and then stands up to climb again.","cn":"核心意象：行者在石阶上歇了几秒，又站起来继续往上爬。"},"chain":["SET THE AIM","HIT THE WALL","REFUSE TO STOP","REPEAT THE STEP","HOLD THE COURSE","ARRIVE AT THE END"],"branches":[{"senses":"01 · 03","en":"DIFFICULTY AND EFFORT: one hard moment and a long series of ordinary steps belong to the same virtue.","cn":"困难与努力：一个艰难时刻与一长串寻常脚步，属于同一种德性。"},{"senses":"02 · 06","en":"PURPOSE AND DOCTRINE: a chosen aim and a promised faithfulness both require holding the course.","cn":"目标与教义：选定的目标与被许诺的忠贞，都要求守住这条路。"},{"senses":"04 · 05","en":"MEASURED AND DOGGED: psychology scores the trait, and refusal makes it visible.","cn":"被测量与不罢休：心理学给这种特质打分，拒绝让它显形。"},{"senses":"07","en":"STEADFAST CHARACTER: older usage names a settled character rather than a score.","cn":"坚定的品格：较早用法命名的是稳定品格，而不是分数。"},{"senses":"08","en":"STRICT TO THE END: the prefix carries through and the root stays strict.","cn":"严格到底：前缀贯穿全程，词根保持严格。"}]},"affixes":{"intro":{"en":"Perseverance can be read from a Latin prefix, a root of strictness and a noun ending that also build a compact family.","cn":"perseverance 可以按一个拉丁前缀、一个表示「严格」的词根与一个名词词尾逐段读出，三者构成一小族词。"},"latinIntro":{"en":"Latin severus gives perseverare and perseverantia, and the same root also gives severe and severity, though along a harsher branch.","cn":"拉丁语 severus 衍生 perseverare 与 perseverantia，同一词根还衍生 severe 与 severity，只是走在更严厉的一支。"},"items":[{"word":"per-","structure":"per- (Latin prefix, through, thoroughly)","meaning":"through; thoroughly","meaningCN":"贯穿；彻底","example":"The prefix also appears in persist and pervade.","exampleCN":"这个前缀也出现在 persist（坚持）与 pervade（遍及）里。"},{"word":"severus","structure":"severus (Latin adjective, grave, strict)","meaning":"grave; strict","meaningCN":"严肃；严格","example":"The adjective also gives English severe.","exampleCN":"这个形容词也是英语 severe 的来源。"},{"word":"perseverare","structure":"per- + severus (verb)","meaning":"to continue strictly, to persist","meaningCN":"严格地持续；坚持","example":"They persevered through the winter.","exampleCN":"他们坚持度过了整个冬天。"},{"word":"perseverance","structure":"perseverare + -antia (abstract noun)","meaning":"the quality of persisting","meaningCN":"坚持的品质；毅力","example":"Perseverance finished the work.","exampleCN":"毅力把这项工作完成了。"},{"word":"persevere","structure":"per- + severus (verb form)","meaning":"to keep going despite difficulty","meaningCN":"遇困难仍继续","example":"She persevered with the lessons.","exampleCN":"她坚持上课。"},{"word":"persevering","structure":"persevere + -ing (active adjective)","meaning":"continuing steadily","meaningCN":"持续不懈的","example":"He is a persevering student.","exampleCN":"他是个坚持不懈的学生。"},{"word":"perseveringly","structure":"persevering + -ly (adverb ending)","meaning":"in a persistent manner","meaningCN":"以坚持不懈的方式","example":"She worked perseveringly.","exampleCN":"她坚持不懈地工作。"},{"word":"severe","structure":"severus through Old French","meaning":"grave, harsh, strict","meaningCN":"严肃的；严厉的","example":"The winter was severe.","exampleCN":"那个冬天很严酷。"},{"word":"severity","structure":"severe + -ity (abstract noun)","meaning":"the quality of being harsh","meaningCN":"严厉；严重","example":"The severity of the storm closed the road.","exampleCN":"风暴的严重程度让道路封闭。"}],"latinEntries":[{"word":"severus","structure":"severus, -a, -um (adjective)","meaning":"grave, serious, strict","meaningCN":"严肃的；庄重的；严格的"},{"word":"perseverare","structure":"perseverare, perseveravi, perseveratum (verb, first conjugation)","meaning":"to persist, continue strictly","meaningCN":"坚持；严格持续"},{"word":"perseverantia","structure":"perseverantia, perseverantiae (f., first declension)","meaning":"steadfastness, constancy","meaningCN":"坚定；恒心"},{"word":"-antia","structure":"-antia (Latin noun suffix, state or quality)","meaning":"state or quality","meaningCN":"状态或性质"}],"derivatives":[{"word":"persevere","structure":"per- through + severus strict → to stay strict all the way","meaning":"to keep going","meaningCN":"坚持；不屈不挠"},{"word":"persevering","structure":"persevere + -ing (active adjective) → continuing without giving up","meaning":"steadily persistent","meaningCN":"坚持不懈的"},{"word":"perseveringly","structure":"persevering + -ly (adverb) → in a persistent way","meaning":"without letting go","meaningCN":"坚持不懈地"},{"word":"perseverant","structure":"persevere + -ant (adjective) → holding firmly to a course","meaning":"steadfast","meaningCN":"坚忍的"},{"word":"severity","structure":"severe + -ity (abstract noun) → the quality of strictness","meaning":"harshness","meaningCN":"严厉；严重"}]}}]);
